import React from 'react';

export interface Quote {
  text: string;
  source: string;
  author: string;
}

export interface Level {
  name: string;
  tier: string; // The major rank group (e.g. 'Egg', 'Tadpole')
  minXP: number;
  color: string;
  shade: string;
  requiredWpm: number;
}

export interface GameState {
  xp: number;
  completedQuotes: number;
}

export interface TestResult {
  id: number;
  date: string;
  wpm: number;
  xpEarned: number;
  mode: GameMode;
}

export type MusicSource = 'NONE' | 'YOUTUBE' | 'SPOTIFY' | 'GENERATED' | 'SUNO';

export interface MusicConfig {
  source: MusicSource;
  presetId: string;
}

export type MechanicalSoundPreset = 'THOCK' | 'CLICKY' | 'BUBBLE' | 'TYPEWRITER';

export interface Settings {
  ghostEnabled: boolean;
  readAheadEnabled: boolean;
  sfxEnabled: boolean;
  mechanicalSoundEnabled: boolean; // Toggle for typing sounds
  mechanicalSoundPreset: MechanicalSoundPreset; // Sound profile
  ambientVolume: number; // Volume for GENERATED sources (Brown Noise, Piano, etc.)
  musicConfig: MusicConfig;
  themeId: string; // New: Selected Theme ID
}

export type GameMode = 'QUOTES' | 'HARDCORE' | 'FIX_MISTAKE' | 'STORY';

export enum GameStatus {
  IDLE = 'IDLE',
  PLAYING = 'PLAYING',
  COMPLETED = 'COMPLETED', // Successfully typed with 100% accuracy
  FAILED = 'FAILED', // Typed but mistakes were present at the end
}

export interface Theme {
  id: string;
  name: string;
  description: string;
  minTier: string; // Tier required to unlock (e.g. 'Tadpole')
  colors: {
    frog: Record<number, string>; // 50-900
    stone: Record<number, string>; // 50-900 (Used for neutrals)
    background: string;
  };
}

export interface Achievement {
  id: string;
  title: string;
  description: string;
  icon: React.ReactNode;
  category: 'SPEED' | 'STREAK' | 'VOLUME' | 'MASTERY' | 'HIDDEN';
  condition: (stats: { wpm: number; totalQuotes: number; maxStreak: number; currentStreak: number; mode: GameMode }) => boolean;
}

export interface NotificationItem {
  id: string;
  title: string;
  description: string;
  icon: React.ReactNode;
  type: 'ACHIEVEMENT' | 'UNLOCK' | 'INFO';
}

import { GoogleGenAI } from "@google/genai";

// Initialize the client
// NOTE: We assume process.env.API_KEY is available as per instructions.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const MODEL_NAME = 'gemini-2.5-flash';

export interface StoryGenerationResult {
  text: string;
  topic: string;
}

export const generateStorySegment = async (topic: string, previousContext: string = ""): Promise<StoryGenerationResult> => {
  try {
    let prompt = "";

    if (!previousContext) {
      // Start of story
      prompt = `Write the opening paragraph of a short story about "${topic}". 
      Constraints:
      1. Maximum 35 words.
      2. Do NOT use markdown (no bold, no italics).
      3. Simple, flowing sentence structure suitable for typing practice.
      4. Make it cozy and engaging.`;
    } else {
      // Continuation
      prompt = `Continue the following story: "${previousContext}".
      Write the NEXT paragraph.
      Constraints:
      1. Maximum 35 words.
      2. Do NOT use markdown.
      3. Maintain the tone.
      4. Do not repeat the previous text.`;
    }

    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
    });

    const text = response.text?.trim() || "The frog sat on the lily pad, wondering where the story went.";

    // Cleanup any accidental markdown or newlines
    const cleanText = text.replace(/[*_#]/g, '').replace(/\n/g, ' ').trim();

    return {
      text: cleanText,
      topic: topic
    };

  } catch (error) {
    console.error("Gemini API Error:", error);
    return {
      text: "The magical ink has run dry. Please check your connection or try again later.",
      topic: topic
    };
  }
};

