  quote: Quote;
  onComplete: (xpEarned: number, wpm: number, mistakes: string[], retryCount: number) => void;
  onFail: () => void;
  onMistake: (word?: string) => void;
  onRequestNewQuote: () => void;
  streak: number;
  ghostWpm: number;
  settings: Settings;
  gameMode: GameMode;
  onInteract?: () => void;
}

const TypingArea: React.FC<TypingAreaProps> = ({ 
  quote, 
  onComplete, 
  onFail, 
  onMistake,
  onRequestNewQuote,
  streak,
  ghostWpm,
  settings,
  gameMode,
  onInteract
}) => {
  const [input, setInput] = useState('');
