  onFail, 
  onMistake,
  onRequestNewQuote,
  streak,
  ghostWpm,
  settings,
  gameMode,
  onInteract
}) => {
  const [input, setInput] = useState('');
  const [startTime, setStartTime] = useState<number | null>(null);
  const [endTime, setEndTime] = useState<number | null>(null);
  const [isFocused, setIsFocused] = useState(false);
  const [status, setStatus] = useState<GameStatus>(GameStatus.IDLE);
  const [wpm, setWpm] = useState(0);
  const [ghostIndex, setGhostIndex] = useState(0);
  const [capsLock, setCapsLock] = useState(false);
  const [isShiftPressed, setIsShiftPressed] = useState(false);

  // Tracking Stats
  const [sessionMistakes, setSessionMistakes] = useState(0);
  const [sessionMistakeWords, setSessionMistakeWords] = useState<string[]>([]);
  const [retryCount, setRetryCount] = useState(0);

  // Smooth Caret State
  const [caretPos, setCaretPos] = useState({ left: 0, top: 0, height: 24, opacity: 0 });

  const inputRef = useRef<HTMLTextAreaElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const textContainerRef = useRef<HTMLDivElement>(null);
  const nextButtonRef = useRef<HTMLButtonElement>(null);
  const retryButtonRef = useRef<HTMLButtonElement>(null);

  // Sync Settings with Engine
  useEffect(() => {
    soundEngine.setEnabled(settings.sfxEnabled);
  }, [settings.sfxEnabled]);

  // Reset state when quote changes
  useEffect(() => {
    setInput('');
    setStartTime(null);
    setEndTime(null);
    setStatus(GameStatus.IDLE);
    setWpm(0);
    setGhostIndex(0);
    setSessionMistakes(0);
    setSessionMistakeWords([]);
    setRetryCount(0);
    if (isFocused) {
        inputRef.current?.focus();
    }
  }, [quote, isFocused]);

  // Focus management for buttons when game ends
  useEffect(() => {
    if (status === GameStatus.COMPLETED) {
        setTimeout(() => nextButtonRef.current?.focus(), 50);
    } else if (status === GameStatus.FAILED) {
        setTimeout(() => retryButtonRef.current?.focus(), 50);
    }
  }, [status]);

  // Handlers wrapped in useCallback for stable dependencies
  const handleRetry = useCallback(() => {
    setInput('');
    setStartTime(null);
    setEndTime(null);
    setStatus(GameStatus.IDLE);
    setWpm(0);
    setGhostIndex(0);
    setSessionMistakes(0); 
    setRetryCount(prev => prev + 1);
    setIsFocused(true);
    setTimeout(() => inputRef.current?.focus(), 10);
  }, []);

  const handleNext = useCallback(() => {
    const isPerfectMaster = retryCount === 0 && sessionMistakes === 0;
    const xp = calculateXP(wpm, quote.text.length, streak, isPerfectMaster, settings.readAheadLevel);
    onComplete(xp, wpm, sessionMistakeWords, retryCount);
  }, [onComplete, wpm, quote.text.length, streak, retryCount, sessionMistakes, sessionMistakeWords, settings.readAheadLevel]);

  // Caps Lock & Shift Detection
  useEffect(() => {
    const checkCapsLock = (e: KeyboardEvent | MouseEvent) => {
      if (e.getModifierState) {
        setCapsLock(e.getModifierState('CapsLock'));
      }
    };

    const handleKeyDown = (e: KeyboardEvent) => {
        if (e.key === 'Shift') setIsShiftPressed(true);
    };
    const handleKeyUp = (e: KeyboardEvent) => {
        if (e.key === 'Shift') setIsShiftPressed(false);
    };

    window.addEventListener('keydown', checkCapsLock as any);
    window.addEventListener('keyup', checkCapsLock as any);
    window.addEventListener('click', checkCapsLock as any);
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    return () => {
      window.removeEventListener('keydown', checkCapsLock as any);
      window.removeEventListener('keyup', checkCapsLock as any);
      window.removeEventListener('click', checkCapsLock as any);
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, []);

  // Global keydown listener
  useEffect(() => {
    const handleGlobalKeyDown = (e: KeyboardEvent) => {
      if (status === GameStatus.COMPLETED) {
        if (e.key === 'Enter' || e.key === 'Tab') {
          e.preventDefault();
          handleNext();
        }
        return;
      }

      if (status === GameStatus.FAILED) {
        if (e.key === 'Enter' || e.key === 'Tab') {
          e.preventDefault();
          handleRetry();
        }
        return;
      }

      if (!isFocused) {
        if (e.key === 'Tab') return;

        if (!e.metaKey && !e.altKey && !e.ctrlKey) {
            e.preventDefault(); 
            setIsFocused(true);
            inputRef.current?.focus();
        }
      }
    };
    window.addEventListener('keydown', handleGlobalKeyDown);
    return () => window.removeEventListener('keydown', handleGlobalKeyDown);
  }, [isFocused, status, handleNext, handleRetry]);

  // Smooth Caret Calculation
  useLayoutEffect(() => {
    const updateCaret = () => {
        if (!textContainerRef.current) return;

        let targetEl: HTMLElement | null = null;
        let left = 0;
        let top = 0;
        let height = 0;

        if (input.length < quote.text.length) {
            // Find current char
            targetEl = textContainerRef.current.querySelector(`[data-index="${input.length}"]`);
            if (targetEl) {
                left = targetEl.offsetLeft;
                top = targetEl.offsetTop;
                height = targetEl.offsetHeight;
            }
        } else {
            // End of text, position after last char
            targetEl = textContainerRef.current.querySelector(`[data-index="${input.length - 1}"]`);
            if (targetEl) {
                left = targetEl.offsetLeft + targetEl.offsetWidth;
                top = targetEl.offsetTop;
                height = targetEl.offsetHeight;
            } else if (quote.text.length === 0) {
                 // Empty quote fallback
                 left = 0;
                 top = 0;
                 height = 24; 
            }
        }

        // Handle visual adjustment for empty state or start
        if (input.length === 0 && quote.text.length > 0) {
             const firstEl = textContainerRef.current.querySelector(`[data-index="0"]`) as HTMLElement;
             if (firstEl) {
                 left = firstEl.offsetLeft;
                 top = firstEl.offsetTop;
                 height = firstEl.offsetHeight;
             }
        }

        setCaretPos({ 
            left, 
            top, 
            height: height || 32, // Default height fallback
            opacity: isFocused && status !== GameStatus.COMPLETED && status !== GameStatus.FAILED ? 1 : 0
        });
    };

    updateCaret();
    window.addEventListener('resize', updateCaret);
    return () => window.removeEventListener('resize', updateCaret);
  }, [input, quote, isFocused, status, settings.readAheadLevel]); // Recalculate on any change affecting layout

  const handleFocus = () => {
    if (status === GameStatus.COMPLETED || status === GameStatus.FAILED) return;
    setIsFocused(true);
    inputRef.current?.focus();
  };

  const handleBlur = () => {
    setTimeout(() => {
        if (document.activeElement !== inputRef.current) {
            setIsFocused(false);
        }
    }, 100);
  };

  const calculateStats = useCallback(() => {
    if (!startTime) return { currentWpm: 0 };
    const now = endTime || Date.now();
    const durationInMinutes = (now - startTime) / 60000;
    if (durationInMinutes <= 0) return { currentWpm: 0 };
    const currentWpm = Math.round((input.length / 5) / durationInMinutes);
    return { currentWpm };
  }, [endTime, input.length, startTime]);

  // Game Loop (WPM + Ghost)
  useEffect(() => {
    if (status === GameStatus.PLAYING) {
      const interval = setInterval(() => {
        const { currentWpm } = calculateStats();
        setWpm(currentWpm);

        if (settings.ghostEnabled && ghostWpm > 0 && startTime) {
            const now = Date.now();
            const elapsedMins = (now - startTime) / 60000;
            const projectedChars = (ghostWpm * 5) * elapsedMins;
            setGhostIndex(projectedChars);
        }
      }, 50);
      return () => clearInterval(interval);
    }
  }, [status, calculateStats, settings.ghostEnabled, ghostWpm, startTime]);

  const getWordAt = (index: number, text: string) => {
    const start = text.lastIndexOf(' ', index) + 1;
    let end = text.indexOf(' ', index);
    if (end === -1) end = text.length;
    return text.slice(start, end).replace(/[.,;!?]/g, ''); 
  };

  const handleChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    if (status === GameStatus.COMPLETED) return;

    const val = e.target.value;
    const prevLen = input.length;

    if (status === GameStatus.IDLE && val.length > 0) {
      setStartTime(Date.now());
      setStatus(GameStatus.PLAYING);
    }

    if (val.length > prevLen) {
        soundEngine.playKeypress();
    }

    // --- Instant Fail Check (All Modes) ---
    if (val.length > 0) {
      if (!quote.text.startsWith(val)) {
        soundEngine.playError(); 
        setStatus(GameStatus.FAILED);
        onFail();

        const word = getWordAt(val.length - 1, quote.text);
        onMistake(word);

        // Track locally for history
        setSessionMistakes(prev => prev + 1);
        if (word && !sessionMistakeWords.includes(word)) {
            setSessionMistakeWords(prev => [...prev, word]);
        }
        return;
      }
    }

    setInput(val);

    if (val.length === quote.text.length) {
      const isPerfect = val === quote.text;
      setEndTime(Date.now());

      if (isPerfect) {
        soundEngine.playSuccess(); 
        setStatus(GameStatus.COMPLETED);
        const finalTime = Date.now();
        const durationMins = (finalTime - (startTime || finalTime)) / 60000;
        const finalWpm = Math.round((quote.text.length / 5) / (durationMins || 1));
        setWpm(finalWpm);
      } else {
        soundEngine.playError(); 
        setStatus(GameStatus.FAILED);
        onFail();
      }
    }
  };

  const getReadAheadState = (index: number) => {
    if (settings.readAheadLevel === 'NONE' || status === GameStatus.IDLE) return { isHidden: false, isHighlighted: false };

    const text = quote.text;
    const caret = input.length;

    let currentWordStart = text.lastIndexOf(' ', caret - 1);
    currentWordStart = currentWordStart === -1 ? 0 : currentWordStart + 1;

    let currentWordEnd = text.indexOf(' ', caret);
    if (currentWordEnd === -1) currentWordEnd = text.length;

    // --- LEVEL 1: FOCUS ---
    if (index >= currentWordStart && index < currentWordEnd) {
        return { isHidden: true, isHighlighted: false };
    }

    // --- LEVEL 2: ULTRA ---
    if (settings.readAheadLevel === 'ULTRA' || settings.readAheadLevel === 'BLIND') {
        let nextWordStart = currentWordEnd + 1;
        let nextWordEnd = text.indexOf(' ', nextWordStart);
        if (nextWordEnd === -1) nextWordEnd = text.length;

        if (index >= nextWordStart && index < nextWordEnd) {
            return { isHidden: true, isHighlighted: false }; 
        }
    }

    // --- LEVEL 3: BLIND ---
    if (settings.readAheadLevel === 'BLIND') {
        let nextWordStart = currentWordEnd + 1;
        let nextWordEnd = text.indexOf(' ', nextWordStart);
        if (nextWordEnd === -1) nextWordEnd = text.length;

        let secondNextStart = nextWordEnd + 1;
        let secondNextEnd = text.indexOf(' ', secondNextStart);
        if (secondNextEnd === -1) secondNextEnd = text.length;

        if (index >= secondNextStart && index < secondNextEnd) {
             return { isHidden: true, isHighlighted: false };
        }
    }

    // Highlight next visible word
    if (index > currentWordEnd) { 
        let highlightStart = currentWordEnd + 1;
        if (settings.readAheadLevel === 'ULTRA') {
             let skip1 = text.indexOf(' ', highlightStart);
             if (skip1 !== -1) highlightStart = skip1 + 1;
             else highlightStart = text.length; 
        } else if (settings.readAheadLevel === 'BLIND') {
             let skip1 = text.indexOf(' ', highlightStart);
             let skip2 = skip1 !== -1 ? text.indexOf(' ', skip1 + 1) : -1;
             if (skip2 !== -1) highlightStart = skip2 + 1;
             else highlightStart = text.length;
        }

        let highlightEnd = text.indexOf(' ', highlightStart);
        if (highlightEnd === -1) highlightEnd = text.length;

        if (index >= highlightStart && index < highlightEnd) {
             return { isHidden: false, isHighlighted: true };
        }
    }

    return { isHidden: false, isHighlighted: false };
  };

  const getTextColor = () => {
     if (status === GameStatus.FAILED) {
        if (gameMode === 'HARDCORE') return 'text-red-400/50';
        return 'text-red-300';
     }
     if (gameMode === 'HARDCORE') return 'text-stone-400';
     return 'text-stone-300';
  };

  const renderText = () => {
    return quote.text.split('').map((char, index) => {
      let colorClass = getTextColor(); 
      let bgClass = '';

      const { isHidden, isHighlighted } = getReadAheadState(index);

      if (index < input.length) {
        if (input[index] === char) {
          // Use Dino Green for completed text
          colorClass = 'text-dino-400'; 
        } else {
          colorClass = 'text-red-500 bg-red-100'; 
        }
      } else {
          if (isHighlighted) {
              colorClass = 'text-dino-600 font-bold';
              bgClass = 'bg-dino-100/50';
          }
      }

      if (gameMode === 'FIX_MISTAKE') {
          if (index >= input.length) {
              colorClass = 'text-red-300';
          }
      }

      const isGhostHere = settings.ghostEnabled && Math.floor(ghostIndex) === index;

      return (
        <span key={index} data-index={index} className="relative">
            {isGhostHere && (
                <span className="absolute -left-[2px] top-0 bottom-0 w-[2px] bg-purple-400/50 z-20 animate-pulse">
                     <span className="absolute -top-4 -left-2 text-[10px] text-purple-400 opacity-70">👻</span>
                </span>
            )}

            <span 
                className={`
                    ${colorClass} ${bgClass} transition-colors duration-100
                    ${isHidden ? 'text-transparent selection:text-transparent' : ''}
                    ${isHidden && index < input.length && input[index] !== char ? '!text-red-500 !bg-red-100' : ''} 
                `}
            >
                {char}
            </span>
        </span>
      );
    });
  };

  const getContainerStyle = () => {
    if (status === GameStatus.FAILED) {
        if (gameMode === 'HARDCORE') {
            return 'bg-red-900/20 border-red-900/50 shadow-[0_0_40px_rgba(220,38,38,0.1)]';
        }
        return 'bg-red-50 border-red-200 shadow-inner';
    }

    if (gameMode === 'HARDCORE') {
        return 'bg-neutral-900 border-neutral-800 text-neutral-400 shadow-[0_0_40px_rgba(0,0,0,0.2)]';
    }
    if (gameMode === 'FIX_MISTAKE') {
        return 'bg-red-50 border-red-100';
    }

    // Light gray background for container
    return 'bg-stone-50 border-stone-200 overflow-hidden';
  };

  // Dynamic Text Sizing
  const getFontSizeClass = () => {
    const len = quote.text.length;
    // Adjusted sizes for better scaling
    if (len < 40) return 'text-4xl md:text-6xl leading-tight';
    if (len < 80) return 'text-3xl md:text-5xl leading-snug';
    if (len < 150) return 'text-2xl md:text-4xl leading-normal';
    return 'text-xl md:text-3xl leading-relaxed';
  };

  const isPerfectMasterPotential = retryCount === 0 && sessionMistakes === 0 && status !== GameStatus.FAILED;

  return (
    <div 
      className="relative w-full max-w-6xl mx-auto min-h-[400px] flex flex-col"
      ref={containerRef}
    >
      {/* Perfect Master Indicator */}
      {isPerfectMasterPotential && status === GameStatus.PLAYING && (
        <div className="absolute -top-8 left-1/2 transform -translate-x-1/2 flex items-center gap-1 text-xs font-bold text-dino-500 animate-pulse">
          <Sparkles className="w-3 h-3" /> Perfect Master Potential (1.5x Bonus)
        </div>
      )}

      <div className={`
        relative flex-grow flex flex-col justify-center p-12 md:p-20 rounded-[3rem] transition-all duration-300 border
        ${getContainerStyle()}
        ${isFocused && status !== GameStatus.FAILED && status !== GameStatus.COMPLETED ? 'ring-2 ring-dino-400/50 ring-offset-2 ring-offset-bg-body' : ''}
        ${status === GameStatus.FAILED ? 'ring-2 ring-red-500 shadow-[0_0_20px_rgba(239,68,68,0.3)]' : ''}
        ${status === GameStatus.COMPLETED ? 'ring-2 ring-dino-100 bg-dino-50/20' : ''}
        ${streak > 2 && status === GameStatus.PLAYING ? 'shadow-[0_0_30px_rgba(251,146,60,0.15)] ring-1 ring-orange-100' : ''}
      `}>

        {!isFocused && status !== GameStatus.COMPLETED && status !== GameStatus.FAILED && (
          <div 
            onClick={handleFocus}
            className="absolute inset-0 z-50 flex items-center justify-center bg-stone-900/5 backdrop-blur-sm cursor-pointer rounded-[3rem] border-2 border-dashed border-dino-200/50 hover:border-dino-300 transition-all"
          >
            <div className="text-center animate-bounce text-dino-500">
              <Play className="w-10 h-10 mx-auto mb-2 opacity-80" fill="currentColor" />
              <span className="font-bold text-base tracking-wide uppercase font-sans">Click or Type to Start</span>
            </div>
          </div>
        )}

        {status === GameStatus.COMPLETED && (
          <div className="absolute inset-0 z-40 flex items-center justify-center">
             <div className="bg-stone-50/90 backdrop-blur-md p-8 rounded-3xl shadow-2xl border border-stone-200 animate-in zoom-in-95 fade-in duration-300 flex flex-col items-center gap-6 min-w-[280px]">
                <div className="text-dino-500 font-black text-xl tracking-tight flex items-center gap-2">
                   <Award className="w-6 h-6" /> Quote Complete!
                </div>

                <div className="grid grid-cols-2 gap-x-12 gap-y-6 w-full">
                   <div className="flex flex-col items-center">
                      <span className="text-[10px] uppercase font-bold text-stone-400 tracking-widest mb-1">Time</span>
                      <span className="font-mono font-bold text-2xl text-stone-700">
                        {endTime && startTime ? ((endTime - startTime) / 1000).toFixed(1) : '0.0'}s
                      </span>
                   </div>
                   <div className="flex flex-col items-center">
                      <span className="text-[10px] uppercase font-bold text-stone-400 tracking-widest mb-1">Speed</span>
                      <span className="font-mono font-bold text-2xl text-stone-700">{wpm} <span className="text-xs text-stone-400 font-sans font-medium">WPM</span></span>
                   </div>
                   <div className="flex flex-col items-center">
                      <span className="text-[10px] uppercase font-bold text-stone-400 tracking-widest mb-1">Retries</span>
                      <span className="font-mono font-bold text-2xl text-stone-700">
                          {retryCount}
                      </span>
                   </div>
                   <div className="flex flex-col items-center">
                      <span className="text-[10px] uppercase font-bold text-stone-400 tracking-widest mb-1">XP Earned</span>
                      <span className="font-mono font-bold text-2xl text-dino-600">
                        +{calculateXP(wpm, quote.text.length, streak, retryCount === 0 && sessionMistakes === 0, settings.readAheadLevel) * (gameMode === 'HARDCORE' ? 5 : 1)}
                      </span>
                   </div>
                </div>

                <div className="text-[10px] font-medium text-stone-400 bg-stone-100/50 px-3 py-1.5 rounded-full">
                   Press <span className="font-bold text-stone-500">Enter</span> or <span className="font-bold text-stone-500">Tab</span> to continue
                </div>
             </div>
          </div>
        )}

        <div className="absolute top-4 left-0 right-0 flex justify-center gap-2 z-30 select-none pointer-events-none">
            {capsLock && (
              <div className="flex items-center gap-2 px-3 py-1.5 bg-orange-100 text-orange-600 rounded-full text-[10px] font-bold tracking-widest border border-orange-200 shadow-sm animate-pulse">
                <Lock className="w-3 h-3" /> CAPS LOCK
              </div>
            )}
            {isShiftPressed && (
               <div className="flex items-center gap-2 px-3 py-1.5 bg-blue-50 text-blue-600 rounded-full text-[10px] font-bold tracking-widest border border-blue-100 shadow-sm">
                <ArrowUp className="w-3 h-3" /> SHIFT
              </div>
            )}
        </div>

        <div className="absolute inset-0 pointer-events-none select-none overflow-hidden rounded-[3rem]">
           {gameMode === 'QUOTES' && (
              <div className="absolute -top-12 -left-12 opacity-[0.02] transform -rotate-12 transition-all duration-700 ease-out scale-100 hover:scale-105">
                 <QuoteIcon className="w-80 h-80 text-stone-900" fill="currentColor" />
              </div>
           )}
           {gameMode === 'HARDCORE' && (
              <div className="absolute -top-12 -left-12 opacity-[0.03] transform -rotate-12 transition-all duration-700 ease-out scale-100 hover:scale-105">
                 <Skull className="w-80 h-80 text-stone-100" />
              </div>
           )}
           {gameMode === 'FIX_MISTAKE' && (
              <div className="absolute -top-12 -left-12 opacity-[0.03] transform -rotate-12 transition-all duration-700 ease-out scale-100 hover:scale-105">
                 <Eraser className="w-80 h-80 text-red-900" />
              </div>
           )}
        </div>

        <div className="absolute top-10 left-0 right-0 px-20 flex justify-between text-xs font-bold opacity-80 uppercase tracking-[0.2em] select-none font-sans z-10 text-stone-500">
          <div className="flex gap-4">
             <span>{quote.source}</span>
             {settings.ghostEnabled && <span className="text-purple-300 flex items-center gap-1"><Ghost className="w-3.5 h-3.5"/> {ghostWpm > 0 ? `${ghostWpm} WPM` : 'Ready'}</span>}
             {settings.readAheadLevel !== 'NONE' && <span className="text-dino-400 flex items-center gap-1"><EyeOff className="w-3.5 h-3.5"/> {settings.readAheadLevel}</span>}
          </div>
          <span>{quote.author}</span>
        </div>

        {/* Text Container with Caret and Dynamic Font */}
        <div 
          ref={textContainerRef}
          className={`font-mono tracking-wide break-words whitespace-pre-wrap mb-12 mt-10 relative z-10 outline-none select-none ${getTextColor()} ${getFontSizeClass()}`}
          onClick={handleFocus}
        >
          {/* Smooth Caret with Dino Green */}
          <div 
             className="absolute bg-dino-500 w-[3px] rounded-full transition-all duration-100 ease-out z-20 pointer-events-none caret-blink shadow-[0_0_10px_rgba(132,204,22,0.5)]"
             style={{ 
                 left: caretPos.left - 1, 
                 top: caretPos.top + 2, 
                 height: caretPos.height - 4,
                 opacity: caretPos.opacity
             }}
          />
          {renderText()}
        </div>

        <textarea
          ref={inputRef}
          value={input}
          onChange={handleChange}
          onBlur={handleBlur}
          onFocus={() => {
              setIsFocused(true);
              onInteract?.();
          }}
          className="absolute opacity-0 top-0 left-0 h-full w-full cursor-default resize-none"
          autoFocus={isFocused}
          disabled={status === GameStatus.COMPLETED || status === GameStatus.FAILED}
        />

        <div className="absolute bottom-10 left-0 right-0 px-20 flex justify-between items-end select-none z-10">
           <div className="flex items-center gap-10 text-stone-400 font-mono text-sm">
             <div className="flex flex-col">
                <span className="text-[10px] uppercase font-bold text-stone-300 mb-0.5 tracking-wider">Speed</span>
                <span className="font-bold text-xl opacity-80 font-sans">{wpm} <span className="text-[10px] font-normal opacity-50">WPM</span></span>
             </div>
             {streak > 0 && (
                <div className={`flex flex-col ${streak > 4 ? 'text-orange-500' : 'text-stone-400'}`}>
                    <span className="text-[10px] uppercase font-bold text-stone-300 mb-0.5 tracking-wider">Streak</span>
                    <span className="font-bold text-xl flex items-center gap-1.5 font-sans">
                        <Flame className={`w-4 h-4 ${streak > 4 ? 'fill-orange-500' : ''}`} /> {streak}
                    </span>
                </div>
             )}
           </div>

           <div>
              {status === GameStatus.FAILED && (
                <button 
                  ref={retryButtonRef}
                  onClick={handleRetry}
                  className="flex items-center gap-2 px-6 py-2.5 bg-red-50 text-red-500 rounded-full hover:bg-red-100 transition font-bold text-sm tracking-wide uppercase focus:outline-none focus:ring-2 focus:ring-red-400 focus:ring-offset-2"
                >
                  <RotateCcw className="w-4 h-4" /> Retry
                </button>
              )}
              {status === GameStatus.COMPLETED && (
                <button 
                  ref={nextButtonRef}
                  onClick={handleNext}
                  className={`flex items-center gap-2 px-6 py-2.5 rounded-full transition shadow-lg font-bold text-sm tracking-wide uppercase transform hover:-translate-y-0.5 focus:outline-none focus:ring-2 focus:ring-offset-2
                    bg-dino-500 text-white hover:bg-dino-600 shadow-dino-200/50 focus:ring-dino-400
                  `}
                >
                   Next Quote <Award className="w-4 h-4" />
                </button>
              )}
           </div>
        </div>
      </div>

      <div className="text-center mt-8 h-4 text-stone-400 text-xs font-medium tracking-wide transition-opacity duration-500 font-sans">
        {status === GameStatus.FAILED ? 
            <span className="text-red-400">
                {gameMode === 'HARDCORE' 
                  ? 'HARDCORE FAIL. 50% XP Penalty.' 
                  : 'Mistake made. Restart required.'}
            </span> : 
         status === GameStatus.COMPLETED ? <span className="text-dino-500">Perfect! Streak +1 {retryCount === 0 && sessionMistakes === 0 && "(Mastery Bonus!)"}</span> :
         isFocused ? "Accuracy is paramount. One mistake restarts the quote." : ""}
      </div>
    </div>
  );
};

export default TypingArea;

import React, { useState, useEffect, useCallback, useLayoutEffect, useRef } from 'react';
import ProgressBar from './components/ProgressBar';
import TypingArea from './components/TypingArea';
import SettingsModal from './components/SettingsModal';
import HelpModal from './components/HelpModal';
import StatsModal from './components/StatsModal';
import ThemeModal from './components/ThemeModal';
import AchievementsModal from './components/AchievementsModal';
import AchievementToast from './components/AchievementToast';
import { MusicPlayer } from './components/MusicPlayer';
import { Quote, Settings, GameMode, TestResult, NotificationItem, ReadAheadLevel } from './types';
import { fetchQuotes } from './services/quoteService';
import { getCurrentLevel, getNextLevel, getAverageWPM, LEVELS, calculateXP } from './utils/gameLogic';
import { soundEngine } from './utils/soundEngine';
import { Loader2, Settings as SettingsIcon, Music, CircleHelp, Skull, BookOpen, Eraser, TrendingUp, Palette, Award, Radio, Lock, Eye, EyeOff, Flame } from 'lucide-react';
import confetti from 'canvas-confetti';
import { THEMES } from './data/themes';
import { ACHIEVEMENTS } from './data/achievements';
import { RADIO_STATIONS } from './data/radioStations';

const App: React.FC = () => {
  // User Stats Persistence
  const [userName, setUserName] = useState<string>(() => {
      return localStorage.getItem('frogType_userName') || 'Froggy';
  });

  const [joinDate, setJoinDate] = useState<string>(() => {
      const stored = localStorage.getItem('frogType_joinDate');
      if (stored) return stored;
      const now = new Date().toISOString();
      localStorage.setItem('frogType_joinDate', now);
      return now;
  });

  const [totalTimePlayed, setTotalTimePlayed] = useState<number>(() => {
      const stored = localStorage.getItem('frogType_totalTime');
      return stored ? parseInt(stored, 10) : 0;
  });

  const [userXP, setUserXP] = useState<number>(() => {
    const saved = localStorage.getItem('frogXP');
    const legacy = localStorage.getItem('frogType_xp');
    if (saved) return parseInt(saved, 10);
    if (legacy) return parseInt(legacy, 10);
    return 0;
  });

  const currentLevel = getCurrentLevel(userXP);

  // Track unlocked tiers persistently to prevent repeat notifications
  const [unlockedTiers, setUnlockedTiers] = useState<string[]>(() => {
    const saved = localStorage.getItem('frogType_unlockedTiers');
    return saved ? JSON.parse(saved) : [];
  });

  // Session Streak (Consecutive Quotes)
  const [streak, setStreak] = useState<number>(() => {
    const saved = localStorage.getItem('frogType_streak');
    return saved ? parseInt(saved, 10) : 0;
  });

  // Daily Streak Logic
  const [dailyStreak, setDailyStreak] = useState<number>(() => {
     const saved = localStorage.getItem('frogType_dailyStreak');
     return saved ? parseInt(saved, 10) : 0;
  });

  const [unlockedAchievements, setUnlockedAchievements] = useState<string[]>(() => {
    const saved = localStorage.getItem('frogType_achievements');
    return saved ? JSON.parse(saved) : [];
  });

  const [notificationQueue, setNotificationQueue] = useState<NotificationItem[]>([]);

  // Track history for average WPM calculation (Last 10)
  const [wpmHistory, setWpmHistory] = useState<number[]>(() => {
    const saved = localStorage.getItem('frogType_wpmHistory');
    return saved ? JSON.parse(saved) : [];
  });

  // Track full history of tests
  const [testHistory, setTestHistory] = useState<TestResult[]>(() => {
    const saved = localStorage.getItem('frogType_history');
    return saved ? JSON.parse(saved) : [];
  });

  const [lastWpm, setLastWpm] = useState<number>(() => {
    const saved = localStorage.getItem('frogType_lastWpm');
    return saved ? parseInt(saved, 10) : 0;
  });

  const [mistakePool, setMistakePool] = useState<string[]>(() => {
    const saved = localStorage.getItem('frogType_mistakes');
    return saved ? JSON.parse(saved) : [];
  });

  const [settings, setSettings] = useState<Settings>(() => {
    const saved = localStorage.getItem('frogType_settings');

    if (!saved) {
      return { 
        ghostEnabled: false, 
        readAheadLevel: 'NONE', 
        sfxEnabled: true,
        mechanicalSoundEnabled: false,
        mechanicalSoundPreset: 'THOCK',
        ambientVolume: 0.02, 
        musicConfig: { source: 'GENERATED', presetId: 'PIANO_SATIE' },
        themeId: 'CLASSIC'
      };
    }

    const parsed = JSON.parse(saved);
    const legacyBrownNoiseEnabled = parsed.brownNoiseEnabled === true;
    const legacyVolume = parsed.brownNoiseVolume ?? 0.5;

    // Migration for legacy boolean readAhead
    let initialReadAhead = parsed.readAheadLevel;
    if (parsed.readAheadEnabled === true && !initialReadAhead) initialReadAhead = 'FOCUS';
    if (!initialReadAhead) initialReadAhead = 'NONE';

    let initialMusicConfig = parsed.musicConfig || { source: 'NONE', presetId: '' };
    if (legacyBrownNoiseEnabled && initialMusicConfig.source === 'NONE') {
        initialMusicConfig = { source: 'GENERATED', presetId: 'BROWN_NOISE' };
    }

    return { 
      ghostEnabled: false, 
      readAheadLevel: initialReadAhead, 
      sfxEnabled: true,
      mechanicalSoundEnabled: parsed.mechanicalSoundEnabled ?? false,
      mechanicalSoundPreset: parsed.mechanicalSoundPreset || 'THOCK',
      ambientVolume: parsed.ambientVolume ?? legacyVolume, 
      musicConfig: initialMusicConfig,
      themeId: parsed.themeId || 'CLASSIC',
      ...parsed
    };
  });

  const [gameMode, setGameMode] = useState<GameMode>(() => {
    const saved = localStorage.getItem('frogType_gameMode');
    return (saved as GameMode) || 'QUOTES';
  });

  const [completedQuotes, setCompletedQuotes] = useState<string[]>(() => {
    const saved = localStorage.getItem('frogType_completedQuotes');
    return saved ? JSON.parse(saved) : [];
  });

  const [quotesQueue, setQuotesQueue] = useState<Quote[]>([]);

  const [currentQuote, setCurrentQuote] = useState<Quote | null>(() => {
    const saved = localStorage.getItem('frogType_currentQuote');
    return saved ? JSON.parse(saved) : null;
  });

  const [loading, setLoading] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isMusicOpen, setIsMusicOpen] = useState(false);
  const [isHelpOpen, setIsHelpOpen] = useState(false);
  const [isStatsOpen, setIsStatsOpen] = useState(false);
  const [isThemeOpen, setIsThemeOpen] = useState(false);
  const [isAchievementsOpen, setIsAchievementsOpen] = useState(false);

  // Start time tracking for current quote
  const [quoteStartTime, setQuoteStartTime] = useState<number | null>(null);

  const isFetchingRef = useRef(false);

  // Derive Lock State
  const uniqueTiers = Array.from(new Set(LEVELS.map(l => l.tier)));
  const currentTierIndex = uniqueTiers.indexOf(currentLevel.tier);
  const polliwogIndex = uniqueTiers.indexOf('Polliwog');
  const isHardcoreLocked = currentTierIndex < polliwogIndex;

  // Persistence
  useEffect(() => { localStorage.setItem('frogXP', userXP.toString()); }, [userXP]);
  useEffect(() => { localStorage.setItem('frogType_unlockedTiers', JSON.stringify(unlockedTiers)); }, [unlockedTiers]);
  useEffect(() => { localStorage.setItem('frogType_streak', streak.toString()); }, [streak]);
  useEffect(() => { localStorage.setItem('frogType_dailyStreak', dailyStreak.toString()); }, [dailyStreak]);
  useEffect(() => { localStorage.setItem('frogType_lastWpm', lastWpm.toString()); }, [lastWpm]);
  useEffect(() => { localStorage.setItem('frogType_wpmHistory', JSON.stringify(wpmHistory)); }, [wpmHistory]);
  useEffect(() => { localStorage.setItem('frogType_history', JSON.stringify(testHistory)); }, [testHistory]);
  useEffect(() => { localStorage.setItem('frogType_settings', JSON.stringify(settings)); }, [settings]);
  useEffect(() => { localStorage.setItem('frogType_mistakes', JSON.stringify(mistakePool)); }, [mistakePool]);
  useEffect(() => { localStorage.setItem('frogType_userName', userName); }, [userName]);
  useEffect(() => { localStorage.setItem('frogType_totalTime', totalTimePlayed.toString()); }, [totalTimePlayed]);

  // Game Mode Persistence & Lock Check
  useEffect(() => { 
      if (gameMode === 'HARDCORE' && isHardcoreLocked) {
          setGameMode('QUOTES');
      }
      localStorage.setItem('frogType_gameMode', gameMode); 
  }, [gameMode, isHardcoreLocked]);

  useEffect(() => { localStorage.setItem('frogType_completedQuotes', JSON.stringify(completedQuotes)); }, [completedQuotes]);
  useEffect(() => { localStorage.setItem('frogType_achievements', JSON.stringify(unlockedAchievements)); }, [unlockedAchievements]);

  // Audio Settings Sync
  useEffect(() => {
    soundEngine.setEnabled(settings.sfxEnabled);
    soundEngine.setMechanicalEnabled(settings.mechanicalSoundEnabled);
    soundEngine.setMechanicalPreset(settings.mechanicalSoundPreset);
    soundEngine.setAmbientVolume(settings.ambientVolume);

    if (settings.musicConfig.source === 'GENERATED') {
      soundEngine.setAmbientMusic(settings.musicConfig.presetId);
    } else {
      soundEngine.stopAmbientMusic();
    }
  }, [settings.sfxEnabled, settings.mechanicalSoundEnabled, settings.mechanicalSoundPreset, settings.ambientVolume, settings.musicConfig]);

  useLayoutEffect(() => {
    const theme = THEMES.find(t => t.id === settings.themeId) || THEMES[0];
    const root = document.documentElement;
    root.style.setProperty('--bg-body', theme.colors.background);
    Object.entries(theme.colors.frog).forEach(([key, value]) => {
       root.style.setProperty(`--frog-${key}`, value);
    });
    Object.entries(theme.colors.stone).forEach(([key, value]) => {
       root.style.setProperty(`--stone-${key}`, value);
    });
    root.style.setProperty('--text-body', theme.colors.stone[800]);
  }, [settings.themeId]);

  useEffect(() => {
    const handleInteraction = () => {
      soundEngine.resumeContext();
      window.removeEventListener('click', handleInteraction);
      window.removeEventListener('keydown', handleInteraction);
    };

    window.addEventListener('click', handleInteraction);
    window.addEventListener('keydown', handleInteraction);
    return () => {
      window.removeEventListener('click', handleInteraction);
      window.removeEventListener('keydown', handleInteraction);
    };
  }, []);

  useEffect(() => { 
    if (currentQuote) {
      localStorage.setItem('frogType_currentQuote', JSON.stringify(currentQuote)); 
      setQuoteStartTime(Date.now());
    } else {
      localStorage.removeItem('frogType_currentQuote');
    }
  }, [currentQuote]);

  // Check Daily Streak on Mount
  useEffect(() => {
      const today = new Date().toDateString();
      const lastVisit = localStorage.getItem('frogType_lastVisitDate');

      // If user hasn't visited today, check if streak should break
      if (lastVisit && lastVisit !== today) {
          const yesterday = new Date();
          yesterday.setDate(yesterday.getDate() - 1);

          if (yesterday.toDateString() !== lastVisit) {
              // Streak broken if last visit was not yesterday
              setDailyStreak(0);
          }
      } else if (!lastVisit) {
          setDailyStreak(0);
      }
  }, []);

  const updateDailyStreakActivity = () => {
      const today = new Date().toDateString();
      const lastVisit = localStorage.getItem('frogType_lastVisitDate');

      if (lastVisit !== today) {
          // New day activity
          let newStreak = 1;
          if (lastVisit) {
              const yesterday = new Date();
              yesterday.setDate(yesterday.getDate() - 1);
              if (yesterday.toDateString() === lastVisit) {
                  newStreak = dailyStreak + 1;
              }
          }
          setDailyStreak(newStreak);
          localStorage.setItem('frogType_lastVisitDate', today);

          // Toast for streak
          setNotificationQueue(prev => [...prev, {
              id: `daily_${Date.now()}`,
              title: "Daily Streak!",
              description: `You're on a ${newStreak} day streak.`,
              icon: <Flame className="w-5 h-5 text-orange-500" />,
              type: "INFO"
          }]);
      } else {
          // Already played today, ensure streak is at least 1 if it was 0
          if (dailyStreak === 0) {
              setDailyStreak(1);
              localStorage.setItem('frogType_lastVisitDate', today);
          }
      }
  };

  const generateMistakeQuote = useCallback((): Quote | null => {
    if (mistakePool.length === 0) return null;
    let pool = [...mistakePool];
    while (pool.length < 15) {
       pool = [...pool, ...mistakePool];
    }
    const shuffled = pool.sort(() => 0.5 - Math.random());
    const selected = shuffled.slice(0, 15);
    const text = selected.join(' ');

    return {
      text,
      source: "Personal Training",
      author: "Your Mistakes"
    };
  }, [mistakePool]);

  const loadMoreQuotes = useCallback(async () => {
    if (isFetchingRef.current) return;

    isFetchingRef.current = true;

    try {
      const level = getCurrentLevel(userXP);
      // IMPORTANT: Pass completedQuotes to filter them out forever
      const newQuotes = await fetchQuotes(5, completedQuotes, level.tier, gameMode);
      setQuotesQueue(prev => [...prev, ...newQuotes]);
    } catch (error) {
      console.error("Failed to load quotes", error);
    } finally {
      isFetchingRef.current = false;
    }
  }, [completedQuotes, userXP, gameMode]);

  useEffect(() => {
    const init = async () => {
      if (!currentQuote && quotesQueue.length === 0) {
         setLoading(true);
         await loadMoreQuotes();
         setLoading(false);
      } else if (quotesQueue.length < 3) {
         loadMoreQuotes();
      }
    };
    init();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (currentQuote) return;

    if (gameMode === 'FIX_MISTAKE') {
      const mistakeQuote = generateMistakeQuote();
      if (mistakeQuote) {
        setCurrentQuote(mistakeQuote);
      } else {
        setGameMode('QUOTES'); 
      }
    } else {
      if (quotesQueue.length > 0) {
        const next = quotesQueue[0];
        setCurrentQuote(next);
        setQuotesQueue(prev => prev.slice(1));
      }

      if (quotesQueue.length < 3) {
        loadMoreQuotes();
      }
    }
  }, [currentQuote, quotesQueue, gameMode, generateMistakeQuote, loadMoreQuotes]);

  const checkAchievements = (wpm: number) => {
    const newNotifications: NotificationItem[] = [];
    const newUnlockIds: string[] = [];

    const stats = {
       wpm,
       totalQuotes: completedQuotes.length + 1, 
       maxStreak: Math.max(streak + 1, streak + 1),
       currentStreak: streak + 1,
       mode: gameMode
    };

    ACHIEVEMENTS.forEach(ach => {
       if (!unlockedAchievements.includes(ach.id)) {
           if (ach.condition(stats)) {
               newUnlockIds.push(ach.id);
               newNotifications.push({
                   id: ach.id,
                   title: ach.title,
                   description: ach.description,
                   icon: ach.icon,
                   type: 'ACHIEVEMENT'
               });
           }
       }
    });

    if (newUnlockIds.length > 0) {
       setUnlockedAchievements(prev => [...prev, ...newUnlockIds]);
       setNotificationQueue(prev => [...prev, ...newNotifications]);
       soundEngine.playLevelUp(); 
    }
  };

  const handleQuoteComplete = (xpCalc: number, wpm: number, mistakes: string[], retryCount: number) => {
    // Recalculate with Read Ahead Bonus (if any changed since TypingArea)
    // Actually simpler to pass raw WPM/Length and recalc here or trust TypingArea passed value.
    // TypingArea uses calculateXP so it already includes ReadAhead bonus from settings passed to it.
    let finalXp = xpCalc; 

    // Update Time Played
    if (quoteStartTime) {
        const durationSec = Math.floor((Date.now() - quoteStartTime) / 1000);
        setTotalTimePlayed(prev => prev + durationSec);
    }

    if (gameMode === 'HARDCORE') {
      finalXp = finalXp * 5;
    }

    // Fix Mistake Mode Logic
    if (gameMode === 'FIX_MISTAKE' && currentQuote) {
      const wordsFixed = [...new Set(currentQuote.text.split(' '))]; 
      setMistakePool(prev => prev.filter(word => !wordsFixed.includes(word)));
    }

    // Mark quote as completed so it never shows again (if in standard modes)
    if (currentQuote && gameMode !== 'FIX_MISTAKE') {
       setCompletedQuotes(prev => [...prev, currentQuote.text]);
    }

    // Update History
    const newHistory = [...wpmHistory, wpm].slice(-10); 
    setWpmHistory(newHistory);
    const avgWpm = getAverageWPM(newHistory);

    const newTestResult: TestResult = {
      id: Date.now(),
      date: new Date().toISOString(),
      wpm,
      xpEarned: finalXp,
      mode: gameMode,
      quoteText: currentQuote?.text || "",
      mistakes: mistakes,
      retryCount: retryCount
    };
    setTestHistory(prev => [...prev, newTestResult]);

    checkAchievements(wpm);

    // Calculate XP and Handle Gates/Unlocks
    const currentLevelObj = getCurrentLevel(userXP);
    const nextLevelObj = getNextLevel(currentLevelObj);
    let potentialXp = userXP + finalXp;

    if (nextLevelObj && potentialXp >= nextLevelObj.minXP) {
         let effectiveMistakeCount = mistakePool.length;
         if (gameMode === 'FIX_MISTAKE' && currentQuote) {
             const wordsFixed = [...new Set(currentQuote.text.split(' '))];
             effectiveMistakeCount = mistakePool.filter(word => !wordsFixed.includes(word)).length;
         }

         const isMasteryGated = effectiveMistakeCount > 0;
         const isSpeedGated = avgWpm < nextLevelObj.requiredWpm;

         if (isMasteryGated || isSpeedGated) {
            potentialXp = nextLevelObj.minXP - 1; 
         }
    }

    const newLevel = getCurrentLevel(potentialXp);

    // Check for Tier Unlocks (Persistent - Only once per tier)
    if (!unlockedTiers.includes(newLevel.tier)) {
         setUnlockedTiers(prev => [...prev, newLevel.tier]);

         const newStations = RADIO_STATIONS.filter(s => s.tier === newLevel.tier);

         if (newStations.length > 0) {
             const musicNotifications: NotificationItem[] = newStations.map(s => ({
                id: `unlock_${s.id}`,
                title: 'New Station Unlocked',
                description: s.name,
                icon: <Radio className="w-5 h-5 text-stone-900" />,
                type: 'UNLOCK'
             }));
             setNotificationQueue(prev => [...prev, ...musicNotifications]);
         }
    }

    const prevLevel = getCurrentLevel(userXP);
    if (newLevel.tier !== prevLevel.tier && potentialXp >= newLevel.minXP) {
          setTimeout(() => {
              confetti({
                particleCount: 200,
                spread: 120,
                origin: { y: 0.6 },
                colors: ['#d1fae5', '#10b981', '#fbbf24', '#f59e0b'],
                startVelocity: 45
              });
              soundEngine.playLevelUp(); 
          }, 300);
    }

    setUserXP(potentialXp);
    setStreak(prev => prev + 1);

    // Update Daily Streak
    updateDailyStreakActivity();

    setLastWpm(wpm);
    setCurrentQuote(null); 
    setQuoteStartTime(null);
  };

  const handleQuoteFail = () => {
    setStreak(0);
  };

  const handleMistake = (word?: string) => {
    const penaltyMultiplier = gameMode === 'HARDCORE' ? 0.5 : 0.85;
    setUserXP(prev => Math.floor(prev * penaltyMultiplier));

    setStreak(0);

    if (word && word.length > 1) {
       setMistakePool(prev => {
         if (prev.includes(word)) return prev;
         return [...prev, word];
       });
    }
  };

  const handlePracticeFromHistory = (mistakes: string[]) => {
      setMistakePool(prev => {
          const newSet = new Set([...prev, ...mistakes]);
          return Array.from(newSet);
      });
      switchMode('FIX_MISTAKE');
  };

  const toggleSettings = () => setIsSettingsOpen(!isSettingsOpen);
  const toggleMusic = () => setIsMusicOpen(!isMusicOpen);
  const toggleHelp = () => setIsHelpOpen(!isHelpOpen);
  const toggleStats = () => setIsStatsOpen(!isStatsOpen);
  const toggleTheme = () => setIsThemeOpen(!isThemeOpen);
  const toggleAchievements = () => setIsAchievementsOpen(!isAchievementsOpen);

  const cycleReadAhead = () => {
      const levels: ReadAheadLevel[] = ['NONE', 'FOCUS', 'ULTRA', 'BLIND'];
      const currentIndex = levels.indexOf(settings.readAheadLevel);
      const nextIndex = (currentIndex + 1) % levels.length;
      setSettings({ ...settings, readAheadLevel: levels[nextIndex] });
      soundEngine.playKeypress(); // Feedback
  };

  const switchMode = (mode: GameMode) => {
    if (mode === 'FIX_MISTAKE' && mistakePool.length === 0) return;
    if (mode === 'HARDCORE' && isHardcoreLocked) return;
    setGameMode(mode);
    setQuotesQueue([]); 
    setCurrentQuote(null); 
  };

  const handleRequestNextQuote = async () => {
      setCurrentQuote(null);
      setQuoteStartTime(null);
  };

  const clearToast = useCallback(() => {
    setNotificationQueue(prev => prev.slice(1));
  }, []);

  // Helper for Read Ahead Icon/Color
  const getReadAheadConfig = () => {
      switch(settings.readAheadLevel) {
          case 'FOCUS': return { label: 'Focus', color: 'text-frog-600', bg: 'bg-frog-100', bonus: '+10%' };
          case 'ULTRA': return { label: 'Ultra', color: 'text-purple-600', bg: 'bg-purple-100', bonus: '+20%' };
          case 'BLIND': return { label: 'Blind', color: 'text-red-600', bg: 'bg-red-100', bonus: '+30%' };
          default: return { label: 'Off', color: 'text-stone-400', bg: 'hover:bg-stone-100', bonus: '' };
      }
  };
  const raConfig = getReadAheadConfig();

  return (
    <div className="min-h-screen flex flex-col bg-transparent text-stone-800 font-sans selection:bg-frog-200">
      <header className="w-full bg-stone-50/80 backdrop-blur-md border-b border-stone-200 sticky top-0 z-40 px-6 py-4 shadow-sm transition-all">
        <div className="max-w-[1400px] mx-auto flex flex-col xl:flex-row items-center justify-between gap-4 xl:gap-8">

          <div className="flex flex-col md:flex-row items-center gap-6 md:gap-8 w-full xl:w-auto">
            <div className="flex flex-col items-center md:items-start flex-shrink-0">
              <h1 className="text-xl font-black text-frog-800 tracking-tight flex items-center gap-2">
                <span className="text-2xl">🐸</span> Frog Type
              </h1>
            </div>

            <div className="flex gap-1 p-1 bg-stone-100/80 rounded-lg shadow-inner border border-stone-200/50">
              <button 
                  onClick={() => switchMode('QUOTES')}
                  className={`px-3 py-1.5 rounded-md text-xs font-bold flex items-center gap-1.5 transition-all focus:outline-none focus:ring-2 focus:ring-frog-500 focus:ring-offset-2 ${gameMode === 'QUOTES' ? 'bg-white text-frog-600 shadow-sm ring-1 ring-stone-200' : 'text-stone-400 hover:bg-stone-200/50 hover:text-stone-600'}`}
              >
                  <BookOpen className="w-3.5 h-3.5" /> Quotes
              </button>
              <button 
                  onClick={() => switchMode('HARDCORE')}
                  disabled={isHardcoreLocked}
                  title={isHardcoreLocked ? "Unlocks at Polliwog level" : "High risk, high reward"}
                  className={`px-3 py-1.5 rounded-md text-xs font-bold flex items-center gap-1.5 transition-all focus:outline-none focus:ring-2 focus:ring-frog-500 focus:ring-offset-2 
                    ${gameMode === 'HARDCORE' 
                      ? 'bg-stone-800 text-white shadow-sm ring-1 ring-stone-900' 
                      : isHardcoreLocked 
                          ? 'opacity-50 cursor-not-allowed text-stone-400 bg-stone-100' 
                          : 'text-stone-400 hover:bg-stone-200/50 hover:text-stone-600'}`}
              >
                  {isHardcoreLocked ? <Lock className="w-3.5 h-3.5" /> : <Skull className="w-3.5 h-3.5" />} 
                  Hardcore
              </button>
              <button 
                  onClick={() => switchMode('FIX_MISTAKE')}
                  disabled={mistakePool.length === 0}
                  className={`px-3 py-1.5 rounded-md text-xs font-bold flex items-center gap-1.5 transition-all focus:outline-none focus:ring-2 focus:ring-frog-500 focus:ring-offset-2 
                    ${gameMode === 'FIX_MISTAKE' ? 'bg-red-500 text-white shadow-sm ring-1 ring-red-600' : 'text-stone-400 hover:bg-stone-200/50 hover:text-stone-600'}
                    ${mistakePool.length === 0 ? 'opacity-50 cursor-not-allowed' : ''}
                  `}
                  title={mistakePool.length === 0 ? "No mistakes recorded yet" : `${mistakePool.length} words to fix`}
              >
                  <Eraser className="w-3.5 h-3.5" /> Fix ({mistakePool.length})
              </button>
            </div>
          </div>

          <div className="w-full xl:w-auto xl:flex-grow xl:max-w-2xl flex items-center gap-4 justify-end">
             <ProgressBar 
               xp={userXP} 
               avgWpm={getAverageWPM(wpmHistory)} 
               mistakeCount={mistakePool.length} 
             />

             <div className="flex items-center gap-1.5 border-l border-stone-200 pl-4 ml-2 shrink-0">
               <button 
                 onClick={cycleReadAhead}
                 className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-frog-500 focus:ring-offset-2 group relative ${raConfig.bg} ${raConfig.color}`}
                 title={`Read Ahead: ${raConfig.label} (${raConfig.bonus ? raConfig.bonus + ' XP' : 'No Bonus'})`}
               >
                  {settings.readAheadLevel === 'NONE' ? <Eye className="w-5 h-5" /> : <EyeOff className="w-5 h-5" />}
                  {raConfig.bonus && (
                      <span className="absolute -top-1 -right-1 bg-frog-500 text-white text-[8px] px-1 rounded-full font-bold">
                          {raConfig.bonus.replace('+','')}
                      </span>
                  )}
               </button>

               <button 
                 onClick={toggleAchievements} 
                 className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-frog-500 focus:ring-offset-2 ${isAchievementsOpen ? 'bg-stone-100 text-frog-600' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                 title="Achievements"
               >
                  <Award className="w-5 h-5" />
               </button>
               <button 
                 onClick={toggleTheme} 
                 className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-frog-500 focus:ring-offset-2 ${isThemeOpen ? 'bg-stone-100 text-frog-600' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                 title="Themes"
               >
                  <Palette className="w-5 h-5" />
               </button>
               <button 
                 onClick={toggleStats} 
                 className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-frog-500 focus:ring-offset-2 ${isStatsOpen ? 'bg-stone-100 text-frog-600' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                 title="Statistics & History"
               >
                  <TrendingUp className="w-5 h-5" />
               </button>
               <button 
                 onClick={toggleHelp} 
                 className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-frog-500 focus:ring-offset-2 ${isHelpOpen ? 'bg-stone-100 text-stone-700' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                 title="How to Play"
               >
                  <CircleHelp className="w-5 h-5" />
               </button>
               <button 
                 onClick={toggleMusic} 
                 className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-frog-500 focus:ring-offset-2 ${isMusicOpen || settings.musicConfig.source !== 'NONE' ? 'bg-stone-100 text-frog-600' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                 title="Background Music"
               >
                  <Music className="w-5 h-5" />
               </button>
               <button onClick={toggleSettings} className="p-2 hover:bg-stone-100 rounded-full text-stone-400 hover:text-stone-600 transition-colors focus:outline-none focus:ring-2 focus:ring-frog-500 focus:ring-offset-2">
                  <SettingsIcon className="w-5 h-5" />
               </button>
             </div>
          </div>

        </div>
      </header>

      <main className="flex-grow flex flex-col items-center justify-center p-6 md:p-12 w-full relative">
        <div className="w-full flex items-center justify-center min-h-[60vh]">
          {loading && !currentQuote ? (
            <div className="flex flex-col items-center justify-center text-stone-400 animate-pulse">
              <Loader2 className="w-10 h-10 animate-spin mb-4 text-frog-400" />
              <p className="font-mono text-xs">
                  Hatching wisdom...
              </p>
            </div>
          ) : currentQuote ? (
            <TypingArea 
              quote={currentQuote} 
              onComplete={handleQuoteComplete} 
              onFail={handleQuoteFail}
              onMistake={handleMistake}
              onRequestNewQuote={handleRequestNextQuote}
              streak={streak}
              ghostWpm={getAverageWPM(wpmHistory)}
              settings={settings}
              gameMode={gameMode}
              onInteract={() => setIsMusicOpen(false)}
            />
          ) : (
             <div className="flex flex-col items-center justify-center text-stone-400">
              <Loader2 className="w-10 h-10 animate-spin mb-4 text-frog-400" />
              <p className="font-mono text-xs">Fetching wisdom...</p>
            </div>
          )}
        </div>
      </main>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        settings={settings} 
        setSettings={setSettings} 
      />

      <ThemeModal
        isOpen={isThemeOpen}
        onClose={() => setIsThemeOpen(false)}
        currentThemeId={settings.themeId}
        setThemeId={(id) => setSettings({ ...settings, themeId: id })}
        currentLevel={getCurrentLevel(userXP)}
        allLevels={LEVELS}
      />

      <AchievementsModal
        isOpen={isAchievementsOpen}
        onClose={() => setIsAchievementsOpen(false)}
        unlockedIds={unlockedAchievements}
      />

      <AchievementToast 
        notifications={notificationQueue}
        onClear={clearToast}
      />

      <HelpModal
        isOpen={isHelpOpen}
        onClose={() => setIsHelpOpen(false)}
      />

      <StatsModal
        isOpen={isStatsOpen}
        onClose={() => setIsStatsOpen(false)}
        avgWpm={getAverageWPM(wpmHistory)}
        history={testHistory}
        onPractice={handlePracticeFromHistory}
        totalTime={totalTimePlayed}
        joinDate={joinDate}
        streak={dailyStreak} // Pass Daily Streak here instead of Session Streak
        userName={userName}
        setUserName={setUserName}
        completedTestsCount={testHistory.length}
      />

      <MusicPlayer 
        isOpen={isMusicOpen} 
        onClose={() => setIsMusicOpen(false)} 
        settings={settings}
        setSettings={setSettings}
        userXP={userXP}
      />

      <footer className="p-6 text-center text-stone-300 text-[10px]">
        <p>© {new Date().getFullYear()} Frog Type. Wisdom from the Ages.</p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useLayoutEffect, useRef } from 'react';
import ProgressBar from './components/ProgressBar';
import TypingArea from './components/TypingArea';
import SettingsModal from './components/SettingsModal';
import HelpModal from './components/HelpModal';
import StatsModal from './components/StatsModal';
import ThemeModal from './components/ThemeModal';
import AchievementsModal from './components/AchievementsModal';
import AchievementToast from './components/AchievementToast';
import { MusicPlayer } from './components/MusicPlayer';
import { Quote, Settings, GameMode, TestResult, NotificationItem, ReadAheadLevel } from './types';
import { fetchQuotes } from './services/quoteService';
import { getCurrentLevel, getNextLevel, getAverageWPM, LEVELS, calculateXP } from './utils/gameLogic';
import { soundEngine } from './utils/soundEngine';
import { Loader2, Settings as SettingsIcon, Music, CircleHelp, Skull, BookOpen, Eraser, TrendingUp, Palette, Award, Radio, Lock, Eye, EyeOff, Flame } from 'lucide-react';
import confetti from 'canvas-confetti';
import { THEMES } from './data/themes';
import { ACHIEVEMENTS } from './data/achievements';
import { RADIO_STATIONS } from './data/radioStations';

const App: React.FC = () => {
  // User Stats Persistence
  const [userName, setUserName] = useState<string>(() => {
      return localStorage.getItem('frogType_userName') || 'Froggy';
  });

  const [joinDate, setJoinDate] = useState<string>(() => {
      const stored = localStorage.getItem('frogType_joinDate');
      if (stored) return stored;
      const now = new Date().toISOString();
      localStorage.setItem('frogType_joinDate', now);
      return now;
  });

  const [totalTimePlayed, setTotalTimePlayed] = useState<number>(() => {
      const stored = localStorage.getItem('frogType_totalTime');
      return stored ? parseInt(stored, 10) : 0;
  });

  const [userXP, setUserXP] = useState<number>(() => {
    const saved = localStorage.getItem('frogXP');
    const legacy = localStorage.getItem('frogType_xp');
    if (saved) return parseInt(saved, 10);
    if (legacy) return parseInt(legacy, 10);
    return 0;
  });

  const currentLevel = getCurrentLevel(userXP);

  // Track unlocked tiers persistently to prevent repeat notifications
  const [unlockedTiers, setUnlockedTiers] = useState<string[]>(() => {
    const saved = localStorage.getItem('frogType_unlockedTiers');
    return saved ? JSON.parse(saved) : [];
  });

  // Session Streak (Consecutive Quotes)
  const [streak, setStreak] = useState<number>(() => {
    const saved = localStorage.getItem('frogType_streak');
    return saved ? parseInt(saved, 10) : 0;
  });

  // Daily Streak Logic
  const [dailyStreak, setDailyStreak] = useState<number>(() => {
     const saved = localStorage.getItem('frogType_dailyStreak');
     return saved ? parseInt(saved, 10) : 0;
  });

  const [unlockedAchievements, setUnlockedAchievements] = useState<string[]>(() => {
    const saved = localStorage.getItem('frogType_achievements');
    return saved ? JSON.parse(saved) : [];
  });

  const [notificationQueue, setNotificationQueue] = useState<NotificationItem[]>([]);

  // Track history for average WPM calculation (Last 10)
  const [wpmHistory, setWpmHistory] = useState<number[]>(() => {
    const saved = localStorage.getItem('frogType_wpmHistory');
    return saved ? JSON.parse(saved) : [];
  });

  // Track full history of tests
  const [testHistory, setTestHistory] = useState<TestResult[]>(() => {
    const saved = localStorage.getItem('frogType_history');
    return saved ? JSON.parse(saved) : [];
  });

  const [lastWpm, setLastWpm] = useState<number>(() => {
    const saved = localStorage.getItem('frogType_lastWpm');
    return saved ? parseInt(saved, 10) : 0;
  });

  const [mistakePool, setMistakePool] = useState<string[]>(() => {
    const saved = localStorage.getItem('frogType_mistakes');
    return saved ? JSON.parse(saved) : [];
  });

  const [settings, setSettings] = useState<Settings>(() => {
    const saved = localStorage.getItem('frogType_settings');

    if (!saved) {
      return { 
        ghostEnabled: false, 
        readAheadLevel: 'NONE', 
        sfxEnabled: true,
        mechanicalSoundEnabled: false,
        mechanicalSoundPreset: 'THOCK',
        ambientVolume: 0.02, 
        musicConfig: { source: 'GENERATED', presetId: 'PIANO_SATIE' },
        themeId: 'CLASSIC'
      };
    }

    const parsed = JSON.parse(saved);
    const legacyBrownNoiseEnabled = parsed.brownNoiseEnabled === true;
    const legacyVolume = parsed.brownNoiseVolume ?? 0.5;

    // Migration for legacy boolean readAhead
    let initialReadAhead = parsed.readAheadLevel;
    if (parsed.readAheadEnabled === true && !initialReadAhead) initialReadAhead = 'FOCUS';
    if (!initialReadAhead) initialReadAhead = 'NONE';

    let initialMusicConfig = parsed.musicConfig || { source: 'NONE', presetId: '' };
    if (legacyBrownNoiseEnabled && initialMusicConfig.source === 'NONE') {
        initialMusicConfig = { source: 'GENERATED', presetId: 'BROWN_NOISE' };
    }

    return { 
      ghostEnabled: false, 
      readAheadLevel: initialReadAhead, 
      sfxEnabled: true,
      mechanicalSoundEnabled: parsed.mechanicalSoundEnabled ?? false,
      mechanicalSoundPreset: parsed.mechanicalSoundPreset || 'THOCK',
      ambientVolume: parsed.ambientVolume ?? legacyVolume, 
      musicConfig: initialMusicConfig,
      themeId: parsed.themeId || 'CLASSIC',
      ...parsed
    };
  });

  const [gameMode, setGameMode] = useState<GameMode>(() => {
    const saved = localStorage.getItem('frogType_gameMode');
    return (saved as GameMode) || 'QUOTES';
  });

  const [completedQuotes, setCompletedQuotes] = useState<string[]>(() => {
    const saved = localStorage.getItem('frogType_completedQuotes');
    return saved ? JSON.parse(saved) : [];
  });

  const [quotesQueue, setQuotesQueue] = useState<Quote[]>([]);

  const [currentQuote, setCurrentQuote] = useState<Quote | null>(() => {
    const saved = localStorage.getItem('frogType_currentQuote');
    return saved ? JSON.parse(saved) : null;
  });

  const [loading, setLoading] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isMusicOpen, setIsMusicOpen] = useState(false);
  const [isHelpOpen, setIsHelpOpen] = useState(false);
  const [isStatsOpen, setIsStatsOpen] = useState(false);
  const [isThemeOpen, setIsThemeOpen] = useState(false);
  const [isAchievementsOpen, setIsAchievementsOpen] = useState(false);

  // Start time tracking for current quote
  const [quoteStartTime, setQuoteStartTime] = useState<number | null>(null);

  const isFetchingRef = useRef(false);

  // Derive Lock State
  const uniqueTiers = Array.from(new Set(LEVELS.map(l => l.tier)));
  const currentTierIndex = uniqueTiers.indexOf(currentLevel.tier);
  const polliwogIndex = uniqueTiers.indexOf('Polliwog');
  const isHardcoreLocked = currentTierIndex < polliwogIndex;

  // Persistence
  useEffect(() => { localStorage.setItem('frogXP', userXP.toString()); }, [userXP]);
  useEffect(() => { localStorage.setItem('frogType_unlockedTiers', JSON.stringify(unlockedTiers)); }, [unlockedTiers]);
  useEffect(() => { localStorage.setItem('frogType_streak', streak.toString()); }, [streak]);
  useEffect(() => { localStorage.setItem('frogType_dailyStreak', dailyStreak.toString()); }, [dailyStreak]);
  useEffect(() => { localStorage.setItem('frogType_lastWpm', lastWpm.toString()); }, [lastWpm]);
  useEffect(() => { localStorage.setItem('frogType_wpmHistory', JSON.stringify(wpmHistory)); }, [wpmHistory]);
  useEffect(() => { localStorage.setItem('frogType_history', JSON.stringify(testHistory)); }, [testHistory]);
  useEffect(() => { localStorage.setItem('frogType_settings', JSON.stringify(settings)); }, [settings]);
  useEffect(() => { localStorage.setItem('frogType_mistakes', JSON.stringify(mistakePool)); }, [mistakePool]);
  useEffect(() => { localStorage.setItem('frogType_userName', userName); }, [userName]);
  useEffect(() => { localStorage.setItem('frogType_totalTime', totalTimePlayed.toString()); }, [totalTimePlayed]);

  // Game Mode Persistence & Lock Check
  useEffect(() => { 
      if (gameMode === 'HARDCORE' && isHardcoreLocked) {
          setGameMode('QUOTES');
      }
      localStorage.setItem('frogType_gameMode', gameMode); 
  }, [gameMode, isHardcoreLocked]);

  useEffect(() => { localStorage.setItem('frogType_completedQuotes', JSON.stringify(completedQuotes)); }, [completedQuotes]);
  useEffect(() => { localStorage.setItem('frogType_achievements', JSON.stringify(unlockedAchievements)); }, [unlockedAchievements]);

  // Audio Settings Sync
  useEffect(() => {
    soundEngine.setEnabled(settings.sfxEnabled);
    soundEngine.setMechanicalEnabled(settings.mechanicalSoundEnabled);
    soundEngine.setMechanicalPreset(settings.mechanicalSoundPreset);
    soundEngine.setAmbientVolume(settings.ambientVolume);

    if (settings.musicConfig.source === 'GENERATED') {
      soundEngine.setAmbientMusic(settings.musicConfig.presetId);
    } else {
      soundEngine.stopAmbientMusic();
    }
  }, [settings.sfxEnabled, settings.mechanicalSoundEnabled, settings.mechanicalSoundPreset, settings.ambientVolume, settings.musicConfig]);

  useLayoutEffect(() => {
    const theme = THEMES.find(t => t.id === settings.themeId) || THEMES[0];
    const root = document.documentElement;
    root.style.setProperty('--bg-body', theme.colors.background);
    Object.entries(theme.colors.frog).forEach(([key, value]) => {
       root.style.setProperty(`--frog-${key}`, value);
    });
    Object.entries(theme.colors.stone).forEach(([key, value]) => {
       root.style.setProperty(`--stone-${key}`, value);
    });
    root.style.setProperty('--text-body', theme.colors.stone[800]);
  }, [settings.themeId]);

  useEffect(() => {
    const handleInteraction = () => {
      soundEngine.resumeContext();
      window.removeEventListener('click', handleInteraction);
      window.removeEventListener('keydown', handleInteraction);
    };

    window.addEventListener('click', handleInteraction);
    window.addEventListener('keydown', handleInteraction);
    return () => {
      window.removeEventListener('click', handleInteraction);
      window.removeEventListener('keydown', handleInteraction);
    };
  }, []);

  useEffect(() => { 
    if (currentQuote) {
      localStorage.setItem('frogType_currentQuote', JSON.stringify(currentQuote)); 
      setQuoteStartTime(Date.now());
    } else {
      localStorage.removeItem('frogType_currentQuote');
    }
  }, [currentQuote]);

  // Check Daily Streak on Mount
  useEffect(() => {
      const today = new Date().toDateString();
      const lastVisit = localStorage.getItem('frogType_lastVisitDate');

      // If user hasn't visited today, check if streak should break
      if (lastVisit && lastVisit !== today) {
          const yesterday = new Date();
          yesterday.setDate(yesterday.getDate() - 1);

          if (yesterday.toDateString() !== lastVisit) {
              // Streak broken if last visit was not yesterday
              setDailyStreak(0);
          }
      } else if (!lastVisit) {
          setDailyStreak(0);
      }
  }, []);

  const updateDailyStreakActivity = () => {
      const today = new Date().toDateString();
      const lastVisit = localStorage.getItem('frogType_lastVisitDate');

      if (lastVisit !== today) {
          // New day activity
          let newStreak = 1;
          if (lastVisit) {
              const yesterday = new Date();
              yesterday.setDate(yesterday.getDate() - 1);
              if (yesterday.toDateString() === lastVisit) {
                  newStreak = dailyStreak + 1;
              }
          }
          setDailyStreak(newStreak);
          localStorage.setItem('frogType_lastVisitDate', today);

          // Toast for streak
          setNotificationQueue(prev => [...prev, {
              id: `daily_${Date.now()}`,
              title: "Daily Streak!",
              description: `You're on a ${newStreak} day streak.`,
              icon: <Flame className="w-5 h-5 text-orange-500" />,
              type: "INFO"
          }]);
      } else {
          // Already played today, ensure streak is at least 1 if it was 0
          if (dailyStreak === 0) {
              setDailyStreak(1);
              localStorage.setItem('frogType_lastVisitDate', today);
          }
      }
  };

  const generateMistakeQuote = useCallback((): Quote | null => {
    if (mistakePool.length === 0) return null;
    let pool = [...mistakePool];
    while (pool.length < 15) {
       pool = [...pool, ...mistakePool];
    }
    const shuffled = pool.sort(() => 0.5 - Math.random());
    const selected = shuffled.slice(0, 15);
    const text = selected.join(' ');

    return {
      text,
      source: "Personal Training",
      author: "Your Mistakes"
    };
  }, [mistakePool]);

  const loadMoreQuotes = useCallback(async () => {
    if (isFetchingRef.current) return;

    isFetchingRef.current = true;

    try {
      const level = getCurrentLevel(userXP);
      // IMPORTANT: Pass completedQuotes to filter them out forever
      const newQuotes = await fetchQuotes(5, completedQuotes, level.tier, gameMode);
      setQuotesQueue(prev => [...prev, ...newQuotes]);
    } catch (error) {
      console.error("Failed to load quotes", error);
    } finally {
      isFetchingRef.current = false;
    }
  }, [completedQuotes, userXP, gameMode]);

  useEffect(() => {
    const init = async () => {
      if (!currentQuote && quotesQueue.length === 0) {
         setLoading(true);
         await loadMoreQuotes();
         setLoading(false);
      } else if (quotesQueue.length < 3) {
         loadMoreQuotes();
      }
    };
    init();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (currentQuote) return;

    if (gameMode === 'FIX_MISTAKE') {
      const mistakeQuote = generateMistakeQuote();
      if (mistakeQuote) {
        setCurrentQuote(mistakeQuote);
      } else {
        setGameMode('QUOTES'); 
      }
    } else {
      if (quotesQueue.length > 0) {
        const next = quotesQueue[0];
        setCurrentQuote(next);
        setQuotesQueue(prev => prev.slice(1));
      }

      if (quotesQueue.length < 3) {
        loadMoreQuotes();
      }
    }
  }, [currentQuote, quotesQueue, gameMode, generateMistakeQuote, loadMoreQuotes]);

  const checkAchievements = (wpm: number) => {
    const newNotifications: NotificationItem[] = [];
    const newUnlockIds: string[] = [];

    const stats = {
       wpm,
       totalQuotes: completedQuotes.length + 1, 
       maxStreak: Math.max(streak + 1, streak + 1),
       currentStreak: streak + 1,
       mode: gameMode
    };

    ACHIEVEMENTS.forEach(ach => {
       if (!unlockedAchievements.includes(ach.id)) {
           if (ach.condition(stats)) {
               newUnlockIds.push(ach.id);
               newNotifications.push({
                   id: ach.id,
                   title: ach.title,
                   description: ach.description,
                   icon: ach.icon,
                   type: 'ACHIEVEMENT'
               });
           }
       }
    });

    if (newUnlockIds.length > 0) {
       setUnlockedAchievements(prev => [...prev, ...newUnlockIds]);
       setNotificationQueue(prev => [...prev, ...newNotifications]);
       soundEngine.playLevelUp(); 
    }
  };

  const handleQuoteComplete = (xpCalc: number, wpm: number, mistakes: string[], retryCount: number) => {
    // Recalculate with Read Ahead Bonus (if any changed since TypingArea)
    // Actually simpler to pass raw WPM/Length and recalc here or trust TypingArea passed value.
    // TypingArea uses calculateXP so it already includes ReadAhead bonus from settings passed to it.
    let finalXp = xpCalc; 

    // Update Time Played
    if (quoteStartTime) {
        const durationSec = Math.floor((Date.now() - quoteStartTime) / 1000);
        setTotalTimePlayed(prev => prev + durationSec);
    }

    if (gameMode === 'HARDCORE') {
      finalXp = finalXp * 5;
    }

    // Fix Mistake Mode Logic
    if (gameMode === 'FIX_MISTAKE' && currentQuote) {
      const wordsFixed = [...new Set(currentQuote.text.split(' '))]; 
      setMistakePool(prev => prev.filter(word => !wordsFixed.includes(word)));
    }

    // Mark quote as completed so it never shows again (if in standard modes)
    if (currentQuote && gameMode !== 'FIX_MISTAKE') {
       setCompletedQuotes(prev => [...prev, currentQuote.text]);
    }

    // Update History
    const newHistory = [...wpmHistory, wpm].slice(-10); 
    setWpmHistory(newHistory);
    const avgWpm = getAverageWPM(newHistory);

    const newTestResult: TestResult = {
      id: Date.now(),
      date: new Date().toISOString(),
      wpm,
      xpEarned: finalXp,
      mode: gameMode,
      quoteText: currentQuote?.text || "",
      mistakes: mistakes,
      retryCount: retryCount
    };
    setTestHistory(prev => [...prev, newTestResult]);

    checkAchievements(wpm);

    // Calculate XP and Handle Gates/Unlocks
    const currentLevelObj = getCurrentLevel(userXP);
    const nextLevelObj = getNextLevel(currentLevelObj);
    let potentialXp = userXP + finalXp;

    if (nextLevelObj && potentialXp >= nextLevelObj.minXP) {
         let effectiveMistakeCount = mistakePool.length;
         if (gameMode === 'FIX_MISTAKE' && currentQuote) {
             const wordsFixed = [...new Set(currentQuote.text.split(' '))];
             effectiveMistakeCount = mistakePool.filter(word => !wordsFixed.includes(word)).length;
         }

         const isMasteryGated = effectiveMistakeCount > 0;
         const isSpeedGated = avgWpm < nextLevelObj.requiredWpm;

         if (isMasteryGated || isSpeedGated) {
            potentialXp = nextLevelObj.minXP - 1; 
         }
    }

    const newLevel = getCurrentLevel(potentialXp);

    // Check for Tier Unlocks (Persistent - Only once per tier)
    if (!unlockedTiers.includes(newLevel.tier)) {
         setUnlockedTiers(prev => [...prev, newLevel.tier]);

         const newStations = RADIO_STATIONS.filter(s => s.tier === newLevel.tier);

         if (newStations.length > 0) {
             const musicNotifications: NotificationItem[] = newStations.map(s => ({
                id: `unlock_${s.id}`,
                title: 'New Station Unlocked',
                description: s.name,
                icon: <Radio className="w-5 h-5 text-stone-900" />,
                type: 'UNLOCK'
             }));
             setNotificationQueue(prev => [...prev, ...musicNotifications]);
         }
    }

    const prevLevel = getCurrentLevel(userXP);
    if (newLevel.tier !== prevLevel.tier && potentialXp >= newLevel.minXP) {
          setTimeout(() => {
              confetti({
                particleCount: 200,
                spread: 120,
                origin: { y: 0.6 },
                colors: ['#d1fae5', '#10b981', '#fbbf24', '#f59e0b'],
                startVelocity: 45
              });
              soundEngine.playLevelUp(); 
          }, 300);
    }

    setUserXP(potentialXp);
    setStreak(prev => prev + 1);

    // Update Daily Streak
    updateDailyStreakActivity();

    setLastWpm(wpm);
    setCurrentQuote(null); 
    setQuoteStartTime(null);
  };

  const handleQuoteFail = () => {
    setStreak(0);
  };

  const handleMistake = (word?: string) => {
    const penaltyMultiplier = gameMode === 'HARDCORE' ? 0.5 : 0.85;
    setUserXP(prev => Math.floor(prev * penaltyMultiplier));

    setStreak(0);

    if (word && word.length > 1) {
       setMistakePool(prev => {
         if (prev.includes(word)) return prev;
         return [...prev, word];
       });
    }
  };

  const handlePracticeFromHistory = (mistakes: string[]) => {
      setMistakePool(prev => {
          const newSet = new Set([...prev, ...mistakes]);
          return Array.from(newSet);
      });
      switchMode('FIX_MISTAKE');
  };

  const toggleSettings = () => setIsSettingsOpen(!isSettingsOpen);
  const toggleMusic = () => setIsMusicOpen(!isMusicOpen);
  const toggleHelp = () => setIsHelpOpen(!isHelpOpen);
  const toggleStats = () => setIsStatsOpen(!isStatsOpen);
  const toggleTheme = () => setIsThemeOpen(!isThemeOpen);
  const toggleAchievements = () => setIsAchievementsOpen(!isAchievementsOpen);

  const cycleReadAhead = () => {
      const levels: ReadAheadLevel[] = ['NONE', 'FOCUS', 'ULTRA', 'BLIND'];
      const currentIndex = levels.indexOf(settings.readAheadLevel);
      const nextIndex = (currentIndex + 1) % levels.length;
      setSettings({ ...settings, readAheadLevel: levels[nextIndex] });
      soundEngine.playKeypress(); // Feedback
  };

  const switchMode = (mode: GameMode) => {
    if (mode === 'FIX_MISTAKE' && mistakePool.length === 0) return;
    if (mode === 'HARDCORE' && isHardcoreLocked) return;
    setGameMode(mode);
    setQuotesQueue([]); 
    setCurrentQuote(null); 
  };

  const handleRequestNextQuote = async () => {
      setCurrentQuote(null);
      setQuoteStartTime(null);
  };

  const clearToast = useCallback(() => {
    setNotificationQueue(prev => prev.slice(1));
  }, []);

  // Helper for Read Ahead Icon/Color
  const getReadAheadConfig = () => {
      switch(settings.readAheadLevel) {
          case 'FOCUS': return { label: 'Focus', color: 'text-frog-600', bg: 'bg-frog-100', bonus: '+10%' };
          case 'ULTRA': return { label: 'Ultra', color: 'text-purple-600', bg: 'bg-purple-100', bonus: '+20%' };
          case 'BLIND': return { label: 'Blind', color: 'text-red-600', bg: 'bg-red-100', bonus: '+30%' };
          default: return { label: 'Off', color: 'text-stone-400', bg: 'hover:bg-stone-100', bonus: '' };
      }
  };
  const raConfig = getReadAheadConfig();

  return (
    <div className="min-h-screen flex flex-col bg-transparent text-stone-800 font-sans selection:bg-frog-200">
      <header className="w-full bg-stone-50/80 backdrop-blur-md border-b border-stone-200 sticky top-0 z-40 px-6 py-4 shadow-sm transition-all">
        <div className="max-w-[1400px] mx-auto flex flex-col xl:flex-row items-center justify-between gap-4 xl:gap-8">

          <div className="flex flex-col md:flex-row items-center gap-6 md:gap-8 w-full xl:w-auto">
            <div className="flex flex-col items-center md:items-start flex-shrink-0">
              <h1 className="text-xl font-black text-dino-400 tracking-tight flex items-center gap-2">
                <span className="text-2xl">🐸</span> Frog Type
              </h1>
            </div>

            <div className="flex gap-1 p-1 bg-stone-100/80 rounded-lg shadow-inner border border-stone-200/50">
              <button 
                  onClick={() => switchMode('QUOTES')}
                  className={`px-3 py-1.5 rounded-md text-xs font-bold flex items-center gap-1.5 transition-all focus:outline-none focus:ring-2 focus:ring-frog-500 focus:ring-offset-2 ${gameMode === 'QUOTES' ? 'bg-white text-frog-600 shadow-sm ring-1 ring-stone-200' : 'text-stone-400 hover:bg-stone-200/50 hover:text-stone-600'}`}
              >
                  <BookOpen className="w-3.5 h-3.5" /> Quotes
              </button>
              <button 
                  onClick={() => switchMode('HARDCORE')}
                  disabled={isHardcoreLocked}
                  title={isHardcoreLocked ? "Unlocks at Polliwog level" : "High risk, high reward"}
                  className={`px-3 py-1.5 rounded-md text-xs font-bold flex items-center gap-1.5 transition-all focus:outline-none focus:ring-2 focus:ring-frog-500 focus:ring-offset-2 
                    ${gameMode === 'HARDCORE' 
                      ? 'bg-stone-800 text-white shadow-sm ring-1 ring-stone-900' 
                      : isHardcoreLocked 
                          ? 'opacity-50 cursor-not-allowed text-stone-400 bg-stone-100' 
                          : 'text-stone-400 hover:bg-stone-200/50 hover:text-stone-600'}`}
              >
                  {isHardcoreLocked ? <Lock className="w-3.5 h-3.5" /> : <Skull className="w-3.5 h-3.5" />} 
                  Hardcore
              </button>
              <button 
                  onClick={() => switchMode('FIX_MISTAKE')}
                  disabled={mistakePool.length === 0}
                  className={`px-3 py-1.5 rounded-md text-xs font-bold flex items-center gap-1.5 transition-all focus:outline-none focus:ring-2 focus:ring-frog-500 focus:ring-offset-2 
                    ${gameMode === 'FIX_MISTAKE' ? 'bg-red-500 text-white shadow-sm ring-1 ring-red-600' : 'text-stone-400 hover:bg-stone-200/50 hover:text-stone-600'}
                    ${mistakePool.length === 0 ? 'opacity-50 cursor-not-allowed' : ''}
                  `}
                  title={mistakePool.length === 0 ? "No mistakes recorded yet" : `${mistakePool.length} words to fix`}
              >
                  <Eraser className="w-3.5 h-3.5" /> Fix ({mistakePool.length})
              </button>
            </div>
          </div>

          <div className="w-full xl:w-auto xl:flex-grow xl:max-w-2xl flex items-center gap-4 justify-end">
             <ProgressBar 
               xp={userXP} 
               avgWpm={getAverageWPM(wpmHistory)} 
               mistakeCount={mistakePool.length} 
             />

             <div className="flex items-center gap-1.5 border-l border-stone-200 pl-4 ml-2 shrink-0">
               <button 
                 onClick={cycleReadAhead}
                 className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-frog-500 focus:ring-offset-2 group relative ${raConfig.bg} ${raConfig.color}`}
                 title={`Read Ahead: ${raConfig.label} (${raConfig.bonus ? raConfig.bonus + ' XP' : 'No Bonus'})`}
               >
                  {settings.readAheadLevel === 'NONE' ? <Eye className="w-5 h-5" /> : <EyeOff className="w-5 h-5" />}
                  {raConfig.bonus && (
                      <span className="absolute -top-1 -right-1 bg-frog-500 text-white text-[8px] px-1 rounded-full font-bold">
                          {raConfig.bonus.replace('+','')}
                      </span>
                  )}
               </button>

               <button 
                 onClick={toggleAchievements} 
                 className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-frog-500 focus:ring-offset-2 ${isAchievementsOpen ? 'bg-stone-100 text-frog-600' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                 title="Achievements"
               >
                  <Award className="w-5 h-5" />
               </button>
               <button 
                 onClick={toggleTheme} 
                 className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-frog-500 focus:ring-offset-2 ${isThemeOpen ? 'bg-stone-100 text-frog-600' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                 title="Themes"
               >
                  <Palette className="w-5 h-5" />
               </button>
               <button 
                 onClick={toggleStats} 
                 className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-frog-500 focus:ring-offset-2 ${isStatsOpen ? 'bg-stone-100 text-frog-600' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                 title="Statistics & History"
               >
                  <TrendingUp className="w-5 h-5" />
               </button>
               <button 
                 onClick={toggleHelp} 
                 className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-frog-500 focus:ring-offset-2 ${isHelpOpen ? 'bg-stone-100 text-stone-700' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                 title="How to Play"
               >
                  <CircleHelp className="w-5 h-5" />
               </button>
               <button 
                 onClick={toggleMusic} 
                 className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-frog-500 focus:ring-offset-2 ${isMusicOpen || settings.musicConfig.source !== 'NONE' ? 'bg-stone-100 text-frog-600' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                 title="Background Music"
               >
                  <Music className="w-5 h-5" />
               </button>
               <button onClick={toggleSettings} className="p-2 hover:bg-stone-100 rounded-full text-stone-400 hover:text-stone-600 transition-colors focus:outline-none focus:ring-2 focus:ring-frog-500 focus:ring-offset-2">
                  <SettingsIcon className="w-5 h-5" />
               </button>
             </div>
          </div>

        </div>
      </header>

      <main className="flex-grow flex flex-col items-center justify-center p-6 md:p-12 w-full relative">
        <div className="w-full flex items-center justify-center min-h-[60vh]">
          {loading && !currentQuote ? (
            <div className="flex flex-col items-center justify-center text-stone-400 animate-pulse">
              <Loader2 className="w-10 h-10 animate-spin mb-4 text-frog-400" />
              <p className="font-mono text-xs">
                  Hatching wisdom...
              </p>
            </div>
          ) : currentQuote ? (
            <TypingArea 
              quote={currentQuote} 
              onComplete={handleQuoteComplete} 
              onFail={handleQuoteFail}
              onMistake={handleMistake}
              onRequestNewQuote={handleRequestNextQuote}
              streak={streak}
              ghostWpm={getAverageWPM(wpmHistory)}
              settings={settings}
              gameMode={gameMode}
              onInteract={() => setIsMusicOpen(false)}
            />
          ) : (
             <div className="flex flex-col items-center justify-center text-stone-400">
              <Loader2 className="w-10 h-10 animate-spin mb-4 text-frog-400" />
              <p className="font-mono text-xs">Fetching wisdom...</p>
            </div>
          )}
        </div>
      </main>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        settings={settings} 
        setSettings={setSettings} 
      />

      <ThemeModal
        isOpen={isThemeOpen}
        onClose={() => setIsThemeOpen(false)}
        currentThemeId={settings.themeId}
        setThemeId={(id) => setSettings({ ...settings, themeId: id })}
        currentLevel={getCurrentLevel(userXP)}
        allLevels={LEVELS}
      />

      <AchievementsModal
        isOpen={isAchievementsOpen}
        onClose={() => setIsAchievementsOpen(false)}
        unlockedIds={unlockedAchievements}
      />

      <AchievementToast 
        notifications={notificationQueue}
        onClear={clearToast}
      />

      <HelpModal
        isOpen={isHelpOpen}
        onClose={() => setIsHelpOpen(false)}
      />

      <StatsModal
        isOpen={isStatsOpen}
        onClose={() => setIsStatsOpen(false)}
        avgWpm={getAverageWPM(wpmHistory)}
        history={testHistory}
        onPractice={handlePracticeFromHistory}
        totalTime={totalTimePlayed}
        joinDate={joinDate}
        streak={dailyStreak} // Pass Daily Streak here instead of Session Streak
        userName={userName}
        setUserName={setUserName}
        completedTestsCount={testHistory.length}
      />

      <MusicPlayer 
        isOpen={isMusicOpen} 
        onClose={() => setIsMusicOpen(false)} 
        settings={settings}
        setSettings={setSettings}
        userXP={userXP}
      />

      <footer className="p-6 text-center text-stone-300 text-[10px]">
        <p>© {new Date().getFullYear()} Frog Type. Wisdom from the Ages.</p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback, useLayoutEffect } from 'react';
import { Quote, GameStatus, Settings, GameMode } from '../types';
import { calculateXP } from '../utils/gameLogic';
import { soundEngine } from '../utils/soundEngine';
import { Play, RotateCcw, Award, Flame, Ghost, EyeOff, Quote as QuoteIcon, Skull, Eraser, Lock, Sparkles, ArrowUp } from 'lucide-react';

interface TypingAreaProps {
  quote: Quote;
  onComplete: (xpEarned: number, wpm: number, mistakes: string[], retryCount: number) => void;
  onFail: () => void;
  onMistake: (word?: string) => void;
  onRequestNewQuote: () => void;
  streak: number;
  ghostWpm: number;
  settings: Settings;
  gameMode: GameMode;
  onInteract?: () => void;
}

const TypingArea: React.FC<TypingAreaProps> = ({ 
  quote, 
  onComplete, 
  onFail, 
  onMistake,
  onRequestNewQuote,
  streak,
  ghostWpm,
  settings,
  gameMode,
  onInteract
}) => {
  const [input, setInput] = useState('');
  const [startTime, setStartTime] = useState<number | null>(null);
  const [endTime, setEndTime] = useState<number | null>(null);
  const [isFocused, setIsFocused] = useState(false);
  const [status, setStatus] = useState<GameStatus>(GameStatus.IDLE);
  const [wpm, setWpm] = useState(0);
  const [ghostIndex, setGhostIndex] = useState(0);
  const [capsLock, setCapsLock] = useState(false);
  const [isShiftPressed, setIsShiftPressed] = useState(false);

  // Tracking Stats
  const [sessionMistakes, setSessionMistakes] = useState(0);
  const [sessionMistakeWords, setSessionMistakeWords] = useState<string[]>([]);
  const [retryCount, setRetryCount] = useState(0);

  // Smooth Caret State
  const [caretPos, setCaretPos] = useState({ left: 0, top: 0, height: 24, opacity: 0 });

  const inputRef = useRef<HTMLTextAreaElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const textContainerRef = useRef<HTMLDivElement>(null);
  const nextButtonRef = useRef<HTMLButtonElement>(null);
  const retryButtonRef = useRef<HTMLButtonElement>(null);

  // Sync Settings with Engine
  useEffect(() => {
    soundEngine.setEnabled(settings.sfxEnabled);
  }, [settings.sfxEnabled]);

  // Reset state when quote changes
  useEffect(() => {
    setInput('');
    setStartTime(null);
    setEndTime(null);
    setStatus(GameStatus.IDLE);
    setWpm(0);
    setGhostIndex(0);
    setSessionMistakes(0);
    setSessionMistakeWords([]);
    setRetryCount(0);
    if (isFocused) {
        inputRef.current?.focus();
    }
  }, [quote, isFocused]);

  // Focus management for buttons when game ends
  useEffect(() => {
    if (status === GameStatus.COMPLETED) {
        setTimeout(() => nextButtonRef.current?.focus(), 50);
    } else if (status === GameStatus.FAILED) {
        setTimeout(() => retryButtonRef.current?.focus(), 50);
    }
  }, [status]);

  // Handlers wrapped in useCallback for stable dependencies
  const handleRetry = useCallback(() => {
    setInput('');
    setStartTime(null);
    setEndTime(null);
    setStatus(GameStatus.IDLE);
    setWpm(0);
    setGhostIndex(0);
    setSessionMistakes(0); 
    setRetryCount(prev => prev + 1);
    setIsFocused(true);
    setTimeout(() => inputRef.current?.focus(), 10);
  }, []);

  const handleNext = useCallback(() => {
    const isPerfectMaster = retryCount === 0 && sessionMistakes === 0;
    const xp = calculateXP(wpm, quote.text.length, streak, isPerfectMaster, settings.readAheadLevel);
    onComplete(xp, wpm, sessionMistakeWords, retryCount);
  }, [onComplete, wpm, quote.text.length, streak, retryCount, sessionMistakes, sessionMistakeWords, settings.readAheadLevel]);

  // Caps Lock & Shift Detection
  useEffect(() => {
    const checkCapsLock = (e: KeyboardEvent | MouseEvent) => {
      if (e.getModifierState) {
        setCapsLock(e.getModifierState('CapsLock'));
      }
    };

    const handleKeyDown = (e: KeyboardEvent) => {
        if (e.key === 'Shift') setIsShiftPressed(true);
    };
    const handleKeyUp = (e: KeyboardEvent) => {
        if (e.key === 'Shift') setIsShiftPressed(false);
    };

    window.addEventListener('keydown', checkCapsLock as any);
    window.addEventListener('keyup', checkCapsLock as any);
    window.addEventListener('click', checkCapsLock as any);
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    return () => {
      window.removeEventListener('keydown', checkCapsLock as any);
      window.removeEventListener('keyup', checkCapsLock as any);
      window.removeEventListener('click', checkCapsLock as any);
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, []);

  // Global keydown listener
  useEffect(() => {
    const handleGlobalKeyDown = (e: KeyboardEvent) => {
      if (status === GameStatus.COMPLETED) {
        if (e.key === 'Enter' || e.key === 'Tab') {
          e.preventDefault();
          handleNext();
        }
        return;
      }

      if (status === GameStatus.FAILED) {
        if (e.key === 'Enter' || e.key === 'Tab') {
          e.preventDefault();
          handleRetry();
        }
        return;
      }

      if (!isFocused) {
        if (e.key === 'Tab') return;

        if (!e.metaKey && !e.altKey && !e.ctrlKey) {
            e.preventDefault(); 
            setIsFocused(true);
            inputRef.current?.focus();
        }
      }
    };
    window.addEventListener('keydown', handleGlobalKeyDown);
    return () => window.removeEventListener('keydown', handleGlobalKeyDown);
  }, [isFocused, status, handleNext, handleRetry]);

  // Smooth Caret Calculation
  useLayoutEffect(() => {
    const updateCaret = () => {
        if (!textContainerRef.current) return;

        let targetEl: HTMLElement | null = null;
        let left = 0;
        let top = 0;
        let height = 0;

        if (input.length < quote.text.length) {
            // Find current char
            targetEl = textContainerRef.current.querySelector(`[data-index="${input.length}"]`);
            if (targetEl) {
                left = targetEl.offsetLeft;
                top = targetEl.offsetTop;
                height = targetEl.offsetHeight;
            }
        } else {
            // End of text, position after last char
            targetEl = textContainerRef.current.querySelector(`[data-index="${input.length - 1}"]`);
            if (targetEl) {
                left = targetEl.offsetLeft + targetEl.offsetWidth;
                top = targetEl.offsetTop;
                height = targetEl.offsetHeight;
            } else if (quote.text.length === 0) {
                 // Empty quote fallback
                 left = 0;
                 top = 0;
                 height = 24; 
            }
        }

        // Handle visual adjustment for empty state or start
        if (input.length === 0 && quote.text.length > 0) {
             const firstEl = textContainerRef.current.querySelector(`[data-index="0"]`) as HTMLElement;
             if (firstEl) {
                 left = firstEl.offsetLeft;
                 top = firstEl.offsetTop;
                 height = firstEl.offsetHeight;
             }
        }

        setCaretPos({ 
            left, 
            top, 
            height: height || 32, // Default height fallback
            opacity: isFocused && status !== GameStatus.COMPLETED && status !== GameStatus.FAILED ? 1 : 0
        });
    };

    updateCaret();
    window.addEventListener('resize', updateCaret);
    return () => window.removeEventListener('resize', updateCaret);
  }, [input, quote, isFocused, status, settings.readAheadLevel]); // Recalculate on any change affecting layout

  const handleFocus = () => {
    if (status === GameStatus.COMPLETED || status === GameStatus.FAILED) return;
    setIsFocused(true);
    inputRef.current?.focus();
  };

  const handleBlur = () => {
    setTimeout(() => {
        if (document.activeElement !== inputRef.current) {
            setIsFocused(false);
        }
    }, 100);
  };

  const calculateStats = useCallback(() => {
    if (!startTime) return { currentWpm: 0 };
    const now = endTime || Date.now();
    const durationInMinutes = (now - startTime) / 60000;
    if (durationInMinutes <= 0) return { currentWpm: 0 };
    const currentWpm = Math.round((input.length / 5) / durationInMinutes);
    return { currentWpm };
  }, [endTime, input.length, startTime]);

  // Game Loop (WPM + Ghost)
  useEffect(() => {
    if (status === GameStatus.PLAYING) {
      const interval = setInterval(() => {
        const { currentWpm } = calculateStats();
        setWpm(currentWpm);

        if (settings.ghostEnabled && ghostWpm > 0 && startTime) {
            const now = Date.now();
            const elapsedMins = (now - startTime) / 60000;
            const projectedChars = (ghostWpm * 5) * elapsedMins;
            setGhostIndex(projectedChars);
        }
      }, 50);
      return () => clearInterval(interval);
    }
  }, [status, calculateStats, settings.ghostEnabled, ghostWpm, startTime]);

  const getWordAt = (index: number, text: string) => {
    const start = text.lastIndexOf(' ', index) + 1;
    let end = text.indexOf(' ', index);
    if (end === -1) end = text.length;
    return text.slice(start, end).replace(/[.,;!?]/g, ''); 
  };

  const handleChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    if (status === GameStatus.COMPLETED) return;

    const val = e.target.value;
    const prevLen = input.length;

    if (status === GameStatus.IDLE && val.length > 0) {
      setStartTime(Date.now());
      setStatus(GameStatus.PLAYING);
    }

    if (val.length > prevLen) {
        soundEngine.playKeypress();
    }

    // --- Instant Fail Check (All Modes) ---
    if (val.length > 0) {
      if (!quote.text.startsWith(val)) {
        soundEngine.playError(); 
        setStatus(GameStatus.FAILED);
        onFail();

        const word = getWordAt(val.length - 1, quote.text);
        onMistake(word);

        // Track locally for history
        setSessionMistakes(prev => prev + 1);
        if (word && !sessionMistakeWords.includes(word)) {
            setSessionMistakeWords(prev => [...prev, word]);
        }
        return;
      }
    }

    setInput(val);

    if (val.length === quote.text.length) {
      const isPerfect = val === quote.text;
      setEndTime(Date.now());

      if (isPerfect) {
        soundEngine.playSuccess(); 
        setStatus(GameStatus.COMPLETED);
        const finalTime = Date.now();
        const durationMins = (finalTime - (startTime || finalTime)) / 60000;
        const finalWpm = Math.round((quote.text.length / 5) / (durationMins || 1));
        setWpm(finalWpm);
      } else {
        soundEngine.playError(); 
        setStatus(GameStatus.FAILED);
        onFail();
      }
    }
  };

  const getReadAheadState = (index: number) => {
    if (settings.readAheadLevel === 'NONE' || status === GameStatus.IDLE) return { isHidden: false, isHighlighted: false };

    const text = quote.text;
    const caret = input.length;

    let currentWordStart = text.lastIndexOf(' ', caret - 1);
    currentWordStart = currentWordStart === -1 ? 0 : currentWordStart + 1;

    let currentWordEnd = text.indexOf(' ', caret);
    if (currentWordEnd === -1) currentWordEnd = text.length;

    // --- LEVEL 1: FOCUS ---
    if (index >= currentWordStart && index < currentWordEnd) {
        return { isHidden: true, isHighlighted: false };
    }

    // --- LEVEL 2: ULTRA ---
    if (settings.readAheadLevel === 'ULTRA' || settings.readAheadLevel === 'BLIND') {
        let nextWordStart = currentWordEnd + 1;
        let nextWordEnd = text.indexOf(' ', nextWordStart);
        if (nextWordEnd === -1) nextWordEnd = text.length;

        if (index >= nextWordStart && index < nextWordEnd) {
            return { isHidden: true, isHighlighted: false }; 
        }
    }

    // --- LEVEL 3: BLIND ---
    if (settings.readAheadLevel === 'BLIND') {
        let nextWordStart = currentWordEnd + 1;
        let nextWordEnd = text.indexOf(' ', nextWordStart);
        if (nextWordEnd === -1) nextWordEnd = text.length;

        let secondNextStart = nextWordEnd + 1;
        let secondNextEnd = text.indexOf(' ', secondNextStart);
        if (secondNextEnd === -1) secondNextEnd = text.length;

        if (index >= secondNextStart && index < secondNextEnd) {
             return { isHidden: true, isHighlighted: false };
        }
    }

    // Highlight next visible word
    if (index > currentWordEnd) { 
        let highlightStart = currentWordEnd + 1;
        if (settings.readAheadLevel === 'ULTRA') {
             let skip1 = text.indexOf(' ', highlightStart);
             if (skip1 !== -1) highlightStart = skip1 + 1;
             else highlightStart = text.length; 
        } else if (settings.readAheadLevel === 'BLIND') {
             let skip1 = text.indexOf(' ', highlightStart);
             let skip2 = skip1 !== -1 ? text.indexOf(' ', skip1 + 1) : -1;
             if (skip2 !== -1) highlightStart = skip2 + 1;
             else highlightStart = text.length;
        }

        let highlightEnd = text.indexOf(' ', highlightStart);
        if (highlightEnd === -1) highlightEnd = text.length;

        if (index >= highlightStart && index < highlightEnd) {
             return { isHidden: false, isHighlighted: true };
        }
    }

    return { isHidden: false, isHighlighted: false };
  };

  const getTextColor = () => {
     if (status === GameStatus.FAILED) {
        if (gameMode === 'HARDCORE') return 'text-red-400/50';
        return 'text-red-300';
     }
     if (gameMode === 'HARDCORE') return 'text-stone-400';
     return 'text-stone-300';
  };

  const renderText = () => {
    return quote.text.split('').map((char, index) => {
      let colorClass = getTextColor(); 
      let bgClass = '';

      const { isHidden, isHighlighted } = getReadAheadState(index);

      if (index < input.length) {
        if (input[index] === char) {
          // Use Dino Green for completed text
          colorClass = 'text-dino-400'; 
        } else {
          colorClass = 'text-red-500 bg-red-100'; 
        }
      } else {
          if (isHighlighted) {
              colorClass = 'text-dino-600 font-bold';
              bgClass = 'bg-dino-100/50';
          }
      }

      if (gameMode === 'FIX_MISTAKE') {
          if (index >= input.length) {
              colorClass = 'text-red-300';
          }
      }

      const isGhostHere = settings.ghostEnabled && Math.floor(ghostIndex) === index;

      return (
        <span key={index} data-index={index} className="relative">
            {isGhostHere && (
                <span className="absolute -left-[2px] top-0 bottom-0 w-[2px] bg-purple-400/50 z-20 animate-pulse">
                     <span className="absolute -top-4 -left-2 text-[10px] text-purple-400 opacity-70">👻</span>
                </span>
            )}

            <span 
                className={`
                    ${colorClass} ${bgClass} transition-colors duration-100
                    ${isHidden ? 'text-transparent selection:text-transparent' : ''}
                    ${isHidden && index < input.length && input[index] !== char ? '!text-red-500 !bg-red-100' : ''} 
                `}
            >
                {char}
            </span>
        </span>
      );
    });
  };

  const getContainerStyle = () => {
    if (status === GameStatus.FAILED) {
        if (gameMode === 'HARDCORE') {
            return 'bg-red-900/20 border-red-900/50 shadow-[0_0_40px_rgba(220,38,38,0.1)]';
        }
        return 'bg-red-50 border-red-200 shadow-inner';
    }

    if (gameMode === 'HARDCORE') {
        return 'bg-neutral-900 border-neutral-800 text-neutral-400 shadow-[0_0_40px_rgba(0,0,0,0.2)]';
    }
    if (gameMode === 'FIX_MISTAKE') {
        return 'bg-red-50 border-red-100';
    }

    // Light gray background for container
    return 'bg-stone-50 border-stone-200 overflow-hidden';
  };

  // Dynamic Text Sizing - Standard/Cozy sizing logic
  const getFontSizeClass = () => {
    const len = quote.text.length;
    // Standard sizes, scaled down if necessary, never massive
    if (len < 100) return 'text-2xl md:text-3xl leading-relaxed';
    if (len < 200) return 'text-xl md:text-2xl leading-relaxed';
    return 'text-lg md:text-xl leading-relaxed';
  };

  const isPerfectMasterPotential = retryCount === 0 && sessionMistakes === 0 && status !== GameStatus.FAILED;

  return (
    <div 
      className="relative w-full max-w-6xl mx-auto min-h-[400px] flex flex-col"
      ref={containerRef}
    >
      {/* Perfect Master Indicator */}
      {isPerfectMasterPotential && status === GameStatus.PLAYING && (
        <div className="absolute -top-8 left-1/2 transform -translate-x-1/2 flex items-center gap-1 text-xs font-bold text-dino-500 animate-pulse">
          <Sparkles className="w-3 h-3" /> Perfect Master Potential (1.5x Bonus)
        </div>
      )}

      <div className={`
        relative flex-grow flex flex-col justify-center p-12 md:p-20 rounded-[3rem] transition-all duration-300 border
        ${getContainerStyle()}
        ${isFocused && status !== GameStatus.FAILED && status !== GameStatus.COMPLETED ? 'ring-2 ring-dino-400/50 ring-offset-2 ring-offset-bg-body' : ''}
        ${status === GameStatus.FAILED ? 'ring-2 ring-red-500 shadow-[0_0_20px_rgba(239,68,68,0.3)]' : ''}
        ${status === GameStatus.COMPLETED ? 'ring-2 ring-dino-100 bg-dino-50/20' : ''}
        ${streak > 2 && status === GameStatus.PLAYING ? 'shadow-[0_0_30px_rgba(251,146,60,0.15)] ring-1 ring-orange-100' : ''}
      `}>

        {!isFocused && status !== GameStatus.COMPLETED && status !== GameStatus.FAILED && (
          <div 
            onClick={handleFocus}
            className="absolute inset-0 z-50 flex items-center justify-center bg-stone-900/5 backdrop-blur-sm cursor-pointer rounded-[3rem] border-2 border-dashed border-dino-200/50 hover:border-dino-300 transition-all"
          >
            <div className="text-center animate-bounce text-dino-500">
              <Play className="w-10 h-10 mx-auto mb-2 opacity-80" fill="currentColor" />
              <span className="font-bold text-base tracking-wide uppercase font-sans">Click or Type to Start</span>
            </div>
          </div>
        )}

        {status === GameStatus.COMPLETED && (
          <div className="absolute inset-0 z-40 flex items-center justify-center">
             <div className="bg-stone-50/90 backdrop-blur-md p-8 rounded-3xl shadow-2xl border border-stone-200 animate-in zoom-in-95 fade-in duration-300 flex flex-col items-center gap-6 min-w-[280px]">
                <div className="text-dino-500 font-black text-xl tracking-tight flex items-center gap-2">
                   <Award className="w-6 h-6" /> Quote Complete!
                </div>

                <div className="grid grid-cols-2 gap-x-12 gap-y-6 w-full">
                   <div className="flex flex-col items-center">
                      <span className="text-[10px] uppercase font-bold text-stone-400 tracking-widest mb-1">Time</span>
                      <span className="font-mono font-bold text-2xl text-stone-700">
                        {endTime && startTime ? ((endTime - startTime) / 1000).toFixed(1) : '0.0'}s
                      </span>
                   </div>
                   <div className="flex flex-col items-center">
                      <span className="text-[10px] uppercase font-bold text-stone-400 tracking-widest mb-1">Speed</span>
                      <span className="font-mono font-bold text-2xl text-stone-700">{wpm} <span className="text-xs text-stone-400 font-sans font-medium">WPM</span></span>
                   </div>
                   <div className="flex flex-col items-center">
                      <span className="text-[10px] uppercase font-bold text-stone-400 tracking-widest mb-1">Retries</span>
                      <span className="font-mono font-bold text-2xl text-stone-700">
                          {retryCount}
                      </span>
                   </div>
                   <div className="flex flex-col items-center">
                      <span className="text-[10px] uppercase font-bold text-stone-400 tracking-widest mb-1">XP Earned</span>
                      <span className="font-mono font-bold text-2xl text-dino-600">
                        +{calculateXP(wpm, quote.text.length, streak, retryCount === 0 && sessionMistakes === 0, settings.readAheadLevel) * (gameMode === 'HARDCORE' ? 5 : 1)}
                      </span>
                   </div>
                </div>

                <div className="text-[10px] font-medium text-stone-400 bg-stone-100/50 px-3 py-1.5 rounded-full">
                   Press <span className="font-bold text-stone-500">Enter</span> or <span className="font-bold text-stone-500">Tab</span> to continue
                </div>
             </div>
          </div>
        )}

        <div className="absolute top-4 left-0 right-0 flex justify-center gap-2 z-30 select-none pointer-events-none">
            {capsLock && (
              <div className="flex items-center gap-2 px-3 py-1.5 bg-orange-100 text-orange-600 rounded-full text-[10px] font-bold tracking-widest border border-orange-200 shadow-sm animate-pulse">
                <Lock className="w-3 h-3" /> CAPS LOCK
              </div>
            )}
            {isShiftPressed && (
               <div className="flex items-center gap-2 px-3 py-1.5 bg-blue-50 text-blue-600 rounded-full text-[10px] font-bold tracking-widest border border-blue-100 shadow-sm">
                <ArrowUp className="w-3 h-3" /> SHIFT
              </div>
            )}
        </div>

        <div className="absolute inset-0 pointer-events-none select-none overflow-hidden rounded-[3rem]">
           {gameMode === 'QUOTES' && (
              <div className="absolute -top-12 -left-12 opacity-[0.02] transform -rotate-12 transition-all duration-700 ease-out scale-100 hover:scale-105">
                 <QuoteIcon className="w-80 h-80 text-stone-900" fill="currentColor" />
              </div>
           )}
           {gameMode === 'HARDCORE' && (
              <div className="absolute -top-12 -left-12 opacity-[0.03] transform -rotate-12 transition-all duration-700 ease-out scale-100 hover:scale-105">
                 <Skull className="w-80 h-80 text-stone-100" />
              </div>
           )}
           {gameMode === 'FIX_MISTAKE' && (
              <div className="absolute -top-12 -left-12 opacity-[0.03] transform -rotate-12 transition-all duration-700 ease-out scale-100 hover:scale-105">
                 <Eraser className="w-80 h-80 text-red-900" />
              </div>
           )}
        </div>

        <div className="absolute top-10 left-0 right-0 px-20 flex justify-between text-xs font-bold opacity-80 uppercase tracking-[0.2em] select-none font-sans z-10 text-stone-500">
          <div className="flex gap-4">
             <span>{quote.source}</span>
             {settings.ghostEnabled && <span className="text-purple-300 flex items-center gap-1"><Ghost className="w-3.5 h-3.5"/> {ghostWpm > 0 ? `${ghostWpm} WPM` : 'Ready'}</span>}
             {settings.readAheadLevel !== 'NONE' && <span className="text-dino-400 flex items-center gap-1"><EyeOff className="w-3.5 h-3.5"/> {settings.readAheadLevel}</span>}
          </div>
          <span>{quote.author}</span>
        </div>

        {/* Text Container with Caret and Dynamic Font */}
        <div 
          ref={textContainerRef}
          className={`font-mono tracking-wide break-words whitespace-pre-wrap mb-12 mt-10 relative z-10 outline-none select-none ${getTextColor()} ${getFontSizeClass()}`}
          onClick={handleFocus}
        >
          {/* Smooth Caret with Dino Green - Animation Disabled */}
          <div 
             className="absolute bg-dino-500 w-[3px] rounded-full transition-all duration-100 ease-out z-20 pointer-events-none caret-blink shadow-[0_0_10px_rgba(132,204,22,0.5)]"
             style={{ 
                 left: caretPos.left - 1, 
                 top: caretPos.top + 2, 
                 height: caretPos.height - 4,
                 opacity: caretPos.opacity
             }}
          />
          {renderText()}
        </div>

        <textarea
          ref={inputRef}
          value={input}
          onChange={handleChange}
          onBlur={handleBlur}
          onFocus={() => {
              setIsFocused(true);
              onInteract?.();
          }}
          className="absolute opacity-0 top-0 left-0 h-full w-full cursor-default resize-none"
          autoFocus={isFocused}
          disabled={status === GameStatus.COMPLETED || status === GameStatus.FAILED}
        />

        <div className="absolute bottom-10 left-0 right-0 px-20 flex justify-between items-end select-none z-10">
           <div className="flex items-center gap-10 text-stone-400 font-mono text-sm">
             <div className="flex flex-col">
                <span className="text-[10px] uppercase font-bold text-stone-300 mb-0.5 tracking-wider">Speed</span>
                <span className="font-bold text-xl opacity-80 font-sans">{wpm} <span className="text-[10px] font-normal opacity-50">WPM</span></span>
             </div>
             {streak > 0 && (
                <div className={`flex flex-col ${streak > 4 ? 'text-orange-500' : 'text-stone-400'}`}>
                    <span className="text-[10px] uppercase font-bold text-stone-300 mb-0.5 tracking-wider">Streak</span>
                    <span className="font-bold text-xl flex items-center gap-1.5 font-sans">
                        <Flame className={`w-4 h-4 ${streak > 4 ? 'fill-orange-500' : ''}`} /> {streak}
                    </span>
                </div>
             )}
           </div>

           <div>
              {status === GameStatus.FAILED && (
                <button 
                  ref={retryButtonRef}
                  onClick={handleRetry}
                  className="flex items-center gap-2 px-6 py-2.5 bg-red-50 text-red-500 rounded-full hover:bg-red-100 transition font-bold text-sm tracking-wide uppercase focus:outline-none focus:ring-2 focus:ring-red-400 focus:ring-offset-2"
                >
                  <RotateCcw className="w-4 h-4" /> Retry
                </button>
              )}
              {status === GameStatus.COMPLETED && (
                <button 
                  ref={nextButtonRef}
                  onClick={handleNext}
                  className={`flex items-center gap-2 px-6 py-2.5 rounded-full transition shadow-lg font-bold text-sm tracking-wide uppercase transform hover:-translate-y-0.5 focus:outline-none focus:ring-2 focus:ring-offset-2
                    bg-dino-500 text-white hover:bg-dino-600 shadow-dino-200/50 focus:ring-dino-400
                  `}
                >
                   Next Quote <Award className="w-4 h-4" />
                </button>
              )}
           </div>
        </div>
      </div>

      <div className="text-center mt-8 h-4 text-stone-400 text-xs font-medium tracking-wide transition-opacity duration-500 font-sans">
        {status === GameStatus.FAILED ? 
            <span className="text-red-400">
                {gameMode === 'HARDCORE' 
                  ? 'HARDCORE FAIL. 50% XP Penalty.' 
                  : 'Mistake made. Restart required.'}
            </span> : 
         status === GameStatus.COMPLETED ? <span className="text-dino-500">Perfect! Streak +1 {retryCount === 0 && sessionMistakes === 0 && "(Mastery Bonus!)"}</span> :
         isFocused ? "Accuracy is paramount. One mistake restarts the quote." : ""}
      </div>
    </div>
  );
};

export default TypingArea;

import React, { useState, useEffect, useRef } from 'react';
import { MusicConfig, MusicSource, Settings } from '../types';
import { getCurrentLevel } from '../utils/gameLogic';
import { RADIO_STATIONS } from '../data/radioStations';
import { X, Music, Disc, Youtube, Radio, Sparkles, Wind, Waves, Guitar, Drum, Rocket, Volume2, Power, AudioWaveform, Lock } from 'lucide-react';

interface MusicPlayerProps {
  isOpen: boolean;
  onClose: () => void;
  settings: Settings;
  setSettings: (s: Settings) => void;
  userXP: number;
}

const TIER_ORDER = ['Egg', 'Tadpole', 'Polliwog', 'Froglet', 'Hopper', 'Tree Frog', 'Bullfrog', 'Frog Sage'];

const BACKGROUND_PRESETS = [
    { id: 'PIANO_BEETHOVEN', name: 'Moonlight Piano', icon: <Music className="w-4 h-4 text-purple-500" /> },
    { id: 'PIANO_SATIE', name: 'Satie (Gymnopédie)', icon: <Music className="w-4 h-4 text-purple-400" /> },
    { id: 'PIANO_JAZZ', name: 'Jazz Lounge', icon: <Music className="w-4 h-4 text-orange-400" /> },
    { id: 'GUITAR', name: 'Acoustic Guitar', icon: <Guitar className="w-4 h-4 text-amber-500" /> },
    { id: 'ZEN', name: 'Zen Bells', icon: <Wind className="w-4 h-4 text-teal-500" /> },
    { id: 'BROWN_NOISE', name: 'Brown Noise', icon: <Waves className="w-4 h-4 text-stone-500" /> },
    { id: 'DRUMS_HARDCORE', name: 'Hardcore Breakbeat', icon: <Drum className="w-4 h-4 text-red-600" /> },
    { id: 'SYNTH_COSMIC', name: 'Cosmic Synth', icon: <Rocket className="w-4 h-4 text-indigo-500" /> }
];

export const MusicPlayer: React.FC<MusicPlayerProps> = ({ isOpen, onClose, settings, setSettings, userXP }) => {
  const [activeTab, setActiveTab] = useState<'BACKGROUND' | 'RADIO'>('BACKGROUND');
  const { musicConfig } = settings;
  const containerRef = useRef<HTMLDivElement>(null);

  const currentLevel = getCurrentLevel(userXP);
  const currentTierIndex = TIER_ORDER.indexOf(currentLevel.tier);

  // Close when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (isOpen && containerRef.current && !containerRef.current.contains(event.target as Node)) {
        onClose();
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [isOpen, onClose]);

  const handlePlay = (source: MusicSource, id: string) => {
    setSettings({
      ...settings,
      musicConfig: { source, presetId: id }
    });
  };

  const handleStop = () => {
    setSettings({
      ...settings,
      musicConfig: { source: 'NONE', presetId: '' }
    });
  };

  const handleAmbientVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSettings({ ...settings, ambientVolume: parseFloat(e.target.value) });
  };

  const isStationLocked = (tier: string) => {
    const requiredIndex = TIER_ORDER.indexOf(tier);
    return currentTierIndex < requiredIndex;
  };

  // The actual player render (Persists even when UI is closed)
  const renderEmbed = () => {
    if (musicConfig.source === 'NONE') return null;

    if (musicConfig.source === 'YOUTUBE') {
      return (
        <div className="w-full aspect-video bg-black rounded-lg overflow-hidden relative group shadow-inner">
           <iframe 
             width="100%" 
             height="100%" 
             src={`https://utube.realityripple.com/#${musicConfig.presetId}`} 
             title="YouTube music player" 
             frameBorder="0" 
             allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" 
             allowFullScreen
             className="opacity-90 hover:opacity-100 transition-opacity"
           ></iframe>
        </div>
      );
    }

    if (musicConfig.source === 'SPOTIFY') {
      return (
        <iframe 
          style={{ borderRadius: '12px' }} 
          src={`https://open.spotify.com/embed/playlist/${musicConfig.presetId}`} 
          width="100%" 
          height="152" 
          frameBorder="0" 
          allowFullScreen 
          allow="autoplay; clipboard-write; encrypted-media; fullscreen; picture-in-picture" 
          loading="lazy"
          className="shadow-sm"
        ></iframe>
      );
    }

    if (musicConfig.source === 'SUNO') {
      return (
        <div className="rounded-xl overflow-hidden shadow-sm border border-stone-200">
           <iframe 
             src={`https://suno.com/embed/playlist/${musicConfig.presetId}`}
             width="100%" 
             height="380" 
             frameBorder="0" 
             allow="clipboard-write; autoplay"
           ></iframe>
        </div>
      );
    }

    if (musicConfig.source === 'GENERATED') {
       // Visualizer for Generated Audio
       const info = BACKGROUND_PRESETS.find(p => p.id === musicConfig.presetId);
       return (
         <div className="w-full h-32 bg-stone-900 rounded-xl flex flex-col items-center justify-center relative overflow-hidden shadow-inner ring-1 ring-stone-800">
            {/* Simple CSS animation for visualizer */}
            <div className="absolute inset-0 opacity-20 flex items-end justify-center gap-1 pb-2">
                {[...Array(20)].map((_, i) => (
                    <div 
                      key={i} 
                      className="w-1.5 bg-dino-400 rounded-t-sm animate-pulse" 
                      style={{ 
                          height: `${20 + Math.random() * 60}%`,
                          animationDuration: `${0.3 + Math.random() * 0.7}s`
                      }} 
                    />
                ))}
            </div>
            <div className="z-10 text-white font-bold flex flex-col items-center gap-2">
                <div className="p-2 bg-stone-800 rounded-full shadow-xl border border-stone-700">
                    {info?.icon || <Sparkles className="w-5 h-5 text-yellow-400" />}
                </div>
                <span className="text-xs tracking-wide font-mono">{info?.name}</span>
            </div>
            <div className="absolute top-2 right-2 text-[8px] text-dino-500 font-black uppercase tracking-widest bg-dino-900/20 px-1.5 py-0.5 rounded border border-dino-900/50">
               Live Engine
            </div>
         </div>
       );
    }
  };

  // If closed and not playing, don't render anything
  if (!isOpen && musicConfig.source === 'NONE') return null;

  return (
    <div className={`fixed bottom-6 right-6 z-50 transition-all duration-300 ${isOpen ? 'translate-y-0 opacity-100' : 'translate-y-10 opacity-0 pointer-events-none'}`}>
      <div ref={containerRef} className="bg-white rounded-2xl shadow-2xl shadow-stone-300/50 w-96 max-w-[calc(100vw-3rem)] border border-stone-100 overflow-hidden flex flex-col">

        {/* Header */}
        <div className="flex items-center justify-between p-4 bg-white border-b border-stone-100">
           <div className="flex items-center gap-2 text-stone-700 font-bold">
             <Radio className="w-4 h-4 text-dino-500" />
             <span className="text-sm">Background Audio</span>
           </div>
           <button onClick={onClose} className="text-stone-400 hover:text-stone-600">
             <X className="w-4 h-4" />
           </button>
        </div>

        {/* Content */}
        <div className="p-4 bg-stone-50/50">

          {/* Active Player Area */}
          <div className={`transition-all duration-300 ${musicConfig.source === 'NONE' ? 'h-0 overflow-hidden opacity-0' : 'h-auto min-h-[100px] mb-4 opacity-100'}`}>
             {renderEmbed()}

             <button 
               onClick={handleStop} 
               className="mt-3 w-full flex items-center justify-center gap-2 py-2 text-xs text-red-500 font-bold bg-red-50 hover:bg-red-100 rounded-lg transition-colors"
             >
               <Power className="w-3.5 h-3.5" /> Disable Music
             </button>
          </div>

          {/* Source Tabs */}
          <div className="flex p-1 bg-stone-200/50 rounded-lg mb-4 gap-0.5">
            <button 
              onClick={() => setActiveTab('BACKGROUND')}
              className={`flex-1 flex items-center justify-center gap-1 py-2 text-[10px] font-bold rounded-md transition-all ${activeTab === 'BACKGROUND' ? 'bg-white text-dino-600 shadow-sm' : 'text-stone-500 hover:text-stone-700'}`}
              title="Generated Sounds"
            >
              <Sparkles className="w-3 h-3" /> Background
            </button>
            <button 
              onClick={() => setActiveTab('RADIO')}
              className={`flex-1 flex items-center justify-center gap-1 py-2 text-[10px] font-bold rounded-md transition-all 
                ${activeTab === 'RADIO' ? 'bg-white text-dino-600 shadow-sm' : 'text-stone-500 hover:text-stone-700'}
              `}
              title="Streaming Radio"
            >
              <Radio className="w-3 h-3" /> Radio
            </button>
          </div>

          {/* Volume Control - Visible when in Background tab */}
          {activeTab === 'BACKGROUND' && (
            <div className="mb-4 px-3 py-3 bg-white rounded-xl border border-stone-100 shadow-sm animate-in slide-in-from-top-2 fade-in duration-300">
               <div className="flex justify-between text-[10px] text-stone-400 font-bold mb-2 uppercase tracking-wide">
                  <span className="flex items-center gap-1.5 text-stone-500"><Volume2 className="w-3.5 h-3.5"/> Music Volume</span>
                  <span>{Math.round(settings.ambientVolume * 100)}%</span>
               </div>
               <input 
                 type="range" 
                 min="0" 
                 max="1" 
                 step="0.01" 
                 value={settings.ambientVolume}
                 onChange={handleAmbientVolumeChange}
                 className="w-full h-1.5 bg-stone-100 rounded-lg appearance-none cursor-pointer accent-dino-500 hover:accent-dino-600"
               />
            </div>
          )}

          {/* Preset List */}
          <div className="space-y-1.5 max-h-48 overflow-y-auto pr-1 custom-scrollbar">
             {activeTab === 'BACKGROUND' && BACKGROUND_PRESETS.map((preset) => (
               <button
                 key={preset.id}
                 onClick={() => handlePlay('GENERATED', preset.id)}
                 className={`w-full text-left px-3 py-2 rounded-lg text-xs font-bold transition-all flex items-center justify-between group
                   ${musicConfig.source === 'GENERATED' && musicConfig.presetId === preset.id 
                     ? 'bg-dino-100 text-dino-700 border border-dino-200' 
                     : 'bg-white hover:bg-stone-50 text-stone-600 border border-transparent hover:border-stone-200'
                   }`}
               >
                 <div className="flex items-center gap-2">
                    {preset.icon && <span className="opacity-70">{preset.icon}</span>}
                    <span className="truncate">{preset.name}</span>
                 </div>
                 {musicConfig.source === 'GENERATED' && musicConfig.presetId === preset.id && (
                   <div className="flex space-x-[2px] items-end h-3">
                     <div className="w-[2px] bg-dino-500 h-1 animate-[bounce_1s_infinite]" />
                     <div className="w-[2px] bg-dino-500 h-2 animate-[bounce_1.2s_infinite]" />
                     <div className="w-[2px] bg-dino-500 h-3 animate-[bounce_0.8s_infinite]" />
                   </div>
                 )}
               </button>
             ))}

             {activeTab === 'RADIO' && RADIO_STATIONS.map((preset) => {
               const locked = isStationLocked(preset.tier);

               return (
                 <button
                   key={preset.id}
                   onClick={() => !locked && handlePlay(preset.type, preset.id)}
                   disabled={locked}
                   className={`w-full text-left px-3 py-2 rounded-lg text-xs font-bold transition-all flex items-center justify-between group
                     ${locked
                       ? 'bg-stone-50 text-stone-400 opacity-60 cursor-not-allowed border border-transparent'
                       : musicConfig.source === preset.type && musicConfig.presetId === preset.id 
                         ? 'bg-dino-100 text-dino-700 border border-dino-200' 
                         : 'bg-white hover:bg-stone-50 text-stone-600 border border-transparent hover:border-stone-200'
                     }`}
                 >
                   <div className="flex items-center gap-2">
                      {locked ? <Lock className="w-3.5 h-3.5 opacity-50" /> : (
                         preset.type === 'YOUTUBE' ? <Youtube className="w-3.5 h-3.5 text-red-500 opacity-80" /> : 
                         preset.type === 'SUNO' ? <AudioWaveform className="w-3.5 h-3.5 text-stone-800 opacity-80" /> :
                         <Disc className="w-3.5 h-3.5 text-dino-500 opacity-80" />
                      )}
                      <div className="flex flex-col">
                        <span className="truncate">{preset.name}</span>
                        {locked && <span className="text-[9px] text-stone-400 font-normal uppercase tracking-wide">Unlocks at {preset.tier}</span>}
                      </div>
                   </div>
                   {!locked && musicConfig.source === preset.type && musicConfig.presetId === preset.id && (
                     <div className="flex space-x-[2px] items-end h-3">
                       <div className="w-[2px] bg-dino-500 h-1 animate-[bounce_1s_infinite]" />
                       <div className="w-[2px] bg-dino-500 h-2 animate-[bounce_1.2s_infinite]" />
                       <div className="w-[2px] bg-dino-500 h-3 animate-[bounce_0.8s_infinite]" />
                     </div>
                   )}
                 </button>
               );
             })}
          </div>

        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useCallback, useLayoutEffect, useRef } from 'react';
import ProgressBar from './components/ProgressBar';
import TypingArea from './components/TypingArea';
import SettingsModal from './components/SettingsModal';
import HelpModal from './components/HelpModal';
import StatsModal from './components/StatsModal';
import ThemeModal from './components/ThemeModal';
import AchievementsModal from './components/AchievementsModal';
import AchievementToast from './components/AchievementToast';
import { MusicPlayer } from './components/MusicPlayer';
import { Quote, Settings, GameMode, TestResult, NotificationItem, ReadAheadLevel } from './types';
import { fetchQuotes } from './services/quoteService';
import { getCurrentLevel, getNextLevel, getAverageWPM, LEVELS, calculateXP } from './utils/gameLogic';
import { soundEngine } from './utils/soundEngine';
import { Loader2, Settings as SettingsIcon, Music, CircleHelp, Skull, BookOpen, Eraser, TrendingUp, Palette, Award, Radio, Lock, Eye, EyeOff, Flame } from 'lucide-react';
import confetti from 'canvas-confetti';
import { THEMES } from './data/themes';
import { ACHIEVEMENTS } from './data/achievements';
import { RADIO_STATIONS } from './data/radioStations';

const App: React.FC = () => {
  // User Stats Persistence
  const [userName, setUserName] = useState<string>(() => {
      return localStorage.getItem('frogType_userName') || 'Froggy';
  });

  const [joinDate, setJoinDate] = useState<string>(() => {
      const stored = localStorage.getItem('frogType_joinDate');
      if (stored) return stored;
      const now = new Date().toISOString();
      localStorage.setItem('frogType_joinDate', now);
      return now;
  });

  const [totalTimePlayed, setTotalTimePlayed] = useState<number>(() => {
      const stored = localStorage.getItem('frogType_totalTime');
      return stored ? parseInt(stored, 10) : 0;
  });

  const [userXP, setUserXP] = useState<number>(() => {
    const saved = localStorage.getItem('frogXP');
    const legacy = localStorage.getItem('frogType_xp');
    if (saved) return parseInt(saved, 10);
    if (legacy) return parseInt(legacy, 10);
    return 0;
  });

  const currentLevel = getCurrentLevel(userXP);

  // Track unlocked tiers persistently to prevent repeat notifications
  const [unlockedTiers, setUnlockedTiers] = useState<string[]>(() => {
    const saved = localStorage.getItem('frogType_unlockedTiers');
    return saved ? JSON.parse(saved) : [];
  });

  // Session Streak (Consecutive Quotes)
  const [streak, setStreak] = useState<number>(() => {
    const saved = localStorage.getItem('frogType_streak');
    return saved ? parseInt(saved, 10) : 0;
  });

  // Daily Streak Logic
  const [dailyStreak, setDailyStreak] = useState<number>(() => {
     const saved = localStorage.getItem('frogType_dailyStreak');
     return saved ? parseInt(saved, 10) : 0;
  });

  const [unlockedAchievements, setUnlockedAchievements] = useState<string[]>(() => {
    const saved = localStorage.getItem('frogType_achievements');
    return saved ? JSON.parse(saved) : [];
  });

  const [notificationQueue, setNotificationQueue] = useState<NotificationItem[]>([]);

  // Track history for average WPM calculation (Last 10)
  const [wpmHistory, setWpmHistory] = useState<number[]>(() => {
    const saved = localStorage.getItem('frogType_wpmHistory');
    return saved ? JSON.parse(saved) : [];
  });

  // Track full history of tests
  const [testHistory, setTestHistory] = useState<TestResult[]>(() => {
    const saved = localStorage.getItem('frogType_history');
    return saved ? JSON.parse(saved) : [];
  });

  const [lastWpm, setLastWpm] = useState<number>(() => {
    const saved = localStorage.getItem('frogType_lastWpm');
    return saved ? parseInt(saved, 10) : 0;
  });

  const [mistakePool, setMistakePool] = useState<string[]>(() => {
    const saved = localStorage.getItem('frogType_mistakes');
    return saved ? JSON.parse(saved) : [];
  });

  const [settings, setSettings] = useState<Settings>(() => {
    const saved = localStorage.getItem('frogType_settings');

    if (!saved) {
      return { 
        ghostEnabled: false, 
        readAheadLevel: 'NONE', 
        sfxEnabled: true,
        mechanicalSoundEnabled: false,
        mechanicalSoundPreset: 'THOCK',
        ambientVolume: 0.02, 
        musicConfig: { source: 'GENERATED', presetId: 'PIANO_SATIE' },
        themeId: 'CLASSIC'
      };
    }

    const parsed = JSON.parse(saved);
    const legacyBrownNoiseEnabled = parsed.brownNoiseEnabled === true;
    const legacyVolume = parsed.brownNoiseVolume ?? 0.5;

    // Migration for legacy boolean readAhead
    let initialReadAhead = parsed.readAheadLevel;
    if (parsed.readAheadEnabled === true && !initialReadAhead) initialReadAhead = 'FOCUS';
    if (!initialReadAhead) initialReadAhead = 'NONE';

    let initialMusicConfig = parsed.musicConfig || { source: 'NONE', presetId: '' };
    if (legacyBrownNoiseEnabled && initialMusicConfig.source === 'NONE') {
        initialMusicConfig = { source: 'GENERATED', presetId: 'BROWN_NOISE' };
    }

    return { 
      ghostEnabled: false, 
      readAheadLevel: initialReadAhead, 
      sfxEnabled: true,
      mechanicalSoundEnabled: parsed.mechanicalSoundEnabled ?? false,
      mechanicalSoundPreset: parsed.mechanicalSoundPreset || 'THOCK',
      ambientVolume: parsed.ambientVolume ?? legacyVolume, 
      musicConfig: initialMusicConfig,
      themeId: parsed.themeId || 'CLASSIC',
      ...parsed
    };
  });

  const [gameMode, setGameMode] = useState<GameMode>(() => {
    const saved = localStorage.getItem('frogType_gameMode');
    return (saved as GameMode) || 'QUOTES';
  });

  const [completedQuotes, setCompletedQuotes] = useState<string[]>(() => {
    const saved = localStorage.getItem('frogType_completedQuotes');
    return saved ? JSON.parse(saved) : [];
  });

  const [quotesQueue, setQuotesQueue] = useState<Quote[]>([]);

  const [currentQuote, setCurrentQuote] = useState<Quote | null>(() => {
    const saved = localStorage.getItem('frogType_currentQuote');
    return saved ? JSON.parse(saved) : null;
  });

  const [loading, setLoading] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isMusicOpen, setIsMusicOpen] = useState(false);
  const [isHelpOpen, setIsHelpOpen] = useState(false);
  const [isStatsOpen, setIsStatsOpen] = useState(false);
  const [isThemeOpen, setIsThemeOpen] = useState(false);
  const [isAchievementsOpen, setIsAchievementsOpen] = useState(false);

  // Start time tracking for current quote
  const [quoteStartTime, setQuoteStartTime] = useState<number | null>(null);

  const isFetchingRef = useRef(false);

  // Derive Lock State
  const uniqueTiers = Array.from(new Set(LEVELS.map(l => l.tier)));
  const currentTierIndex = uniqueTiers.indexOf(currentLevel.tier);
  const polliwogIndex = uniqueTiers.indexOf('Polliwog');
  const isHardcoreLocked = currentTierIndex < polliwogIndex;

  // Persistence
  useEffect(() => { localStorage.setItem('frogXP', userXP.toString()); }, [userXP]);
  useEffect(() => { localStorage.setItem('frogType_unlockedTiers', JSON.stringify(unlockedTiers)); }, [unlockedTiers]);
  useEffect(() => { localStorage.setItem('frogType_streak', streak.toString()); }, [streak]);
  useEffect(() => { localStorage.setItem('frogType_dailyStreak', dailyStreak.toString()); }, [dailyStreak]);
  useEffect(() => { localStorage.setItem('frogType_lastWpm', lastWpm.toString()); }, [lastWpm]);
  useEffect(() => { localStorage.setItem('frogType_wpmHistory', JSON.stringify(wpmHistory)); }, [wpmHistory]);
  useEffect(() => { localStorage.setItem('frogType_history', JSON.stringify(testHistory)); }, [testHistory]);
  useEffect(() => { localStorage.setItem('frogType_settings', JSON.stringify(settings)); }, [settings]);
  useEffect(() => { localStorage.setItem('frogType_mistakes', JSON.stringify(mistakePool)); }, [mistakePool]);
  useEffect(() => { localStorage.setItem('frogType_userName', userName); }, [userName]);
  useEffect(() => { localStorage.setItem('frogType_totalTime', totalTimePlayed.toString()); }, [totalTimePlayed]);

  // Game Mode Persistence & Lock Check
  useEffect(() => { 
      if (gameMode === 'HARDCORE' && isHardcoreLocked) {
          setGameMode('QUOTES');
      }
      localStorage.setItem('frogType_gameMode', gameMode); 
  }, [gameMode, isHardcoreLocked]);

  useEffect(() => { localStorage.setItem('frogType_completedQuotes', JSON.stringify(completedQuotes)); }, [completedQuotes]);
  useEffect(() => { localStorage.setItem('frogType_achievements', JSON.stringify(unlockedAchievements)); }, [unlockedAchievements]);

  // Audio Settings Sync
  useEffect(() => {
    soundEngine.setEnabled(settings.sfxEnabled);
    soundEngine.setMechanicalEnabled(settings.mechanicalSoundEnabled);
    soundEngine.setMechanicalPreset(settings.mechanicalSoundPreset);
    soundEngine.setAmbientVolume(settings.ambientVolume);

    if (settings.musicConfig.source === 'GENERATED') {
      soundEngine.setAmbientMusic(settings.musicConfig.presetId);
    } else {
      soundEngine.stopAmbientMusic();
    }
  }, [settings.sfxEnabled, settings.mechanicalSoundEnabled, settings.mechanicalSoundPreset, settings.ambientVolume, settings.musicConfig]);

  useLayoutEffect(() => {
    const theme = THEMES.find(t => t.id === settings.themeId) || THEMES[0];
    const root = document.documentElement;
    root.style.setProperty('--bg-body', theme.colors.background);
    Object.entries(theme.colors.frog).forEach(([key, value]) => {
       root.style.setProperty(`--frog-${key}`, value);
    });
    Object.entries(theme.colors.stone).forEach(([key, value]) => {
       root.style.setProperty(`--stone-${key}`, value);
    });
    root.style.setProperty('--text-body', theme.colors.stone[800]);
  }, [settings.themeId]);

  useEffect(() => {
    const handleInteraction = () => {
      soundEngine.resumeContext();
      window.removeEventListener('click', handleInteraction);
      window.removeEventListener('keydown', handleInteraction);
    };

    window.addEventListener('click', handleInteraction);
    window.addEventListener('keydown', handleInteraction);
    return () => {
      window.removeEventListener('click', handleInteraction);
      window.removeEventListener('keydown', handleInteraction);
    };
  }, []);

  useEffect(() => { 
    if (currentQuote) {
      localStorage.setItem('frogType_currentQuote', JSON.stringify(currentQuote)); 
      setQuoteStartTime(Date.now());
    } else {
      localStorage.removeItem('frogType_currentQuote');
    }
  }, [currentQuote]);

  // Check Daily Streak on Mount
  useEffect(() => {
      const today = new Date().toDateString();
      const lastVisit = localStorage.getItem('frogType_lastVisitDate');

      // If user hasn't visited today, check if streak should break
      if (lastVisit && lastVisit !== today) {
          const yesterday = new Date();
          yesterday.setDate(yesterday.getDate() - 1);

          if (yesterday.toDateString() !== lastVisit) {
              // Streak broken if last visit was not yesterday
              setDailyStreak(0);
          }
      } else if (!lastVisit) {
          setDailyStreak(0);
      }
  }, []);

  const updateDailyStreakActivity = () => {
      const today = new Date().toDateString();
      const lastVisit = localStorage.getItem('frogType_lastVisitDate');

      if (lastVisit !== today) {
          // New day activity
          let newStreak = 1;
          if (lastVisit) {
              const yesterday = new Date();
              yesterday.setDate(yesterday.getDate() - 1);
              if (yesterday.toDateString() === lastVisit) {
                  newStreak = dailyStreak + 1;
              }
          }
          setDailyStreak(newStreak);
          localStorage.setItem('frogType_lastVisitDate', today);

          // Toast for streak
          setNotificationQueue(prev => [...prev, {
              id: `daily_${Date.now()}`,
              title: "Daily Streak!",
              description: `You're on a ${newStreak} day streak.`,
              icon: <Flame className="w-5 h-5 text-orange-500" />,
              type: "INFO"
          }]);
      } else {
          // Already played today, ensure streak is at least 1 if it was 0
          if (dailyStreak === 0) {
              setDailyStreak(1);
              localStorage.setItem('frogType_lastVisitDate', today);
          }
      }
  };

  const generateMistakeQuote = useCallback((): Quote | null => {
    if (mistakePool.length === 0) return null;
    let pool = [...mistakePool];
    while (pool.length < 15) {
       pool = [...pool, ...mistakePool];
    }
    const shuffled = pool.sort(() => 0.5 - Math.random());
    const selected = shuffled.slice(0, 15);
    const text = selected.join(' ');

    return {
      text,
      source: "Personal Training",
      author: "Your Mistakes"
    };
  }, [mistakePool]);

  const loadMoreQuotes = useCallback(async () => {
    if (isFetchingRef.current) return;

    isFetchingRef.current = true;

    try {
      const level = getCurrentLevel(userXP);
      // IMPORTANT: Pass completedQuotes to filter them out forever
      const newQuotes = await fetchQuotes(5, completedQuotes, level.tier, gameMode);
      setQuotesQueue(prev => [...prev, ...newQuotes]);
    } catch (error) {
      console.error("Failed to load quotes", error);
    } finally {
      isFetchingRef.current = false;
    }
  }, [completedQuotes, userXP, gameMode]);

  useEffect(() => {
    const init = async () => {
      if (!currentQuote && quotesQueue.length === 0) {
         setLoading(true);
         await loadMoreQuotes();
         setLoading(false);
      } else if (quotesQueue.length < 3) {
         loadMoreQuotes();
      }
    };
    init();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (currentQuote) return;

    if (gameMode === 'FIX_MISTAKE') {
      const mistakeQuote = generateMistakeQuote();
      if (mistakeQuote) {
        setCurrentQuote(mistakeQuote);
      } else {
        setGameMode('QUOTES'); 
      }
    } else {
      if (quotesQueue.length > 0) {
        const next = quotesQueue[0];
        setCurrentQuote(next);
        setQuotesQueue(prev => prev.slice(1));
      }

      if (quotesQueue.length < 3) {
        loadMoreQuotes();
      }
    }
  }, [currentQuote, quotesQueue, gameMode, generateMistakeQuote, loadMoreQuotes]);

  const checkAchievements = (wpm: number) => {
    const newNotifications: NotificationItem[] = [];
    const newUnlockIds: string[] = [];

    const stats = {
       wpm,
       totalQuotes: completedQuotes.length + 1, 
       maxStreak: Math.max(streak + 1, streak + 1),
       currentStreak: streak + 1,
       mode: gameMode
    };

    ACHIEVEMENTS.forEach(ach => {
       if (!unlockedAchievements.includes(ach.id)) {
           if (ach.condition(stats)) {
               newUnlockIds.push(ach.id);
               newNotifications.push({
                   id: ach.id,
                   title: ach.title,
                   description: ach.description,
                   icon: ach.icon,
                   type: 'ACHIEVEMENT'
               });
           }
       }
    });

    if (newUnlockIds.length > 0) {
       setUnlockedAchievements(prev => [...prev, ...newUnlockIds]);
       setNotificationQueue(prev => [...prev, ...newNotifications]);
       soundEngine.playLevelUp(); 
    }
  };

  const handleQuoteComplete = (xpCalc: number, wpm: number, mistakes: string[], retryCount: number) => {
    // Recalculate with Read Ahead Bonus (if any changed since TypingArea)
    // Actually simpler to pass raw WPM/Length and recalc here or trust TypingArea passed value.
    // TypingArea uses calculateXP so it already includes ReadAhead bonus from settings passed to it.
    let finalXp = xpCalc; 

    // Update Time Played
    if (quoteStartTime) {
        const durationSec = Math.floor((Date.now() - quoteStartTime) / 1000);
        setTotalTimePlayed(prev => prev + durationSec);
    }

    if (gameMode === 'HARDCORE') {
      finalXp = finalXp * 5;
    }

    // Fix Mistake Mode Logic
    if (gameMode === 'FIX_MISTAKE' && currentQuote) {
      const wordsFixed = [...new Set(currentQuote.text.split(' '))]; 
      setMistakePool(prev => prev.filter(word => !wordsFixed.includes(word)));
    }

    // Mark quote as completed so it never shows again (if in standard modes)
    if (currentQuote && gameMode !== 'FIX_MISTAKE') {
       setCompletedQuotes(prev => [...prev, currentQuote.text]);
    }

    // Update History
    const newHistory = [...wpmHistory, wpm].slice(-10); 
    setWpmHistory(newHistory);
    const avgWpm = getAverageWPM(newHistory);

    const newTestResult: TestResult = {
      id: Date.now(),
      date: new Date().toISOString(),
      wpm,
      xpEarned: finalXp,
      mode: gameMode,
      quoteText: currentQuote?.text || "",
      mistakes: mistakes,
      retryCount: retryCount
    };
    setTestHistory(prev => [...prev, newTestResult]);

    checkAchievements(wpm);

    // Calculate XP and Handle Gates/Unlocks
    const currentLevelObj = getCurrentLevel(userXP);
    const nextLevelObj = getNextLevel(currentLevelObj);
    let potentialXp = userXP + finalXp;

    if (nextLevelObj && potentialXp >= nextLevelObj.minXP) {
         let effectiveMistakeCount = mistakePool.length;
         if (gameMode === 'FIX_MISTAKE' && currentQuote) {
             const wordsFixed = [...new Set(currentQuote.text.split(' '))];
             effectiveMistakeCount = mistakePool.filter(word => !wordsFixed.includes(word)).length;
         }

         const isMasteryGated = effectiveMistakeCount > 0;
         const isSpeedGated = avgWpm < nextLevelObj.requiredWpm;

         if (isMasteryGated || isSpeedGated) {
            potentialXp = nextLevelObj.minXP - 1; 
         }
    }

    const newLevel = getCurrentLevel(potentialXp);

    // Check for Tier Unlocks (Persistent - Only once per tier)
    if (!unlockedTiers.includes(newLevel.tier)) {
         setUnlockedTiers(prev => [...prev, newLevel.tier]);

         const newStations = RADIO_STATIONS.filter(s => s.tier === newLevel.tier);

         if (newStations.length > 0) {
             const musicNotifications: NotificationItem[] = newStations.map(s => ({
                id: `unlock_${s.id}`,
                title: 'New Station Unlocked',
                description: s.name,
                icon: <Radio className="w-5 h-5 text-stone-900" />,
                type: 'UNLOCK'
             }));
             setNotificationQueue(prev => [...prev, ...musicNotifications]);
         }
    }

    const prevLevel = getCurrentLevel(userXP);
    if (newLevel.tier !== prevLevel.tier && potentialXp >= newLevel.minXP) {
          setTimeout(() => {
              confetti({
                particleCount: 200,
                spread: 120,
                origin: { y: 0.6 },
                colors: ['#d1fae5', '#10b981', '#fbbf24', '#f59e0b'],
                startVelocity: 45
              });
              soundEngine.playLevelUp(); 
          }, 300);
    }

    setUserXP(potentialXp);
    setStreak(prev => prev + 1);

    // Update Daily Streak
    updateDailyStreakActivity();

    setLastWpm(wpm);
    setCurrentQuote(null); 
    setQuoteStartTime(null);
  };

  const handleQuoteFail = () => {
    setStreak(0);
  };

  const handleMistake = (word?: string) => {
    const penaltyMultiplier = gameMode === 'HARDCORE' ? 0.5 : 0.85;
    setUserXP(prev => Math.floor(prev * penaltyMultiplier));

    setStreak(0);

    if (word && word.length > 1) {
       setMistakePool(prev => {
         if (prev.includes(word)) return prev;
         return [...prev, word];
       });
    }
  };

  const handlePracticeFromHistory = (mistakes: string[]) => {
      setMistakePool(prev => {
          const newSet = new Set([...prev, ...mistakes]);
          return Array.from(newSet);
      });
      switchMode('FIX_MISTAKE');
  };

  const toggleSettings = () => setIsSettingsOpen(!isSettingsOpen);
  const toggleMusic = () => setIsMusicOpen(!isMusicOpen);
  const toggleHelp = () => setIsHelpOpen(!isHelpOpen);
  const toggleStats = () => setIsStatsOpen(!isStatsOpen);
  const toggleTheme = () => setIsThemeOpen(!isThemeOpen);
  const toggleAchievements = () => setIsAchievementsOpen(!isAchievementsOpen);

  const cycleReadAhead = () => {
      const levels: ReadAheadLevel[] = ['NONE', 'FOCUS', 'ULTRA', 'BLIND'];
      const currentIndex = levels.indexOf(settings.readAheadLevel);
      const nextIndex = (currentIndex + 1) % levels.length;
      setSettings({ ...settings, readAheadLevel: levels[nextIndex] });
      soundEngine.playKeypress(); // Feedback
  };

  const switchMode = (mode: GameMode) => {
    if (mode === 'FIX_MISTAKE' && mistakePool.length === 0) return;
    if (mode === 'HARDCORE' && isHardcoreLocked) return;
    setGameMode(mode);
    setQuotesQueue([]); 
    setCurrentQuote(null); 
  };

  const handleRequestNextQuote = async () => {
      setCurrentQuote(null);
      setQuoteStartTime(null);
  };

  const clearToast = useCallback(() => {
    setNotificationQueue(prev => prev.slice(1));
  }, []);

  // Helper for Read Ahead Icon/Color
  const getReadAheadConfig = () => {
      switch(settings.readAheadLevel) {
          case 'FOCUS': return { label: 'Focus', color: 'text-dino-600', bg: 'bg-dino-100', bonus: '+10%' };
          case 'ULTRA': return { label: 'Ultra', color: 'text-purple-600', bg: 'bg-purple-100', bonus: '+20%' };
          case 'BLIND': return { label: 'Blind', color: 'text-red-600', bg: 'bg-red-100', bonus: '+30%' };
          default: return { label: 'Off', color: 'text-stone-400', bg: 'hover:bg-stone-100', bonus: '' };
      }
  };
  const raConfig = getReadAheadConfig();

  return (
    <div className="min-h-screen flex flex-col bg-transparent text-stone-800 font-sans selection:bg-frog-200">
      <header className="w-full bg-stone-50/80 backdrop-blur-md border-b border-stone-200 sticky top-0 z-40 px-6 py-4 shadow-sm transition-all">
        <div className="max-w-[1400px] mx-auto flex flex-col xl:flex-row items-center justify-between gap-4 xl:gap-8">

          <div className="flex flex-col md:flex-row items-center gap-6 md:gap-8 w-full xl:w-auto">
            <div className="flex flex-col items-center md:items-start flex-shrink-0">
              <h1 className="text-xl font-black text-dino-400 tracking-tight flex items-center gap-2">
                <span className="text-2xl">🐸</span> Frog Type
              </h1>
            </div>

            <div className="flex gap-1 p-1 bg-stone-100/80 rounded-lg shadow-inner border border-stone-200/50">
              <button 
                  onClick={() => switchMode('QUOTES')}
                  className={`px-3 py-1.5 rounded-md text-xs font-bold flex items-center gap-1.5 transition-all focus:outline-none focus:ring-2 focus:ring-dino-500 focus:ring-offset-2 ${gameMode === 'QUOTES' ? 'bg-white text-dino-600 shadow-sm ring-1 ring-stone-200' : 'text-stone-400 hover:bg-stone-200/50 hover:text-stone-600'}`}
              >
                  <BookOpen className="w-3.5 h-3.5" /> Quotes
              </button>
              <button 
                  onClick={() => switchMode('HARDCORE')}
                  disabled={isHardcoreLocked}
                  title={isHardcoreLocked ? "Unlocks at Polliwog level" : "High risk, high reward"}
                  className={`px-3 py-1.5 rounded-md text-xs font-bold flex items-center gap-1.5 transition-all focus:outline-none focus:ring-2 focus:ring-dino-500 focus:ring-offset-2 
                    ${gameMode === 'HARDCORE' 
                      ? 'bg-stone-800 text-white shadow-sm ring-1 ring-stone-900' 
                      : isHardcoreLocked 
                          ? 'opacity-50 cursor-not-allowed text-stone-400 bg-stone-100' 
                          : 'text-stone-400 hover:bg-stone-200/50 hover:text-stone-600'}`}
              >
                  {isHardcoreLocked ? <Lock className="w-3.5 h-3.5" /> : <Skull className="w-3.5 h-3.5" />} 
                  Hardcore
              </button>
              <button 
                  onClick={() => switchMode('FIX_MISTAKE')}
                  disabled={mistakePool.length === 0}
                  className={`px-3 py-1.5 rounded-md text-xs font-bold flex items-center gap-1.5 transition-all focus:outline-none focus:ring-2 focus:ring-dino-500 focus:ring-offset-2 
                    ${gameMode === 'FIX_MISTAKE' ? 'bg-red-500 text-white shadow-sm ring-1 ring-red-600' : 'text-stone-400 hover:bg-stone-200/50 hover:text-stone-600'}
                    ${mistakePool.length === 0 ? 'opacity-50 cursor-not-allowed' : ''}
                  `}
                  title={mistakePool.length === 0 ? "No mistakes recorded yet" : `${mistakePool.length} words to fix`}
              >
                  <Eraser className="w-3.5 h-3.5" /> Fix ({mistakePool.length})
              </button>
            </div>
          </div>

          <div className="w-full xl:w-auto xl:flex-grow xl:max-w-2xl flex items-center gap-4 justify-end">
             <ProgressBar 
               xp={userXP} 
               avgWpm={getAverageWPM(wpmHistory)} 
               mistakeCount={mistakePool.length} 
             />

             <div className="flex items-center gap-1.5 border-l border-stone-200 pl-4 ml-2 shrink-0">
               <button 
                 onClick={cycleReadAhead}
                 className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-dino-500 focus:ring-offset-2 group relative ${raConfig.bg} ${raConfig.color}`}
                 title={`Read Ahead: ${raConfig.label} (${raConfig.bonus ? raConfig.bonus + ' XP' : 'No Bonus'})`}
               >
                  {settings.readAheadLevel === 'NONE' ? <Eye className="w-5 h-5" /> : <EyeOff className="w-5 h-5" />}
                  {raConfig.bonus && (
                      <span className="absolute -top-1 -right-1 bg-dino-500 text-white text-[8px] px-1 rounded-full font-bold">
                          {raConfig.bonus.replace('+','')}
                      </span>
                  )}
               </button>

               <button 
                 onClick={toggleAchievements} 
                 className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-dino-500 focus:ring-offset-2 ${isAchievementsOpen ? 'bg-stone-100 text-dino-600' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                 title="Achievements"
               >
                  <Award className="w-5 h-5" />
               </button>
               <button 
                 onClick={toggleTheme} 
                 className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-dino-500 focus:ring-offset-2 ${isThemeOpen ? 'bg-stone-100 text-dino-600' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                 title="Themes"
               >
                  <Palette className="w-5 h-5" />
               </button>
               <button 
                 onClick={toggleStats} 
                 className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-dino-500 focus:ring-offset-2 ${isStatsOpen ? 'bg-stone-100 text-dino-600' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                 title="Statistics & History"
               >
                  <TrendingUp className="w-5 h-5" />
               </button>
               <button 
                 onClick={toggleHelp} 
                 className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-dino-500 focus:ring-offset-2 ${isHelpOpen ? 'bg-stone-100 text-stone-700' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                 title="How to Play"
               >
                  <CircleHelp className="w-5 h-5" />
               </button>
               <button 
                 onClick={toggleMusic} 
                 className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-dino-500 focus:ring-offset-2 ${isMusicOpen || settings.musicConfig.source !== 'NONE' ? 'bg-stone-100 text-dino-600' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                 title="Background Music"
               >
                  <Music className="w-5 h-5" />
               </button>
               <button onClick={toggleSettings} className="p-2 hover:bg-stone-100 rounded-full text-stone-400 hover:text-stone-600 transition-colors focus:outline-none focus:ring-2 focus:ring-dino-500 focus:ring-offset-2">
                  <SettingsIcon className="w-5 h-5" />
               </button>
             </div>
          </div>

        </div>
      </header>

      <main className="flex-grow flex flex-col items-center justify-center p-6 md:p-12 w-full relative">
        <div className="w-full flex items-center justify-center min-h-[60vh]">
          {loading && !currentQuote ? (
            <div className="flex flex-col items-center justify-center text-stone-400 animate-pulse">
              <Loader2 className="w-10 h-10 animate-spin mb-4 text-dino-400" />
              <p className="font-mono text-xs">
                  Hatching wisdom...
              </p>
            </div>
          ) : currentQuote ? (
            <TypingArea 
              quote={currentQuote} 
              onComplete={handleQuoteComplete} 
              onFail={handleQuoteFail}
              onMistake={handleMistake}
              onRequestNewQuote={handleRequestNextQuote}
              streak={streak}
              ghostWpm={getAverageWPM(wpmHistory)}
              settings={settings}
              gameMode={gameMode}
              onInteract={() => setIsMusicOpen(false)}
            />
          ) : (
             <div className="flex flex-col items-center justify-center text-stone-400">
              <Loader2 className="w-10 h-10 animate-spin mb-4 text-dino-400" />
              <p className="font-mono text-xs">Fetching wisdom...</p>
            </div>
          )}
        </div>
      </main>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        settings={settings} 
        setSettings={setSettings} 
      />

      <ThemeModal
        isOpen={isThemeOpen}
        onClose={() => setIsThemeOpen(false)}
        currentThemeId={settings.themeId}
        setThemeId={(id) => setSettings({ ...settings, themeId: id })}
        currentLevel={getCurrentLevel(userXP)}
        allLevels={LEVELS}
      />

      <AchievementsModal
        isOpen={isAchievementsOpen}
        onClose={() => setIsAchievementsOpen(false)}
        unlockedIds={unlockedAchievements}
      />

      <AchievementToast 
        notifications={notificationQueue}
        onClear={clearToast}
      />

      <HelpModal
        isOpen={isHelpOpen}
        onClose={() => setIsHelpOpen(false)}
      />

      <StatsModal
        isOpen={isStatsOpen}
        onClose={() => setIsStatsOpen(false)}
        avgWpm={getAverageWPM(wpmHistory)}
        history={testHistory}
        onPractice={handlePracticeFromHistory}
        totalTime={totalTimePlayed}
        joinDate={joinDate}
        streak={dailyStreak} // Pass Daily Streak here instead of Session Streak
        userName={userName}
        setUserName={setUserName}
        completedTestsCount={testHistory.length}
      />

      <MusicPlayer 
        isOpen={isMusicOpen} 
        onClose={() => setIsMusicOpen(false)} 
        settings={settings}
        setSettings={setSettings}
        userXP={userXP}
      />

      <footer className="p-6 text-center text-stone-300 text-[10px]">
        <p>© {new Date().getFullYear()} Frog Type. Wisdom from the Ages.</p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useLayoutEffect, useRef } from 'react';
import ProgressBar from './components/ProgressBar';
import TypingArea from './components/TypingArea';
import SettingsModal from './components/SettingsModal';
import HelpModal from './components/HelpModal';
import StatsModal from './components/StatsModal';
import ThemeModal from './components/ThemeModal';
import AchievementsModal from './components/AchievementsModal';
import AchievementToast from './components/AchievementToast';
import { MusicPlayer } from './components/MusicPlayer';
import { Quote, Settings, GameMode, TestResult, NotificationItem, ReadAheadLevel } from './types';
import { fetchQuotes } from './services/quoteService';
import { getCurrentLevel, getNextLevel, getAverageWPM, LEVELS, calculateXP } from './utils/gameLogic';
import { soundEngine } from './utils/soundEngine';
import { Loader2, Settings as SettingsIcon, Music, CircleHelp, Skull, BookOpen, Eraser, TrendingUp, Palette, Award, Radio, Lock, Eye, EyeOff, Flame } from 'lucide-react';
import confetti from 'canvas-confetti';
import { THEMES } from './data/themes';
import { ACHIEVEMENTS } from './data/achievements';
import { RADIO_STATIONS } from './data/radioStations';

const App: React.FC = () => {
  // User Stats Persistence
  const [userName, setUserName] = useState<string>(() => {
      return localStorage.getItem('frogType_userName') || 'Froggy';
  });

  const [joinDate, setJoinDate] = useState<string>(() => {
      const stored = localStorage.getItem('frogType_joinDate');
      if (stored) return stored;
      const now = new Date().toISOString();
      localStorage.setItem('frogType_joinDate', now);
      return now;
  });

  const [totalTimePlayed, setTotalTimePlayed] = useState<number>(() => {
      const stored = localStorage.getItem('frogType_totalTime');
      return stored ? parseInt(stored, 10) : 0;
  });

  const [userXP, setUserXP] = useState<number>(() => {
    const saved = localStorage.getItem('frogXP');
    const legacy = localStorage.getItem('frogType_xp');
    if (saved) return parseInt(saved, 10);
    if (legacy) return parseInt(legacy, 10);
    return 0;
  });

  const currentLevel = getCurrentLevel(userXP);

  // Track unlocked tiers persistently to prevent repeat notifications
  const [unlockedTiers, setUnlockedTiers] = useState<string[]>(() => {
    const saved = localStorage.getItem('frogType_unlockedTiers');
    return saved ? JSON.parse(saved) : [];
  });

  // Session Streak (Consecutive Quotes)
  const [streak, setStreak] = useState<number>(() => {
    const saved = localStorage.getItem('frogType_streak');
    return saved ? parseInt(saved, 10) : 0;
  });

  // Daily Streak Logic
  const [dailyStreak, setDailyStreak] = useState<number>(() => {
     const saved = localStorage.getItem('frogType_dailyStreak');
     return saved ? parseInt(saved, 10) : 0;
  });

  const [unlockedAchievements, setUnlockedAchievements] = useState<string[]>(() => {
    const saved = localStorage.getItem('frogType_achievements');
    return saved ? JSON.parse(saved) : [];
  });

  const [notificationQueue, setNotificationQueue] = useState<NotificationItem[]>([]);

  // Track history for average WPM calculation (Last 10)
  const [wpmHistory, setWpmHistory] = useState<number[]>(() => {
    const saved = localStorage.getItem('frogType_wpmHistory');
    return saved ? JSON.parse(saved) : [];
  });

  // Track full history of tests
  const [testHistory, setTestHistory] = useState<TestResult[]>(() => {
    const saved = localStorage.getItem('frogType_history');
    return saved ? JSON.parse(saved) : [];
  });

  const [lastWpm, setLastWpm] = useState<number>(() => {
    const saved = localStorage.getItem('frogType_lastWpm');
    return saved ? parseInt(saved, 10) : 0;
  });

  const [mistakePool, setMistakePool] = useState<string[]>(() => {
    const saved = localStorage.getItem('frogType_mistakes');
    return saved ? JSON.parse(saved) : [];
  });

  const [settings, setSettings] = useState<Settings>(() => {
    const saved = localStorage.getItem('frogType_settings');

    if (!saved) {
      return { 
        ghostEnabled: false, 
        readAheadLevel: 'NONE', 
        sfxEnabled: true,
        mechanicalSoundEnabled: false,
        mechanicalSoundPreset: 'THOCK',
        ambientVolume: 0.02, 
        musicConfig: { source: 'GENERATED', presetId: 'PIANO_SATIE' },
        themeId: 'CLASSIC'
      };
    }

    const parsed = JSON.parse(saved);
    const legacyBrownNoiseEnabled = parsed.brownNoiseEnabled === true;
    const legacyVolume = parsed.brownNoiseVolume ?? 0.5;

    // Migration for legacy boolean readAhead
    let initialReadAhead = parsed.readAheadLevel;
    if (parsed.readAheadEnabled === true && !initialReadAhead) initialReadAhead = 'FOCUS';
    if (!initialReadAhead) initialReadAhead = 'NONE';

    let initialMusicConfig = parsed.musicConfig || { source: 'NONE', presetId: '' };
    if (legacyBrownNoiseEnabled && initialMusicConfig.source === 'NONE') {
        initialMusicConfig = { source: 'GENERATED', presetId: 'BROWN_NOISE' };
    }

    return { 
      ghostEnabled: false, 
      readAheadLevel: initialReadAhead, 
      sfxEnabled: true,
      mechanicalSoundEnabled: parsed.mechanicalSoundEnabled ?? false,
      mechanicalSoundPreset: parsed.mechanicalSoundPreset || 'THOCK',
      ambientVolume: parsed.ambientVolume ?? legacyVolume, 
      musicConfig: initialMusicConfig,
      themeId: parsed.themeId || 'CLASSIC',
      ...parsed
    };
  });

  const [gameMode, setGameMode] = useState<GameMode>(() => {
    const saved = localStorage.getItem('frogType_gameMode');
    return (saved as GameMode) || 'QUOTES';
  });

  const [completedQuotes, setCompletedQuotes] = useState<string[]>(() => {
    const saved = localStorage.getItem('frogType_completedQuotes');
    return saved ? JSON.parse(saved) : [];
  });

  const [quotesQueue, setQuotesQueue] = useState<Quote[]>([]);

  const [currentQuote, setCurrentQuote] = useState<Quote | null>(() => {
    const saved = localStorage.getItem('frogType_currentQuote');
    return saved ? JSON.parse(saved) : null;
  });

  const [loading, setLoading] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isMusicOpen, setIsMusicOpen] = useState(false);
  const [isHelpOpen, setIsHelpOpen] = useState(false);
  const [isStatsOpen, setIsStatsOpen] = useState(false);
  const [isThemeOpen, setIsThemeOpen] = useState(false);
  const [isAchievementsOpen, setIsAchievementsOpen] = useState(false);

  // Start time tracking for current quote
  const [quoteStartTime, setQuoteStartTime] = useState<number | null>(null);

  const isFetchingRef = useRef(false);

  // Derive Lock State
  const uniqueTiers = Array.from(new Set(LEVELS.map(l => l.tier)));
  const currentTierIndex = uniqueTiers.indexOf(currentLevel.tier);
  const polliwogIndex = uniqueTiers.indexOf('Polliwog');
  const isHardcoreLocked = currentTierIndex < polliwogIndex;

  // Persistence
  useEffect(() => { localStorage.setItem('frogXP', userXP.toString()); }, [userXP]);
  useEffect(() => { localStorage.setItem('frogType_unlockedTiers', JSON.stringify(unlockedTiers)); }, [unlockedTiers]);
  useEffect(() => { localStorage.setItem('frogType_streak', streak.toString()); }, [streak]);
  useEffect(() => { localStorage.setItem('frogType_dailyStreak', dailyStreak.toString()); }, [dailyStreak]);
  useEffect(() => { localStorage.setItem('frogType_lastWpm', lastWpm.toString()); }, [lastWpm]);
  useEffect(() => { localStorage.setItem('frogType_wpmHistory', JSON.stringify(wpmHistory)); }, [wpmHistory]);
  useEffect(() => { localStorage.setItem('frogType_history', JSON.stringify(testHistory)); }, [testHistory]);
  useEffect(() => { localStorage.setItem('frogType_settings', JSON.stringify(settings)); }, [settings]);
  useEffect(() => { localStorage.setItem('frogType_mistakes', JSON.stringify(mistakePool)); }, [mistakePool]);
  useEffect(() => { localStorage.setItem('frogType_userName', userName); }, [userName]);
  useEffect(() => { localStorage.setItem('frogType_totalTime', totalTimePlayed.toString()); }, [totalTimePlayed]);

  // Game Mode Persistence & Lock Check
  useEffect(() => { 
      if (gameMode === 'HARDCORE' && isHardcoreLocked) {
          setGameMode('QUOTES');
      }
      localStorage.setItem('frogType_gameMode', gameMode); 
  }, [gameMode, isHardcoreLocked]);

  useEffect(() => { localStorage.setItem('frogType_completedQuotes', JSON.stringify(completedQuotes)); }, [completedQuotes]);
  useEffect(() => { localStorage.setItem('frogType_achievements', JSON.stringify(unlockedAchievements)); }, [unlockedAchievements]);

  // Audio Settings Sync
  useEffect(() => {
    soundEngine.setEnabled(settings.sfxEnabled);
    soundEngine.setMechanicalEnabled(settings.mechanicalSoundEnabled);
    soundEngine.setMechanicalPreset(settings.mechanicalSoundPreset);
    soundEngine.setAmbientVolume(settings.ambientVolume);

    if (settings.musicConfig.source === 'GENERATED') {
      soundEngine.setAmbientMusic(settings.musicConfig.presetId);
    } else {
      soundEngine.stopAmbientMusic();
    }
  }, [settings.sfxEnabled, settings.mechanicalSoundEnabled, settings.mechanicalSoundPreset, settings.ambientVolume, settings.musicConfig]);

  useLayoutEffect(() => {
    const theme = THEMES.find(t => t.id === settings.themeId) || THEMES[0];
    const root = document.documentElement;
    root.style.setProperty('--bg-body', theme.colors.background);
    Object.entries(theme.colors.frog).forEach(([key, value]) => {
       root.style.setProperty(`--frog-${key}`, value);
    });
    Object.entries(theme.colors.stone).forEach(([key, value]) => {
       root.style.setProperty(`--stone-${key}`, value);
    });
    root.style.setProperty('--text-body', theme.colors.stone[800]);
  }, [settings.themeId]);

  useEffect(() => {
    const handleInteraction = () => {
      soundEngine.resumeContext();
      window.removeEventListener('click', handleInteraction);
      window.removeEventListener('keydown', handleInteraction);
    };

    window.addEventListener('click', handleInteraction);
    window.addEventListener('keydown', handleInteraction);
    return () => {
      window.removeEventListener('click', handleInteraction);
      window.removeEventListener('keydown', handleInteraction);
    };
  }, []);

  useEffect(() => { 
    if (currentQuote) {
      localStorage.setItem('frogType_currentQuote', JSON.stringify(currentQuote)); 
      setQuoteStartTime(Date.now());
    } else {
      localStorage.removeItem('frogType_currentQuote');
    }
  }, [currentQuote]);

  // Check Daily Streak on Mount
  useEffect(() => {
      const today = new Date().toDateString();
      const lastVisit = localStorage.getItem('frogType_lastVisitDate');

      // If user hasn't visited today, check if streak should break
      if (lastVisit && lastVisit !== today) {
          const yesterday = new Date();
          yesterday.setDate(yesterday.getDate() - 1);

          if (yesterday.toDateString() !== lastVisit) {
              // Streak broken if last visit was not yesterday
              setDailyStreak(0);
          }
      } else if (!lastVisit) {
          setDailyStreak(0);
      }
  }, []);

  const updateDailyStreakActivity = () => {
      const today = new Date().toDateString();
      const lastVisit = localStorage.getItem('frogType_lastVisitDate');

      if (lastVisit !== today) {
          // New day activity
          let newStreak = 1;
          if (lastVisit) {
              const yesterday = new Date();
              yesterday.setDate(yesterday.getDate() - 1);
              if (yesterday.toDateString() === lastVisit) {
                  newStreak = dailyStreak + 1;
              }
          }
          setDailyStreak(newStreak);
          localStorage.setItem('frogType_lastVisitDate', today);

          // Toast for streak
          setNotificationQueue(prev => [...prev, {
              id: `daily_${Date.now()}`,
              title: "Daily Streak!",
              description: `You're on a ${newStreak} day streak.`,
              icon: <Flame className="w-5 h-5 text-orange-500" />,
              type: "INFO"
          }]);
      } else {
          // Already played today, ensure streak is at least 1 if it was 0
          if (dailyStreak === 0) {
              setDailyStreak(1);
              localStorage.setItem('frogType_lastVisitDate', today);
          }
      }
  };

  const generateMistakeQuote = useCallback((): Quote | null => {
    if (mistakePool.length === 0) return null;
    let pool = [...mistakePool];
    while (pool.length < 15) {
       pool = [...pool, ...mistakePool];
    }
    const shuffled = pool.sort(() => 0.5 - Math.random());
    const selected = shuffled.slice(0, 15);
    const text = selected.join(' ');

    return {
      text,
      source: "Personal Training",
      author: "Your Mistakes"
    };
  }, [mistakePool]);

  const loadMoreQuotes = useCallback(async () => {
    if (isFetchingRef.current) return;

    isFetchingRef.current = true;

    try {
      const level = getCurrentLevel(userXP);
      // IMPORTANT: Pass completedQuotes to filter them out forever
      const newQuotes = await fetchQuotes(5, completedQuotes, level.tier, gameMode);
      setQuotesQueue(prev => [...prev, ...newQuotes]);
    } catch (error) {
      console.error("Failed to load quotes", error);
    } finally {
      isFetchingRef.current = false;
    }
  }, [completedQuotes, userXP, gameMode]);

  useEffect(() => {
    const init = async () => {
      if (!currentQuote && quotesQueue.length === 0) {
         setLoading(true);
         await loadMoreQuotes();
         setLoading(false);
      } else if (quotesQueue.length < 3) {
         loadMoreQuotes();
      }
    };
    init();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (currentQuote) return;

    if (gameMode === 'FIX_MISTAKE') {
      const mistakeQuote = generateMistakeQuote();
      if (mistakeQuote) {
        setCurrentQuote(mistakeQuote);
      } else {
        setGameMode('QUOTES'); 
      }
    } else {
      if (quotesQueue.length > 0) {
        const next = quotesQueue[0];
        setCurrentQuote(next);
        setQuotesQueue(prev => prev.slice(1));
      }

      if (quotesQueue.length < 3) {
        loadMoreQuotes();
      }
    }
  }, [currentQuote, quotesQueue, gameMode, generateMistakeQuote, loadMoreQuotes]);

  const checkAchievements = (wpm: number) => {
    const newNotifications: NotificationItem[] = [];
    const newUnlockIds: string[] = [];

    const stats = {
       wpm,
       totalQuotes: completedQuotes.length + 1, 
       maxStreak: Math.max(streak + 1, streak + 1),
       currentStreak: streak + 1,
       mode: gameMode
    };

    ACHIEVEMENTS.forEach(ach => {
       if (!unlockedAchievements.includes(ach.id)) {
           if (ach.condition(stats)) {
               newUnlockIds.push(ach.id);
               newNotifications.push({
                   id: ach.id,
                   title: ach.title,
                   description: ach.description,
                   icon: ach.icon,
                   type: 'ACHIEVEMENT'
               });
           }
       }
    });

    if (newUnlockIds.length > 0) {
       setUnlockedAchievements(prev => [...prev, ...newUnlockIds]);
       setNotificationQueue(prev => [...prev, ...newNotifications]);
       soundEngine.playLevelUp(); 
    }
  };

  const handleQuoteComplete = (xpCalc: number, wpm: number, mistakes: string[], retryCount: number) => {
    // Recalculate with Read Ahead Bonus (if any changed since TypingArea)
    // Actually simpler to pass raw WPM/Length and recalc here or trust TypingArea passed value.
    // TypingArea uses calculateXP so it already includes ReadAhead bonus from settings passed to it.
    let finalXp = xpCalc; 

    // Update Time Played
    if (quoteStartTime) {
        const durationSec = Math.floor((Date.now() - quoteStartTime) / 1000);
        setTotalTimePlayed(prev => prev + durationSec);
    }

    if (gameMode === 'HARDCORE') {
      finalXp = finalXp * 5;
    }

    // Fix Mistake Mode Logic
    if (gameMode === 'FIX_MISTAKE' && currentQuote) {
      const wordsFixed = [...new Set(currentQuote.text.split(' '))]; 
      setMistakePool(prev => prev.filter(word => !wordsFixed.includes(word)));
    }

    // Mark quote as completed so it never shows again (if in standard modes)
    if (currentQuote && gameMode !== 'FIX_MISTAKE') {
       setCompletedQuotes(prev => [...prev, currentQuote.text]);
    }

    // Update History
    const newHistory = [...wpmHistory, wpm].slice(-10); 
    setWpmHistory(newHistory);
    const avgWpm = getAverageWPM(newHistory);

    const newTestResult: TestResult = {
      id: Date.now(),
      date: new Date().toISOString(),
      wpm,
      xpEarned: finalXp,
      mode: gameMode,
      quoteText: currentQuote?.text || "",
      mistakes: mistakes,
      retryCount: retryCount
    };
    setTestHistory(prev => [...prev, newTestResult]);

    checkAchievements(wpm);

    // Calculate XP and Handle Gates/Unlocks
    const currentLevelObj = getCurrentLevel(userXP);
    const nextLevelObj = getNextLevel(currentLevelObj);
    let potentialXp = userXP + finalXp;

    if (nextLevelObj && potentialXp >= nextLevelObj.minXP) {
         let effectiveMistakeCount = mistakePool.length;
         if (gameMode === 'FIX_MISTAKE' && currentQuote) {
             const wordsFixed = [...new Set(currentQuote.text.split(' '))];
             effectiveMistakeCount = mistakePool.filter(word => !wordsFixed.includes(word)).length;
         }

         const isMasteryGated = effectiveMistakeCount > 0;
         const isSpeedGated = avgWpm < nextLevelObj.requiredWpm;

         if (isMasteryGated || isSpeedGated) {
            potentialXp = nextLevelObj.minXP - 1; 
         }
    }

    const newLevel = getCurrentLevel(potentialXp);

    // Check for Tier Unlocks (Persistent - Only once per tier)
    if (!unlockedTiers.includes(newLevel.tier)) {
         setUnlockedTiers(prev => [...prev, newLevel.tier]);

         const newStations = RADIO_STATIONS.filter(s => s.tier === newLevel.tier);

         if (newStations.length > 0) {
             const musicNotifications: NotificationItem[] = newStations.map(s => ({
                id: `unlock_${s.id}`,
                title: 'New Station Unlocked',
                description: s.name,
                icon: <Radio className="w-5 h-5 text-stone-900" />,
                type: 'UNLOCK'
             }));
             setNotificationQueue(prev => [...prev, ...musicNotifications]);
         }
    }

    const prevLevel = getCurrentLevel(userXP);
    if (newLevel.tier !== prevLevel.tier && potentialXp >= newLevel.minXP) {
          setTimeout(() => {
              confetti({
                particleCount: 200,
                spread: 120,
                origin: { y: 0.6 },
                colors: ['#40D672', '#22c55e', '#fbbf24', '#f59e0b'],
                startVelocity: 45
              });
              soundEngine.playLevelUp(); 
          }, 300);
    }

    setUserXP(potentialXp);
    setStreak(prev => prev + 1);

    // Update Daily Streak
    updateDailyStreakActivity();

    setLastWpm(wpm);
    setCurrentQuote(null); 
    setQuoteStartTime(null);
  };

  const handleQuoteFail = () => {
    setStreak(0);
  };

  const handleMistake = (word?: string) => {
    const penaltyMultiplier = gameMode === 'HARDCORE' ? 0.5 : 0.85;
    setUserXP(prev => Math.floor(prev * penaltyMultiplier));

    setStreak(0);

    if (word && word.length > 1) {
       setMistakePool(prev => {
         if (prev.includes(word)) return prev;
         return [...prev, word];
       });
    }
  };

  const handlePracticeFromHistory = (mistakes: string[]) => {
      setMistakePool(prev => {
          const newSet = new Set([...prev, ...mistakes]);
          return Array.from(newSet);
      });
      switchMode('FIX_MISTAKE');
  };

  const toggleSettings = () => setIsSettingsOpen(!isSettingsOpen);
  const toggleMusic = () => setIsMusicOpen(!isMusicOpen);
  const toggleHelp = () => setIsHelpOpen(!isHelpOpen);
  const toggleStats = () => setIsStatsOpen(!isStatsOpen);
  const toggleTheme = () => setIsThemeOpen(!isThemeOpen);
  const toggleAchievements = () => setIsAchievementsOpen(!isAchievementsOpen);

  const cycleReadAhead = () => {
      const levels: ReadAheadLevel[] = ['NONE', 'FOCUS', 'ULTRA', 'BLIND'];
      const currentIndex = levels.indexOf(settings.readAheadLevel);
      const nextIndex = (currentIndex + 1) % levels.length;
      setSettings({ ...settings, readAheadLevel: levels[nextIndex] });
      soundEngine.playKeypress(); // Feedback
  };

  const switchMode = (mode: GameMode) => {
    if (mode === 'FIX_MISTAKE' && mistakePool.length === 0) return;
    if (mode === 'HARDCORE' && isHardcoreLocked) return;
    setGameMode(mode);
    setQuotesQueue([]); 
    setCurrentQuote(null); 
  };

  const handleRequestNextQuote = async () => {
      setCurrentQuote(null);
      setQuoteStartTime(null);
  };

  const clearToast = useCallback(() => {
    setNotificationQueue(prev => prev.slice(1));
  }, []);

  // Helper for Read Ahead Icon/Color
  const getReadAheadConfig = () => {
      switch(settings.readAheadLevel) {
          case 'FOCUS': return { label: 'Focus', color: 'text-frog-green', bg: 'bg-frog-100', bonus: '+10%' };
          case 'ULTRA': return { label: 'Ultra', color: 'text-purple-600', bg: 'bg-purple-100', bonus: '+20%' };
          case 'BLIND': return { label: 'Blind', color: 'text-red-600', bg: 'bg-red-100', bonus: '+30%' };
          default: return { label: 'Off', color: 'text-stone-400', bg: 'hover:bg-stone-100', bonus: '' };
      }
  };
  const raConfig = getReadAheadConfig();

  return (
    <div className="min-h-screen flex flex-col bg-transparent text-stone-800 font-sans selection:bg-frog-200">
      <header className="w-full bg-stone-50/80 backdrop-blur-md border-b border-stone-200 sticky top-0 z-40 px-6 py-4 shadow-sm transition-all">
        <div className="max-w-[1400px] mx-auto flex flex-col xl:flex-row items-center justify-between gap-4 xl:gap-8">

          <div className="flex flex-col md:flex-row items-center gap-6 md:gap-8 w-full xl:w-auto">
            <div className="flex flex-col items-center md:items-start flex-shrink-0">
              <h1 className="text-xl font-black text-frog-green tracking-tight flex items-center gap-2">
                <span className="text-2xl">🐸</span> Frog Type
              </h1>
            </div>

            <div className="flex gap-1 p-1 bg-stone-100/80 rounded-lg shadow-inner border border-stone-200/50">
              <button 
                  onClick={() => switchMode('QUOTES')}
                  className={`px-3 py-1.5 rounded-md text-xs font-bold flex items-center gap-1.5 transition-all focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 ${gameMode === 'QUOTES' ? 'bg-white text-frog-green shadow-sm ring-1 ring-stone-200' : 'text-stone-400 hover:bg-stone-200/50 hover:text-stone-600'}`}
              >
                  <BookOpen className="w-3.5 h-3.5" /> Quotes
              </button>
              <button 
                  onClick={() => switchMode('HARDCORE')}
                  disabled={isHardcoreLocked}
                  title={isHardcoreLocked ? "Unlocks at Polliwog level" : "High risk, high reward"}
                  className={`px-3 py-1.5 rounded-md text-xs font-bold flex items-center gap-1.5 transition-all focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 
                    ${gameMode === 'HARDCORE' 
                      ? 'bg-stone-800 text-white shadow-sm ring-1 ring-stone-900' 
                      : isHardcoreLocked 
                          ? 'opacity-50 cursor-not-allowed text-stone-400 bg-stone-100' 
                          : 'text-stone-400 hover:bg-stone-200/50 hover:text-stone-600'}`}
              >
                  {isHardcoreLocked ? <Lock className="w-3.5 h-3.5" /> : <Skull className="w-3.5 h-3.5" />} 
                  Hardcore
              </button>
              <button 
                  onClick={() => switchMode('FIX_MISTAKE')}
                  disabled={mistakePool.length === 0}
                  className={`px-3 py-1.5 rounded-md text-xs font-bold flex items-center gap-1.5 transition-all focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 
                    ${gameMode === 'FIX_MISTAKE' ? 'bg-red-500 text-white shadow-sm ring-1 ring-red-600' : 'text-stone-400 hover:bg-stone-200/50 hover:text-stone-600'}
                    ${mistakePool.length === 0 ? 'opacity-50 cursor-not-allowed' : ''}
                  `}
                  title={mistakePool.length === 0 ? "No mistakes recorded yet" : `${mistakePool.length} words to fix`}
              >
                  <Eraser className="w-3.5 h-3.5" /> Fix ({mistakePool.length})
              </button>
            </div>
          </div>

          <div className="w-full xl:w-auto xl:flex-grow xl:max-w-2xl flex items-center gap-4 justify-end">
             <ProgressBar 
               xp={userXP} 
               avgWpm={getAverageWPM(wpmHistory)} 
               mistakeCount={mistakePool.length} 
             />

             <div className="flex items-center gap-1.5 border-l border-stone-200 pl-4 ml-2 shrink-0">
               <button 
                 onClick={cycleReadAhead}
                 className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 group relative ${raConfig.bg} ${raConfig.color}`}
                 title={`Read Ahead: ${raConfig.label} (${raConfig.bonus ? raConfig.bonus + ' XP' : 'No Bonus'})`}
               >
                  {settings.readAheadLevel === 'NONE' ? <Eye className="w-5 h-5" /> : <EyeOff className="w-5 h-5" />}
                  {raConfig.bonus && (
                      <span className="absolute -top-1 -right-1 bg-frog-green text-white text-[8px] px-1 rounded-full font-bold">
                          {raConfig.bonus.replace('+','')}
                      </span>
                  )}
               </button>

               <button 
                 onClick={toggleAchievements} 
                 className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 ${isAchievementsOpen ? 'bg-stone-100 text-frog-green' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                 title="Achievements"
               >
                  <Award className="w-5 h-5" />
               </button>
               <button 
                 onClick={toggleTheme} 
                 className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 ${isThemeOpen ? 'bg-stone-100 text-frog-green' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                 title="Themes"
               >
                  <Palette className="w-5 h-5" />
               </button>
               <button 
                 onClick={toggleStats} 
                 className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 ${isStatsOpen ? 'bg-stone-100 text-frog-green' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                 title="Statistics & History"
               >
                  <TrendingUp className="w-5 h-5" />
               </button>
               <button 
                 onClick={toggleHelp} 
                 className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 ${isHelpOpen ? 'bg-stone-100 text-stone-700' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                 title="How to Play"
               >
                  <CircleHelp className="w-5 h-5" />
               </button>
               <button 
                 onClick={toggleMusic} 
                 className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 ${isMusicOpen || settings.musicConfig.source !== 'NONE' ? 'bg-stone-100 text-frog-green' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                 title="Background Music"
               >
                  <Music className="w-5 h-5" />
               </button>
               <button onClick={toggleSettings} className="p-2 hover:bg-stone-100 rounded-full text-stone-400 hover:text-stone-600 transition-colors focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2">
                  <SettingsIcon className="w-5 h-5" />
               </button>
             </div>
          </div>

        </div>
      </header>

      <main className="flex-grow flex flex-col items-center justify-center p-6 md:p-12 w-full relative">
        <div className="w-full flex items-center justify-center min-h-[60vh]">
          {loading && !currentQuote ? (
            <div className="flex flex-col items-center justify-center text-stone-400 animate-pulse">
              <Loader2 className="w-10 h-10 animate-spin mb-4 text-frog-green" />
              <p className="font-mono text-xs">
                  Hatching wisdom...
              </p>
            </div>
          ) : currentQuote ? (
            <TypingArea 
              quote={currentQuote} 
              onComplete={handleQuoteComplete} 
              onFail={handleQuoteFail}
              onMistake={handleMistake}
              onRequestNewQuote={handleRequestNextQuote}
              streak={streak}
              ghostWpm={getAverageWPM(wpmHistory)}
              settings={settings}
              gameMode={gameMode}
              onInteract={() => setIsMusicOpen(false)}
            />
          ) : (
             <div className="flex flex-col items-center justify-center text-stone-400">
              <Loader2 className="w-10 h-10 animate-spin mb-4 text-frog-green" />
              <p className="font-mono text-xs">Fetching wisdom...</p>
            </div>
          )}
        </div>
      </main>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        settings={settings} 
        setSettings={setSettings} 
      />

      <ThemeModal
        isOpen={isThemeOpen}
        onClose={() => setIsThemeOpen(false)}
        currentThemeId={settings.themeId}
        setThemeId={(id) => setSettings({ ...settings, themeId: id })}
        currentLevel={getCurrentLevel(userXP)}
        allLevels={LEVELS}
      />

      <AchievementsModal
        isOpen={isAchievementsOpen}
        onClose={() => setIsAchievementsOpen(false)}
        unlockedIds={unlockedAchievements}
      />

      <AchievementToast 
        notifications={notificationQueue}
        onClear={clearToast}
      />

      <HelpModal
        isOpen={isHelpOpen}
        onClose={() => setIsHelpOpen(false)}
      />

      <StatsModal
        isOpen={isStatsOpen}
        onClose={() => setIsStatsOpen(false)}
        avgWpm={getAverageWPM(wpmHistory)}
        history={testHistory}
        onPractice={handlePracticeFromHistory}
        totalTime={totalTimePlayed}
        joinDate={joinDate}
        streak={dailyStreak} // Pass Daily Streak here instead of Session Streak
        userName={userName}
        setUserName={setUserName}
        completedTestsCount={testHistory.length}
      />

      <MusicPlayer 
        isOpen={isMusicOpen} 
        onClose={() => setIsMusicOpen(false)} 
        settings={settings}
        setSettings={setSettings}
        userXP={userXP}
      />

      <footer className="p-6 text-center text-stone-300 text-[10px]">
        <p>© {new Date().getFullYear()} Frog Type. Wisdom from the Ages.</p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback, useLayoutEffect } from 'react';
import { Quote, GameStatus, Settings, GameMode } from '../types';
import { calculateXP } from '../utils/gameLogic';
import { soundEngine } from '../utils/soundEngine';
import { Play, RotateCcw, Award, Flame, Ghost, EyeOff, Quote as QuoteIcon, Skull, Eraser, Lock, Sparkles, ArrowUp } from 'lucide-react';

interface TypingAreaProps {
  quote: Quote;
  onComplete: (xpEarned: number, wpm: number, mistakes: string[], retryCount: number) => void;
  onFail: () => void;
  onMistake: (word?: string) => void;
  onRequestNewQuote: () => void;
  streak: number;
  ghostWpm: number;
  settings: Settings;
  gameMode: GameMode;
  onInteract?: () => void;
}

const TypingArea: React.FC<TypingAreaProps> = ({ 
  quote, 
  onComplete, 
  onFail, 
  onMistake,
  onRequestNewQuote,
  streak,
  ghostWpm,
  settings,
  gameMode,
  onInteract
}) => {
  const [input, setInput] = useState('');
  const [startTime, setStartTime] = useState<number | null>(null);
  const [endTime, setEndTime] = useState<number | null>(null);
  const [isFocused, setIsFocused] = useState(false);
  const [status, setStatus] = useState<GameStatus>(GameStatus.IDLE);
  const [wpm, setWpm] = useState(0);
  const [ghostIndex, setGhostIndex] = useState(0);
  const [capsLock, setCapsLock] = useState(false);
  const [isShiftPressed, setIsShiftPressed] = useState(false);

  // Tracking Stats
  const [sessionMistakes, setSessionMistakes] = useState(0);
  const [sessionMistakeWords, setSessionMistakeWords] = useState<string[]>([]);
  const [retryCount, setRetryCount] = useState(0);

  // Smooth Caret State
  const [caretPos, setCaretPos] = useState({ left: 0, top: 0, height: 24, opacity: 0 });

  const inputRef = useRef<HTMLTextAreaElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const textContainerRef = useRef<HTMLDivElement>(null);
  const nextButtonRef = useRef<HTMLButtonElement>(null);
  const retryButtonRef = useRef<HTMLButtonElement>(null);

  // Sync Settings with Engine
  useEffect(() => {
    soundEngine.setEnabled(settings.sfxEnabled);
  }, [settings.sfxEnabled]);

  // Reset state when quote changes
  useEffect(() => {
    setInput('');
    setStartTime(null);
    setEndTime(null);
    setStatus(GameStatus.IDLE);
    setWpm(0);
    setGhostIndex(0);
    setSessionMistakes(0);
    setSessionMistakeWords([]);
    setRetryCount(0);
    if (isFocused) {
        inputRef.current?.focus();
    }
  }, [quote, isFocused]);

  // Focus management for buttons when game ends
  useEffect(() => {
    if (status === GameStatus.COMPLETED) {
        setTimeout(() => nextButtonRef.current?.focus(), 50);
    } else if (status === GameStatus.FAILED) {
        setTimeout(() => retryButtonRef.current?.focus(), 50);
    }
  }, [status]);

  // Handlers wrapped in useCallback for stable dependencies
  const handleRetry = useCallback(() => {
    setInput('');
    setStartTime(null);
    setEndTime(null);
    setStatus(GameStatus.IDLE);
    setWpm(0);
    setGhostIndex(0);
    setSessionMistakes(0); 
    setRetryCount(prev => prev + 1);
    setIsFocused(true);
    setTimeout(() => inputRef.current?.focus(), 10);
  }, []);

  const handleNext = useCallback(() => {
    const isPerfectMaster = retryCount === 0 && sessionMistakes === 0;
    const xp = calculateXP(wpm, quote.text.length, streak, isPerfectMaster, settings.readAheadLevel);
    onComplete(xp, wpm, sessionMistakeWords, retryCount);
  }, [onComplete, wpm, quote.text.length, streak, retryCount, sessionMistakes, sessionMistakeWords, settings.readAheadLevel]);

  // Caps Lock & Shift Detection
  useEffect(() => {
    const checkCapsLock = (e: KeyboardEvent | MouseEvent) => {
      if (e.getModifierState) {
        setCapsLock(e.getModifierState('CapsLock'));
      }
    };

    const handleKeyDown = (e: KeyboardEvent) => {
        if (e.key === 'Shift') setIsShiftPressed(true);
    };
    const handleKeyUp = (e: KeyboardEvent) => {
        if (e.key === 'Shift') setIsShiftPressed(false);
    };

    window.addEventListener('keydown', checkCapsLock as any);
    window.addEventListener('keyup', checkCapsLock as any);
    window.addEventListener('click', checkCapsLock as any);
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    return () => {
      window.removeEventListener('keydown', checkCapsLock as any);
      window.removeEventListener('keyup', checkCapsLock as any);
      window.removeEventListener('click', checkCapsLock as any);
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, []);

  // Global keydown listener
  useEffect(() => {
    const handleGlobalKeyDown = (e: KeyboardEvent) => {
      if (status === GameStatus.COMPLETED) {
        if (e.key === 'Enter' || e.key === 'Tab') {
          e.preventDefault();
          handleNext();
        }
        return;
      }

      if (status === GameStatus.FAILED) {
        if (e.key === 'Enter' || e.key === 'Tab') {
          e.preventDefault();
          handleRetry();
        }
        return;
      }

      if (!isFocused) {
        if (e.key === 'Tab') return;

        if (!e.metaKey && !e.altKey && !e.ctrlKey) {
            e.preventDefault(); 
            setIsFocused(true);
            inputRef.current?.focus();
        }
      }
    };
    window.addEventListener('keydown', handleGlobalKeyDown);
    return () => window.removeEventListener('keydown', handleGlobalKeyDown);
  }, [isFocused, status, handleNext, handleRetry]);

  // Smooth Caret Calculation
  useLayoutEffect(() => {
    const updateCaret = () => {
        if (!textContainerRef.current) return;

        let targetEl: HTMLElement | null = null;
        let left = 0;
        let top = 0;
        let height = 0;

        if (input.length < quote.text.length) {
            // Find current char
            targetEl = textContainerRef.current.querySelector(`[data-index="${input.length}"]`);
            if (targetEl) {
                left = targetEl.offsetLeft;
                top = targetEl.offsetTop;
                height = targetEl.offsetHeight;
            }
        } else {
            // End of text, position after last char
            targetEl = textContainerRef.current.querySelector(`[data-index="${input.length - 1}"]`);
            if (targetEl) {
                left = targetEl.offsetLeft + targetEl.offsetWidth;
                top = targetEl.offsetTop;
                height = targetEl.offsetHeight;
            } else if (quote.text.length === 0) {
                 // Empty quote fallback
                 left = 0;
                 top = 0;
                 height = 24; 
            }
        }

        // Handle visual adjustment for empty state or start
        if (input.length === 0 && quote.text.length > 0) {
             const firstEl = textContainerRef.current.querySelector(`[data-index="0"]`) as HTMLElement;
             if (firstEl) {
                 left = firstEl.offsetLeft;
                 top = firstEl.offsetTop;
                 height = firstEl.offsetHeight;
             }
        }

        setCaretPos({ 
            left, 
            top, 
            height: height || 32, // Default height fallback
            opacity: isFocused && status !== GameStatus.COMPLETED && status !== GameStatus.FAILED ? 1 : 0
        });
    };

    updateCaret();
    window.addEventListener('resize', updateCaret);
    return () => window.removeEventListener('resize', updateCaret);
  }, [input, quote, isFocused, status, settings.readAheadLevel]); // Recalculate on any change affecting layout

  const handleFocus = () => {
    if (status === GameStatus.COMPLETED || status === GameStatus.FAILED) return;
    setIsFocused(true);
    inputRef.current?.focus();
  };

  const handleBlur = () => {
    setTimeout(() => {
        if (document.activeElement !== inputRef.current) {
            setIsFocused(false);
        }
    }, 100);
  };

  const calculateStats = useCallback(() => {
    if (!startTime) return { currentWpm: 0 };
    const now = endTime || Date.now();
    const durationInMinutes = (now - startTime) / 60000;
    if (durationInMinutes <= 0) return { currentWpm: 0 };
    const currentWpm = Math.round((input.length / 5) / durationInMinutes);
    return { currentWpm };
  }, [endTime, input.length, startTime]);

  // Game Loop (WPM + Ghost)
  useEffect(() => {
    if (status === GameStatus.PLAYING) {
      const interval = setInterval(() => {
        const { currentWpm } = calculateStats();
        setWpm(currentWpm);

        if (settings.ghostEnabled && ghostWpm > 0 && startTime) {
            const now = Date.now();
            const elapsedMins = (now - startTime) / 60000;
            const projectedChars = (ghostWpm * 5) * elapsedMins;
            setGhostIndex(projectedChars);
        }
      }, 50);
      return () => clearInterval(interval);
    }
  }, [status, calculateStats, settings.ghostEnabled, ghostWpm, startTime]);

  const getWordAt = (index: number, text: string) => {
    const start = text.lastIndexOf(' ', index) + 1;
    let end = text.indexOf(' ', index);
    if (end === -1) end = text.length;
    return text.slice(start, end).replace(/[.,;!?]/g, ''); 
  };

  const handleChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    if (status === GameStatus.COMPLETED) return;

    const val = e.target.value;
    const prevLen = input.length;

    if (status === GameStatus.IDLE && val.length > 0) {
      setStartTime(Date.now());
      setStatus(GameStatus.PLAYING);
    }

    if (val.length > prevLen) {
        soundEngine.playKeypress();
    }

    // --- Instant Fail Check (All Modes) ---
    if (val.length > 0) {
      if (!quote.text.startsWith(val)) {
        soundEngine.playError(); 
        setStatus(GameStatus.FAILED);
        onFail();

        const word = getWordAt(val.length - 1, quote.text);
        onMistake(word);

        // Track locally for history
        setSessionMistakes(prev => prev + 1);
        if (word && !sessionMistakeWords.includes(word)) {
            setSessionMistakeWords(prev => [...prev, word]);
        }
        return;
      }
    }

    setInput(val);

    if (val.length === quote.text.length) {
      const isPerfect = val === quote.text;
      setEndTime(Date.now());

      if (isPerfect) {
        soundEngine.playSuccess(); 
        setStatus(GameStatus.COMPLETED);
        const finalTime = Date.now();
        const durationMins = (finalTime - (startTime || finalTime)) / 60000;
        const finalWpm = Math.round((quote.text.length / 5) / (durationMins || 1));
        setWpm(finalWpm);
      } else {
        soundEngine.playError(); 
        setStatus(GameStatus.FAILED);
        onFail();
      }
    }
  };

  const getReadAheadState = (index: number) => {
    if (settings.readAheadLevel === 'NONE' || status === GameStatus.IDLE) return { isHidden: false, isHighlighted: false };

    const text = quote.text;
    const caret = input.length;

    let currentWordStart = text.lastIndexOf(' ', caret - 1);
    currentWordStart = currentWordStart === -1 ? 0 : currentWordStart + 1;

    let currentWordEnd = text.indexOf(' ', caret);
    if (currentWordEnd === -1) currentWordEnd = text.length;

    // --- LEVEL 1: FOCUS ---
    if (index >= currentWordStart && index < currentWordEnd) {
        return { isHidden: true, isHighlighted: false };
    }

    // --- LEVEL 2: ULTRA ---
    if (settings.readAheadLevel === 'ULTRA' || settings.readAheadLevel === 'BLIND') {
        let nextWordStart = currentWordEnd + 1;
        let nextWordEnd = text.indexOf(' ', nextWordStart);
        if (nextWordEnd === -1) nextWordEnd = text.length;

        if (index >= nextWordStart && index < nextWordEnd) {
            return { isHidden: true, isHighlighted: false }; 
        }
    }

    // --- LEVEL 3: BLIND ---
    if (settings.readAheadLevel === 'BLIND') {
        let nextWordStart = currentWordEnd + 1;
        let nextWordEnd = text.indexOf(' ', nextWordStart);
        if (nextWordEnd === -1) nextWordEnd = text.length;

        let secondNextStart = nextWordEnd + 1;
        let secondNextEnd = text.indexOf(' ', secondNextStart);
        if (secondNextEnd === -1) secondNextEnd = text.length;

        if (index >= secondNextStart && index < secondNextEnd) {
             return { isHidden: true, isHighlighted: false };
        }
    }

    // Highlight next visible word
    if (index > currentWordEnd) { 
        let highlightStart = currentWordEnd + 1;
        if (settings.readAheadLevel === 'ULTRA') {
             let skip1 = text.indexOf(' ', highlightStart);
             if (skip1 !== -1) highlightStart = skip1 + 1;
             else highlightStart = text.length; 
        } else if (settings.readAheadLevel === 'BLIND') {
             let skip1 = text.indexOf(' ', highlightStart);
             let skip2 = skip1 !== -1 ? text.indexOf(' ', skip1 + 1) : -1;
             if (skip2 !== -1) highlightStart = skip2 + 1;
             else highlightStart = text.length;
        }

        let highlightEnd = text.indexOf(' ', highlightStart);
        if (highlightEnd === -1) highlightEnd = text.length;

        if (index >= highlightStart && index < highlightEnd) {
             return { isHidden: false, isHighlighted: true };
        }
    }

    return { isHidden: false, isHighlighted: false };
  };

  const getTextColor = () => {
     if (status === GameStatus.FAILED) {
        if (gameMode === 'HARDCORE') return 'text-red-400/50';
        return 'text-red-300';
     }
     if (gameMode === 'HARDCORE') return 'text-stone-400';
     return 'text-stone-300';
  };

  const renderText = () => {
    return quote.text.split('').map((char, index) => {
      let colorClass = getTextColor(); 
      let bgClass = '';

      const { isHidden, isHighlighted } = getReadAheadState(index);

      if (index < input.length) {
        if (input[index] === char) {
          // Use frog-green for completed text
          colorClass = 'text-frog-green'; 
        } else {
          colorClass = 'text-red-500 bg-red-100'; 
        }
      } else {
          if (isHighlighted) {
              colorClass = 'text-frog-green font-bold';
              bgClass = 'bg-green-100/50';
          }
      }

      if (gameMode === 'FIX_MISTAKE') {
          if (index >= input.length) {
              colorClass = 'text-red-300';
          }
      }

      const isGhostHere = settings.ghostEnabled && Math.floor(ghostIndex) === index;

      return (
        <span key={index} data-index={index} className="relative">
            {isGhostHere && (
                <span className="absolute -left-[2px] top-0 bottom-0 w-[2px] bg-purple-400/50 z-20 animate-pulse">
                     <span className="absolute -top-4 -left-2 text-[10px] text-purple-400 opacity-70">👻</span>
                </span>
            )}

            <span 
                className={`
                    ${colorClass} ${bgClass} transition-colors duration-100
                    ${isHidden ? 'text-transparent selection:text-transparent' : ''}
                    ${isHidden && index < input.length && input[index] !== char ? '!text-red-500 !bg-red-100' : ''} 
                `}
            >
                {char}
            </span>
        </span>
      );
    });
  };

  const getContainerStyle = () => {
    if (status === GameStatus.FAILED) {
        if (gameMode === 'HARDCORE') {
            return 'bg-red-900/20 border-red-900/50 shadow-[0_0_40px_rgba(220,38,38,0.1)]';
        }
        return 'bg-red-50 border-red-200 shadow-inner';
    }

    if (gameMode === 'HARDCORE') {
        return 'bg-neutral-900 border-neutral-800 text-neutral-400 shadow-[0_0_40px_rgba(0,0,0,0.2)]';
    }
    if (gameMode === 'FIX_MISTAKE') {
        return 'bg-red-50 border-red-100';
    }

    // Light gray background for container
    return 'bg-stone-50 border-stone-200 overflow-hidden';
  };

  // Dynamic Text Sizing - Standard/Cozy sizing logic
  const getFontSizeClass = () => {
    const len = quote.text.length;
    // Standard sizes, scaled down if necessary, never massive
    if (len < 100) return 'text-2xl md:text-3xl leading-relaxed';
    if (len < 200) return 'text-xl md:text-2xl leading-relaxed';
    return 'text-lg md:text-xl leading-relaxed';
  };

  const isPerfectMasterPotential = retryCount === 0 && sessionMistakes === 0 && status !== GameStatus.FAILED;

  return (
    <div 
      className="relative w-full max-w-6xl mx-auto min-h-[400px] flex flex-col"
      ref={containerRef}
    >
      {/* Perfect Master Indicator */}
      {isPerfectMasterPotential && status === GameStatus.PLAYING && (
        <div className="absolute -top-8 left-1/2 transform -translate-x-1/2 flex items-center gap-1 text-xs font-bold text-frog-green animate-pulse">
          <Sparkles className="w-3 h-3" /> Perfect Master Potential (1.5x Bonus)
        </div>
      )}

      <div className={`
        relative flex-grow flex flex-col justify-center p-12 md:p-20 rounded-[3rem] transition-all duration-300 border
        ${getContainerStyle()}
        ${isFocused && status !== GameStatus.FAILED && status !== GameStatus.COMPLETED ? 'ring-2 ring-frog-green/50 ring-offset-2 ring-offset-bg-body' : ''}
        ${status === GameStatus.FAILED ? 'ring-2 ring-red-500 shadow-[0_0_20px_rgba(239,68,68,0.3)]' : ''}
        ${status === GameStatus.COMPLETED ? 'ring-2 ring-frog-green/20 bg-green-50/20' : ''}
        ${streak > 2 && status === GameStatus.PLAYING ? 'shadow-[0_0_30px_rgba(251,146,60,0.15)] ring-1 ring-orange-100' : ''}
      `}>

        {!isFocused && status !== GameStatus.COMPLETED && status !== GameStatus.FAILED && (
          <div 
            onClick={handleFocus}
            className="absolute inset-0 z-50 flex items-center justify-center bg-stone-900/5 backdrop-blur-sm cursor-pointer rounded-[3rem] border-2 border-dashed border-frog-green/50 hover:border-frog-green transition-all"
          >
            <div className="text-center animate-bounce text-frog-green">
              <Play className="w-10 h-10 mx-auto mb-2 opacity-80" fill="currentColor" />
              <span className="font-bold text-base tracking-wide uppercase font-sans">Click or Type to Start</span>
            </div>
          </div>
        )}

        {status === GameStatus.COMPLETED && (
          <div className="absolute inset-0 z-40 flex items-center justify-center">
             <div className="bg-stone-50/90 backdrop-blur-md p-8 rounded-3xl shadow-2xl border border-stone-200 animate-in zoom-in-95 fade-in duration-300 flex flex-col items-center gap-6 min-w-[280px]">
                <div className="text-frog-green font-black text-xl tracking-tight flex items-center gap-2">
                   <Award className="w-6 h-6" /> Quote Complete!
                </div>

                <div className="grid grid-cols-2 gap-x-12 gap-y-6 w-full">
                   <div className="flex flex-col items-center">
                      <span className="text-[10px] uppercase font-bold text-stone-400 tracking-widest mb-1">Time</span>
                      <span className="font-mono font-bold text-2xl text-stone-700">
                        {endTime && startTime ? ((endTime - startTime) / 1000).toFixed(1) : '0.0'}s
                      </span>
                   </div>
                   <div className="flex flex-col items-center">
                      <span className="text-[10px] uppercase font-bold text-stone-400 tracking-widest mb-1">Speed</span>
                      <span className="font-mono font-bold text-2xl text-stone-700">{wpm} <span className="text-xs text-stone-400 font-sans font-medium">WPM</span></span>
                   </div>
                   <div className="flex flex-col items-center">
                      <span className="text-[10px] uppercase font-bold text-stone-400 tracking-widest mb-1">Retries</span>
                      <span className="font-mono font-bold text-2xl text-stone-700">
                          {retryCount}
                      </span>
                   </div>
                   <div className="flex flex-col items-center">
                      <span className="text-[10px] uppercase font-bold text-stone-400 tracking-widest mb-1">XP Earned</span>
                      <span className="font-mono font-bold text-2xl text-frog-green">
                        +{calculateXP(wpm, quote.text.length, streak, retryCount === 0 && sessionMistakes === 0, settings.readAheadLevel) * (gameMode === 'HARDCORE' ? 5 : 1)}
                      </span>
                   </div>
                </div>

                <div className="text-[10px] font-medium text-stone-400 bg-stone-100/50 px-3 py-1.5 rounded-full">
                   Press <span className="font-bold text-stone-500">Enter</span> or <span className="font-bold text-stone-500">Tab</span> to continue
                </div>
             </div>
          </div>
        )}

        <div className="absolute top-4 left-0 right-0 flex justify-center gap-2 z-30 select-none pointer-events-none">
            {capsLock && (
              <div className="flex items-center gap-2 px-3 py-1.5 bg-orange-100 text-orange-600 rounded-full text-[10px] font-bold tracking-widest border border-orange-200 shadow-sm animate-pulse">
                <Lock className="w-3 h-3" /> CAPS LOCK
              </div>
            )}
            {isShiftPressed && (
               <div className="flex items-center gap-2 px-3 py-1.5 bg-blue-50 text-blue-600 rounded-full text-[10px] font-bold tracking-widest border border-blue-100 shadow-sm">
                <ArrowUp className="w-3 h-3" /> SHIFT
              </div>
            )}
        </div>

        <div className="absolute inset-0 pointer-events-none select-none overflow-hidden rounded-[3rem]">
           {gameMode === 'QUOTES' && (
              <div className="absolute -top-12 -left-12 opacity-[0.02] transform -rotate-12 transition-all duration-700 ease-out scale-100 hover:scale-105">
                 <QuoteIcon className="w-80 h-80 text-stone-900" fill="currentColor" />
              </div>
           )}
           {gameMode === 'HARDCORE' && (
              <div className="absolute -top-12 -left-12 opacity-[0.03] transform -rotate-12 transition-all duration-700 ease-out scale-100 hover:scale-105">
                 <Skull className="w-80 h-80 text-stone-100" />
              </div>
           )}
           {gameMode === 'FIX_MISTAKE' && (
              <div className="absolute -top-12 -left-12 opacity-[0.03] transform -rotate-12 transition-all duration-700 ease-out scale-100 hover:scale-105">
                 <Eraser className="w-80 h-80 text-red-900" />
              </div>
           )}
        </div>

        <div className="absolute top-10 left-0 right-0 px-20 flex justify-between text-xs font-bold opacity-80 uppercase tracking-[0.2em] select-none font-sans z-10 text-stone-500">
          <div className="flex gap-4">
             <span>{quote.source}</span>
             {settings.ghostEnabled && <span className="text-purple-300 flex items-center gap-1"><Ghost className="w-3.5 h-3.5"/> {ghostWpm > 0 ? `${ghostWpm} WPM` : 'Ready'}</span>}
             {settings.readAheadLevel !== 'NONE' && <span className="text-frog-green flex items-center gap-1"><EyeOff className="w-3.5 h-3.5"/> {settings.readAheadLevel}</span>}
          </div>
          <span>{quote.author}</span>
        </div>

        {/* Text Container with Caret and Dynamic Font */}
        <div 
          ref={textContainerRef}
          className={`font-mono tracking-wide break-words whitespace-pre-wrap mb-12 mt-10 relative z-10 outline-none select-none ${getTextColor()} ${getFontSizeClass()}`}
          onClick={handleFocus}
        >
          {/* Smooth Caret with Frog Green - Animation Disabled */}
          <div 
             className="absolute bg-frog-green w-[3px] rounded-full transition-all duration-100 ease-out z-20 pointer-events-none caret-blink shadow-[0_0_10px_rgba(64,214,114,0.5)]"
             style={{ 
                 left: caretPos.left - 1, 
                 top: caretPos.top + 2, 
                 height: caretPos.height - 4,
                 opacity: caretPos.opacity
             }}
          />
          {renderText()}
        </div>

        <textarea
          ref={inputRef}
          value={input}
          onChange={handleChange}
          onBlur={handleBlur}
          onFocus={() => {
              setIsFocused(true);
              onInteract?.();
          }}
          className="absolute opacity-0 top-0 left-0 h-full w-full cursor-default resize-none"
          autoFocus={isFocused}
          disabled={status === GameStatus.COMPLETED || status === GameStatus.FAILED}
        />

        <div className="absolute bottom-10 left-0 right-0 px-20 flex justify-between items-end select-none z-10">
           <div className="flex items-center gap-10 text-stone-400 font-mono text-sm">
             <div className="flex flex-col">
                <span className="text-[10px] uppercase font-bold text-stone-300 mb-0.5 tracking-wider">Speed</span>
                <span className="font-bold text-xl opacity-80 font-sans">{wpm} <span className="text-[10px] font-normal opacity-50">WPM</span></span>
             </div>
             {streak > 0 && (
                <div className={`flex flex-col ${streak > 4 ? 'text-orange-500' : 'text-stone-400'}`}>
                    <span className="text-[10px] uppercase font-bold text-stone-300 mb-0.5 tracking-wider">Streak</span>
                    <span className="font-bold text-xl flex items-center gap-1.5 font-sans">
                        <Flame className={`w-4 h-4 ${streak > 4 ? 'fill-orange-500' : ''}`} /> {streak}
                    </span>
                </div>
             )}
           </div>

           <div>
              {status === GameStatus.FAILED && (
                <button 
                  ref={retryButtonRef}
                  onClick={handleRetry}
                  className="flex items-center gap-2 px-6 py-2.5 bg-red-50 text-red-500 rounded-full hover:bg-red-100 transition font-bold text-sm tracking-wide uppercase focus:outline-none focus:ring-2 focus:ring-red-400 focus:ring-offset-2"
                >
                  <RotateCcw className="w-4 h-4" /> Retry
                </button>
              )}
              {status === GameStatus.COMPLETED && (
                <button 
                  ref={nextButtonRef}
                  onClick={handleNext}
                  className={`flex items-center gap-2 px-6 py-2.5 rounded-full transition shadow-lg font-bold text-sm tracking-wide uppercase transform hover:-translate-y-0.5 focus:outline-none focus:ring-2 focus:ring-offset-2
                    bg-frog-green text-white hover:bg-green-500 shadow-green-200/50 focus:ring-frog-green
                  `}
                >
                   Next Quote <Award className="w-4 h-4" />
                </button>
              )}
           </div>
        </div>
      </div>

      <div className="text-center mt-8 h-4 text-stone-400 text-xs font-medium tracking-wide transition-opacity duration-500 font-sans">
        {status === GameStatus.FAILED ? 
            <span className="text-red-400">
                {gameMode === 'HARDCORE' 
                  ? 'HARDCORE FAIL. 50% XP Penalty.' 
                  : 'Mistake made. Restart required.'}
            </span> : 
         status === GameStatus.COMPLETED ? <span className="text-frog-green">Perfect! Streak +1 {retryCount === 0 && sessionMistakes === 0 && "(Mastery Bonus!)"}</span> :
         isFocused ? "Accuracy is paramount. One mistake restarts the quote." : ""}
      </div>
    </div>
  );
};

export default TypingArea;

import React, { useState, useEffect, useRef } from 'react';
import { MusicConfig, MusicSource, Settings } from '../types';
import { getCurrentLevel } from '../utils/gameLogic';
import { RADIO_STATIONS } from '../data/radioStations';
import { X, Music, Disc, Youtube, Radio, Sparkles, Wind, Waves, Guitar, Drum, Rocket, Volume2, Power, AudioWaveform, Lock } from 'lucide-react';

interface MusicPlayerProps {
  isOpen: boolean;
  onClose: () => void;
  settings: Settings;
  setSettings: (s: Settings) => void;
  userXP: number;
}

const TIER_ORDER = ['Egg', 'Tadpole', 'Polliwog', 'Froglet', 'Hopper', 'Tree Frog', 'Bullfrog', 'Frog Sage'];

const BACKGROUND_PRESETS = [
    { id: 'PIANO_BEETHOVEN', name: 'Moonlight Piano', icon: <Music className="w-4 h-4 text-purple-500" /> },
    { id: 'PIANO_SATIE', name: 'Satie (Gymnopédie)', icon: <Music className="w-4 h-4 text-purple-400" /> },
    { id: 'PIANO_JAZZ', name: 'Jazz Lounge', icon: <Music className="w-4 h-4 text-orange-400" /> },
    { id: 'GUITAR', name: 'Acoustic Guitar', icon: <Guitar className="w-4 h-4 text-amber-500" /> },
    { id: 'ZEN', name: 'Zen Bells', icon: <Wind className="w-4 h-4 text-teal-500" /> },
    { id: 'BROWN_NOISE', name: 'Brown Noise', icon: <Waves className="w-4 h-4 text-stone-500" /> },
    { id: 'DRUMS_HARDCORE', name: 'Hardcore Breakbeat', icon: <Drum className="w-4 h-4 text-red-600" /> },
    { id: 'SYNTH_COSMIC', name: 'Cosmic Synth', icon: <Rocket className="w-4 h-4 text-indigo-500" /> }
];

export const MusicPlayer: React.FC<MusicPlayerProps> = ({ isOpen, onClose, settings, setSettings, userXP }) => {
  const [activeTab, setActiveTab] = useState<'BACKGROUND' | 'RADIO'>('BACKGROUND');
  const { musicConfig } = settings;
  const containerRef = useRef<HTMLDivElement>(null);

  const currentLevel = getCurrentLevel(userXP);
  const currentTierIndex = TIER_ORDER.indexOf(currentLevel.tier);

  // Close when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (isOpen && containerRef.current && !containerRef.current.contains(event.target as Node)) {
        onClose();
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [isOpen, onClose]);

  const handlePlay = (source: MusicSource, id: string) => {
    setSettings({
      ...settings,
      musicConfig: { source, presetId: id }
    });
  };

  const handleStop = () => {
    setSettings({
      ...settings,
      musicConfig: { source: 'NONE', presetId: '' }
    });
  };

  const handleAmbientVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSettings({ ...settings, ambientVolume: parseFloat(e.target.value) });
  };

  const isStationLocked = (tier: string) => {
    const requiredIndex = TIER_ORDER.indexOf(tier);
    return currentTierIndex < requiredIndex;
  };

  // The actual player render (Persists even when UI is closed)
  const renderEmbed = () => {
    if (musicConfig.source === 'NONE') return null;

    if (musicConfig.source === 'YOUTUBE') {
      return (
        <div className="w-full aspect-video bg-black rounded-lg overflow-hidden relative group shadow-inner">
           <iframe 
             width="100%" 
             height="100%" 
             src={`https://utube.realityripple.com/#${musicConfig.presetId}`} 
             title="YouTube music player" 
             frameBorder="0" 
             allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" 
             allowFullScreen
             className="opacity-90 hover:opacity-100 transition-opacity"
           ></iframe>
        </div>
      );
    }

    if (musicConfig.source === 'SPOTIFY') {
      return (
        <iframe 
          style={{ borderRadius: '12px' }} 
          src={`https://open.spotify.com/embed/playlist/${musicConfig.presetId}`} 
          width="100%" 
          height="152" 
          frameBorder="0" 
          allowFullScreen 
          allow="autoplay; clipboard-write; encrypted-media; fullscreen; picture-in-picture" 
          loading="lazy"
          className="shadow-sm"
        ></iframe>
      );
    }

    if (musicConfig.source === 'SUNO') {
      return (
        <div className="rounded-xl overflow-hidden shadow-sm border border-stone-200">
           <iframe 
             src={`https://suno.com/embed/playlist/${musicConfig.presetId}`}
             width="100%" 
             height="380" 
             frameBorder="0" 
             allow="clipboard-write; autoplay"
           ></iframe>
        </div>
      );
    }

    if (musicConfig.source === 'GENERATED') {
       // Visualizer for Generated Audio
       const info = BACKGROUND_PRESETS.find(p => p.id === musicConfig.presetId);
       return (
         <div className="w-full h-32 bg-stone-900 rounded-xl flex flex-col items-center justify-center relative overflow-hidden shadow-inner ring-1 ring-stone-800">
            {/* Simple CSS animation for visualizer */}
            <div className="absolute inset-0 opacity-20 flex items-end justify-center gap-1 pb-2">
                {[...Array(20)].map((_, i) => (
                    <div 
                      key={i} 
                      className="w-1.5 bg-frog-green rounded-t-sm animate-pulse" 
                      style={{ 
                          height: `${20 + Math.random() * 60}%`,
                          animationDuration: `${0.3 + Math.random() * 0.7}s`
                      }} 
                    />
                ))}
            </div>
            <div className="z-10 text-white font-bold flex flex-col items-center gap-2">
                <div className="p-2 bg-stone-800 rounded-full shadow-xl border border-stone-700">
                    {info?.icon || <Sparkles className="w-5 h-5 text-yellow-400" />}
                </div>
                <span className="text-xs tracking-wide font-mono">{info?.name}</span>
            </div>
            <div className="absolute top-2 right-2 text-[8px] text-frog-green font-black uppercase tracking-widest bg-stone-800 px-1.5 py-0.5 rounded border border-stone-700/50">
               Live Engine
            </div>
         </div>
       );
    }
  };

  // If closed and not playing, don't render anything
  if (!isOpen && musicConfig.source === 'NONE') return null;

  return (
    <div className={`fixed bottom-6 right-6 z-50 transition-all duration-300 ${isOpen ? 'translate-y-0 opacity-100' : 'translate-y-10 opacity-0 pointer-events-none'}`}>
      <div ref={containerRef} className="bg-white rounded-2xl shadow-2xl shadow-stone-300/50 w-96 max-w-[calc(100vw-3rem)] border border-stone-100 overflow-hidden flex flex-col">

        {/* Header */}
        <div className="flex items-center justify-between p-4 bg-white border-b border-stone-100">
           <div className="flex items-center gap-2 text-stone-700 font-bold">
             <Radio className="w-4 h-4 text-frog-green" />
             <span className="text-sm">Background Audio</span>
           </div>
           <button onClick={onClose} className="text-stone-400 hover:text-stone-600">
             <X className="w-4 h-4" />
           </button>
        </div>

        {/* Content */}
        <div className="p-4 bg-stone-50/50">

          {/* Active Player Area */}
          <div className={`transition-all duration-300 ${musicConfig.source === 'NONE' ? 'h-0 overflow-hidden opacity-0' : 'h-auto min-h-[100px] mb-4 opacity-100'}`}>
             {renderEmbed()}

             <button 
               onClick={handleStop} 
               className="mt-3 w-full flex items-center justify-center gap-2 py-2 text-xs text-red-500 font-bold bg-red-50 hover:bg-red-100 rounded-lg transition-colors"
             >
               <Power className="w-3.5 h-3.5" /> Disable Music
             </button>
          </div>

          {/* Source Tabs */}
          <div className="flex p-1 bg-stone-200/50 rounded-lg mb-4 gap-0.5">
            <button 
              onClick={() => setActiveTab('BACKGROUND')}
              className={`flex-1 flex items-center justify-center gap-1 py-2 text-[10px] font-bold rounded-md transition-all ${activeTab === 'BACKGROUND' ? 'bg-white text-frog-green shadow-sm' : 'text-stone-500 hover:text-stone-700'}`}
              title="Generated Sounds"
            >
              <Sparkles className="w-3 h-3" /> Background
            </button>
            <button 
              onClick={() => setActiveTab('RADIO')}
              className={`flex-1 flex items-center justify-center gap-1 py-2 text-[10px] font-bold rounded-md transition-all 
                ${activeTab === 'RADIO' ? 'bg-white text-frog-green shadow-sm' : 'text-stone-500 hover:text-stone-700'}
              `}
              title="Streaming Radio"
            >
              <Radio className="w-3 h-3" /> Radio
            </button>
          </div>

          {/* Volume Control - Visible when in Background tab */}
          {activeTab === 'BACKGROUND' && (
            <div className="mb-4 px-3 py-3 bg-white rounded-xl border border-stone-100 shadow-sm animate-in slide-in-from-top-2 fade-in duration-300">
               <div className="flex justify-between text-[10px] text-stone-400 font-bold mb-2 uppercase tracking-wide">
                  <span className="flex items-center gap-1.5 text-stone-500"><Volume2 className="w-3.5 h-3.5"/> Music Volume</span>
                  <span>{Math.round(settings.ambientVolume * 100)}%</span>
               </div>
               <input 
                 type="range" 
                 min="0" 
                 max="1" 
                 step="0.01" 
                 value={settings.ambientVolume}
                 onChange={handleAmbientVolumeChange}
                 className="w-full h-1.5 bg-stone-100 rounded-lg appearance-none cursor-pointer accent-frog-green hover:accent-green-500"
               />
            </div>
          )}

          {/* Preset List */}
          <div className="space-y-1.5 max-h-48 overflow-y-auto pr-1 custom-scrollbar">
             {activeTab === 'BACKGROUND' && BACKGROUND_PRESETS.map((preset) => (
               <button
                 key={preset.id}
                 onClick={() => handlePlay('GENERATED', preset.id)}
                 className={`w-full text-left px-3 py-2 rounded-lg text-xs font-bold transition-all flex items-center justify-between group
                   ${musicConfig.source === 'GENERATED' && musicConfig.presetId === preset.id 
                     ? 'bg-green-50 text-frog-green border border-green-100' 
                     : 'bg-white hover:bg-stone-50 text-stone-600 border border-transparent hover:border-stone-200'
                   }`}
               >
                 <div className="flex items-center gap-2">
                    {preset.icon && <span className="opacity-70">{preset.icon}</span>}
                    <span className="truncate">{preset.name}</span>
                 </div>
                 {musicConfig.source === 'GENERATED' && musicConfig.presetId === preset.id && (
                   <div className="flex space-x-[2px] items-end h-3">
                     <div className="w-[2px] bg-frog-green h-1 animate-[bounce_1s_infinite]" />
                     <div className="w-[2px] bg-frog-green h-2 animate-[bounce_1.2s_infinite]" />
                     <div className="w-[2px] bg-frog-green h-3 animate-[bounce_0.8s_infinite]" />
                   </div>
                 )}
               </button>
             ))}

             {activeTab === 'RADIO' && RADIO_STATIONS.map((preset) => {
               const locked = isStationLocked(preset.tier);

               return (
                 <button
                   key={preset.id}
                   onClick={() => !locked && handlePlay(preset.type, preset.id)}
                   disabled={locked}
                   className={`w-full text-left px-3 py-2 rounded-lg text-xs font-bold transition-all flex items-center justify-between group
                     ${locked
                       ? 'bg-stone-50 text-stone-400 opacity-60 cursor-not-allowed border border-transparent'
                       : musicConfig.source === preset.type && musicConfig.presetId === preset.id 
                         ? 'bg-green-50 text-frog-green border border-green-100' 
                         : 'bg-white hover:bg-stone-50 text-stone-600 border border-transparent hover:border-stone-200'
                     }`}
                 >
                   <div className="flex items-center gap-2">
                      {locked ? <Lock className="w-3.5 h-3.5 opacity-50" /> : (
                         preset.type === 'YOUTUBE' ? <Youtube className="w-3.5 h-3.5 text-red-500 opacity-80" /> : 
                         preset.type === 'SUNO' ? <AudioWaveform className="w-3.5 h-3.5 text-stone-800 opacity-80" /> :
                         <Disc className="w-3.5 h-3.5 text-frog-green opacity-80" />
                      )}
                      <div className="flex flex-col">
                        <span className="truncate">{preset.name}</span>
                        {locked && <span className="text-[9px] text-stone-400 font-normal uppercase tracking-wide">Unlocks at {preset.tier}</span>}
                      </div>
                   </div>
                   {!locked && musicConfig.source === preset.type && musicConfig.presetId === preset.id && (
                     <div className="flex space-x-[2px] items-end h-3">
                       <div className="w-[2px] bg-frog-green h-1 animate-[bounce_1s_infinite]" />
                       <div className="w-[2px] bg-frog-green h-2 animate-[bounce_1.2s_infinite]" />
                       <div className="w-[2px] bg-frog-green h-3 animate-[bounce_0.8s_infinite]" />
                     </div>
                   )}
                 </button>
               );
             })}
          </div>

        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useCallback, useLayoutEffect, useRef } from 'react';
import ProgressBar from './components/ProgressBar';
import TypingArea from './components/TypingArea';
import SettingsModal from './components/SettingsModal';
import HelpModal from './components/HelpModal';
import StatsModal from './components/StatsModal';
import ThemeModal from './components/ThemeModal';
import AchievementsModal from './components/AchievementsModal';
import AchievementToast from './components/AchievementToast';
import { MusicPlayer } from './components/MusicPlayer';
import { Quote, Settings, GameMode, TestResult, NotificationItem, ReadAheadLevel } from './types';
import { fetchQuotes } from './services/quoteService';
import { getCurrentLevel, getNextLevel, getAverageWPM, LEVELS, calculateXP, checkLevelProgress } from './utils/gameLogic';
import { soundEngine } from './utils/soundEngine';
import { Loader2, Settings as SettingsIcon, Music, CircleHelp, Skull, BookOpen, Eraser, TrendingUp, Palette, Award, Radio, Lock, Eye, EyeOff, Flame, AlertTriangle, ArrowRight } from 'lucide-react';
import confetti from 'canvas-confetti';
import { THEMES } from './data/themes';
import { ACHIEVEMENTS } from './data/achievements';
import { RADIO_STATIONS } from './data/radioStations';

const App: React.FC = () => {
  // User Stats Persistence
  const [userName, setUserName] = useState<string>(() => {
      return localStorage.getItem('frogType_userName') || 'Froggy';
  });

  const [joinDate, setJoinDate] = useState<string>(() => {
      const stored = localStorage.getItem('frogType_joinDate');
      if (stored) return stored;
      const now = new Date().toISOString();
      localStorage.setItem('frogType_joinDate', now);
      return now;
  });

  const [totalTimePlayed, setTotalTimePlayed] = useState<number>(() => {
      const stored = localStorage.getItem('frogType_totalTime');
      return stored ? parseInt(stored, 10) : 0;
  });

  const [userXP, setUserXP] = useState<number>(() => {
    const saved = localStorage.getItem('frogXP');
    const legacy = localStorage.getItem('frogType_xp');
    if (saved) return parseInt(saved, 10);
    if (legacy) return parseInt(legacy, 10);
    return 0;
  });

  const currentLevel = getCurrentLevel(userXP);

  // Track unlocked tiers persistently to prevent repeat notifications
  const [unlockedTiers, setUnlockedTiers] = useState<string[]>(() => {
    const saved = localStorage.getItem('frogType_unlockedTiers');
    return saved ? JSON.parse(saved) : [];
  });

  // Session Streak (Consecutive Quotes)
  const [streak, setStreak] = useState<number>(() => {
    const saved = localStorage.getItem('frogType_streak');
    return saved ? parseInt(saved, 10) : 0;
  });

  // Daily Streak Logic
  const [dailyStreak, setDailyStreak] = useState<number>(() => {
     const saved = localStorage.getItem('frogType_dailyStreak');
     return saved ? parseInt(saved, 10) : 0;
  });

  const [unlockedAchievements, setUnlockedAchievements] = useState<string[]>(() => {
    const saved = localStorage.getItem('frogType_achievements');
    return saved ? JSON.parse(saved) : [];
  });

  const [notificationQueue, setNotificationQueue] = useState<NotificationItem[]>([]);

  // Track history for average WPM calculation (Last 10)
  const [wpmHistory, setWpmHistory] = useState<number[]>(() => {
    const saved = localStorage.getItem('frogType_wpmHistory');
    return saved ? JSON.parse(saved) : [];
  });

  // Track full history of tests
  const [testHistory, setTestHistory] = useState<TestResult[]>(() => {
    const saved = localStorage.getItem('frogType_history');
    return saved ? JSON.parse(saved) : [];
  });

  const [lastWpm, setLastWpm] = useState<number>(() => {
    const saved = localStorage.getItem('frogType_lastWpm');
    return saved ? parseInt(saved, 10) : 0;
  });

  const [mistakePool, setMistakePool] = useState<string[]>(() => {
    const saved = localStorage.getItem('frogType_mistakes');
    return saved ? JSON.parse(saved) : [];
  });

  const [settings, setSettings] = useState<Settings>(() => {
    const saved = localStorage.getItem('frogType_settings');

    if (!saved) {
      return { 
        ghostEnabled: false, 
        readAheadLevel: 'NONE', 
        sfxEnabled: true,
        mechanicalSoundEnabled: false,
        mechanicalSoundPreset: 'THOCK',
        ambientVolume: 0.02, 
        musicConfig: { source: 'GENERATED', presetId: 'PIANO_SATIE' },
        themeId: 'CLASSIC'
      };
    }

    const parsed = JSON.parse(saved);
    const legacyBrownNoiseEnabled = parsed.brownNoiseEnabled === true;
    const legacyVolume = parsed.brownNoiseVolume ?? 0.5;

    // Migration for legacy boolean readAhead
    let initialReadAhead = parsed.readAheadLevel;
    if (parsed.readAheadEnabled === true && !initialReadAhead) initialReadAhead = 'FOCUS';
    if (!initialReadAhead) initialReadAhead = 'NONE';

    let initialMusicConfig = parsed.musicConfig || { source: 'NONE', presetId: '' };
    if (legacyBrownNoiseEnabled && initialMusicConfig.source === 'NONE') {
        initialMusicConfig = { source: 'GENERATED', presetId: 'BROWN_NOISE' };
    }

    return { 
      ghostEnabled: false, 
      readAheadLevel: initialReadAhead, 
      sfxEnabled: true,
      mechanicalSoundEnabled: parsed.mechanicalSoundEnabled ?? false,
      mechanicalSoundPreset: parsed.mechanicalSoundPreset || 'THOCK',
      ambientVolume: parsed.ambientVolume ?? legacyVolume, 
      musicConfig: initialMusicConfig,
      themeId: parsed.themeId || 'CLASSIC',
      ...parsed
    };
  });

  const [gameMode, setGameMode] = useState<GameMode>(() => {
    const saved = localStorage.getItem('frogType_gameMode');
    return (saved as GameMode) || 'QUOTES';
  });

  const [completedQuotes, setCompletedQuotes] = useState<string[]>(() => {
    const saved = localStorage.getItem('frogType_completedQuotes');
    return saved ? JSON.parse(saved) : [];
  });

  const [quotesQueue, setQuotesQueue] = useState<Quote[]>([]);

  const [currentQuote, setCurrentQuote] = useState<Quote | null>(() => {
    const saved = localStorage.getItem('frogType_currentQuote');
    return saved ? JSON.parse(saved) : null;
  });

  const [loading, setLoading] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isMusicOpen, setIsMusicOpen] = useState(false);
  const [isHelpOpen, setIsHelpOpen] = useState(false);
  const [isStatsOpen, setIsStatsOpen] = useState(false);
  const [isThemeOpen, setIsThemeOpen] = useState(false);
  const [isAchievementsOpen, setIsAchievementsOpen] = useState(false);

  // Start time tracking for current quote
  const [quoteStartTime, setQuoteStartTime] = useState<number | null>(null);

  const isFetchingRef = useRef(false);

  // Derive Lock State
  const uniqueTiers = Array.from(new Set(LEVELS.map(l => l.tier)));
  const currentTierIndex = uniqueTiers.indexOf(currentLevel.tier);
  const polliwogIndex = uniqueTiers.indexOf('Polliwog');
  const isHardcoreLocked = currentTierIndex < polliwogIndex;

  // Gating Check
  const avgWpmVal = getAverageWPM(wpmHistory);
  const { isGated, reason } = checkLevelProgress(userXP, avgWpmVal, mistakePool.length);

  // Persistence
  useEffect(() => { localStorage.setItem('frogXP', userXP.toString()); }, [userXP]);
  useEffect(() => { localStorage.setItem('frogType_unlockedTiers', JSON.stringify(unlockedTiers)); }, [unlockedTiers]);
  useEffect(() => { localStorage.setItem('frogType_streak', streak.toString()); }, [streak]);
  useEffect(() => { localStorage.setItem('frogType_dailyStreak', dailyStreak.toString()); }, [dailyStreak]);
  useEffect(() => { localStorage.setItem('frogType_lastWpm', lastWpm.toString()); }, [lastWpm]);
  useEffect(() => { localStorage.setItem('frogType_wpmHistory', JSON.stringify(wpmHistory)); }, [wpmHistory]);
  useEffect(() => { localStorage.setItem('frogType_history', JSON.stringify(testHistory)); }, [testHistory]);
  useEffect(() => { localStorage.setItem('frogType_settings', JSON.stringify(settings)); }, [settings]);
  useEffect(() => { localStorage.setItem('frogType_mistakes', JSON.stringify(mistakePool)); }, [mistakePool]);
  useEffect(() => { localStorage.setItem('frogType_userName', userName); }, [userName]);
  useEffect(() => { localStorage.setItem('frogType_totalTime', totalTimePlayed.toString()); }, [totalTimePlayed]);

  // Game Mode Persistence & Lock Check
  useEffect(() => { 
      if (gameMode === 'HARDCORE' && isHardcoreLocked) {
          setGameMode('QUOTES');
      }
      localStorage.setItem('frogType_gameMode', gameMode); 
  }, [gameMode, isHardcoreLocked]);

  useEffect(() => { localStorage.setItem('frogType_completedQuotes', JSON.stringify(completedQuotes)); }, [completedQuotes]);
  useEffect(() => { localStorage.setItem('frogType_achievements', JSON.stringify(unlockedAchievements)); }, [unlockedAchievements]);

  // Audio Settings Sync
  useEffect(() => {
    soundEngine.setEnabled(settings.sfxEnabled);
    soundEngine.setMechanicalEnabled(settings.mechanicalSoundEnabled);
    soundEngine.setMechanicalPreset(settings.mechanicalSoundPreset);
    soundEngine.setAmbientVolume(settings.ambientVolume);

    if (settings.musicConfig.source === 'GENERATED') {
      soundEngine.setAmbientMusic(settings.musicConfig.presetId);
    } else {
      soundEngine.stopAmbientMusic();
    }
  }, [settings.sfxEnabled, settings.mechanicalSoundEnabled, settings.mechanicalSoundPreset, settings.ambientVolume, settings.musicConfig]);

  useLayoutEffect(() => {
    const theme = THEMES.find(t => t.id === settings.themeId) || THEMES[0];
    const root = document.documentElement;
    root.style.setProperty('--bg-body', theme.colors.background);
    Object.entries(theme.colors.frog).forEach(([key, value]) => {
       root.style.setProperty(`--frog-${key}`, value);
    });
    Object.entries(theme.colors.stone).forEach(([key, value]) => {
       root.style.setProperty(`--stone-${key}`, value);
    });
    root.style.setProperty('--text-body', theme.colors.stone[800]);
  }, [settings.themeId]);

  useEffect(() => {
    const handleInteraction = () => {
      soundEngine.resumeContext();
      window.removeEventListener('click', handleInteraction);
      window.removeEventListener('keydown', handleInteraction);
    };

    window.addEventListener('click', handleInteraction);
    window.addEventListener('keydown', handleInteraction);
    return () => {
      window.removeEventListener('click', handleInteraction);
      window.removeEventListener('keydown', handleInteraction);
    };
  }, []);

  useEffect(() => { 
    if (currentQuote) {
      localStorage.setItem('frogType_currentQuote', JSON.stringify(currentQuote)); 
      setQuoteStartTime(Date.now());
    } else {
      localStorage.removeItem('frogType_currentQuote');
    }
  }, [currentQuote]);

  // Check Daily Streak on Mount
  useEffect(() => {
      const today = new Date().toDateString();
      const lastVisit = localStorage.getItem('frogType_lastVisitDate');

      // If user hasn't visited today, check if streak should break
      if (lastVisit && lastVisit !== today) {
          const yesterday = new Date();
          yesterday.setDate(yesterday.getDate() - 1);

          if (yesterday.toDateString() !== lastVisit) {
              // Streak broken if last visit was not yesterday
              setDailyStreak(0);
          }
      } else if (!lastVisit) {
          setDailyStreak(0);
      }
  }, []);

  const updateDailyStreakActivity = () => {
      const today = new Date().toDateString();
      const lastVisit = localStorage.getItem('frogType_lastVisitDate');

      if (lastVisit !== today) {
          // New day activity
          let newStreak = 1;
          if (lastVisit) {
              const yesterday = new Date();
              yesterday.setDate(yesterday.getDate() - 1);
              if (yesterday.toDateString() === lastVisit) {
                  newStreak = dailyStreak + 1;
              }
          }
          setDailyStreak(newStreak);
          localStorage.setItem('frogType_lastVisitDate', today);

          // Toast for streak
          setNotificationQueue(prev => [...prev, {
              id: `daily_${Date.now()}`,
              title: "Daily Streak!",
              description: `You're on a ${newStreak} day streak.`,
              icon: <Flame className="w-5 h-5 text-orange-500" />,
              type: "INFO"
          }]);
      } else {
          // Already played today, ensure streak is at least 1 if it was 0
          if (dailyStreak === 0) {
              setDailyStreak(1);
              localStorage.setItem('frogType_lastVisitDate', today);
          }
      }
  };

  const generateMistakeQuote = useCallback((): Quote | null => {
    if (mistakePool.length === 0) return null;
    let pool = [...mistakePool];
    while (pool.length < 15) {
       pool = [...pool, ...mistakePool];
    }
    const shuffled = pool.sort(() => 0.5 - Math.random());
    const selected = shuffled.slice(0, 15);
    const text = selected.join(' ');

    return {
      text,
      source: "Personal Training",
      author: "Your Mistakes"
    };
  }, [mistakePool]);

  const loadMoreQuotes = useCallback(async () => {
    if (isFetchingRef.current) return;

    isFetchingRef.current = true;

    try {
      const level = getCurrentLevel(userXP);
      // IMPORTANT: Pass completedQuotes to filter them out forever
      const newQuotes = await fetchQuotes(5, completedQuotes, level.tier, gameMode);
      setQuotesQueue(prev => [...prev, ...newQuotes]);
    } catch (error) {
      console.error("Failed to load quotes", error);
    } finally {
      isFetchingRef.current = false;
    }
  }, [completedQuotes, userXP, gameMode]);

  useEffect(() => {
    const init = async () => {
      if (!currentQuote && quotesQueue.length === 0) {
         setLoading(true);
         await loadMoreQuotes();
         setLoading(false);
      } else if (quotesQueue.length < 3) {
         loadMoreQuotes();
      }
    };
    init();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (currentQuote) return;

    if (gameMode === 'FIX_MISTAKE') {
      const mistakeQuote = generateMistakeQuote();
      if (mistakeQuote) {
        setCurrentQuote(mistakeQuote);
      } else {
        setGameMode('QUOTES'); 
      }
    } else {
      if (quotesQueue.length > 0) {
        const next = quotesQueue[0];
        setCurrentQuote(next);
        setQuotesQueue(prev => prev.slice(1));
      }

      if (quotesQueue.length < 3) {
        loadMoreQuotes();
      }
    }
  }, [currentQuote, quotesQueue, gameMode, generateMistakeQuote, loadMoreQuotes]);

  const checkAchievements = (wpm: number) => {
    const newNotifications: NotificationItem[] = [];
    const newUnlockIds: string[] = [];

    const stats = {
       wpm,
       totalQuotes: completedQuotes.length + 1, 
       maxStreak: Math.max(streak + 1, streak + 1),
       currentStreak: streak + 1,
       mode: gameMode
    };

    ACHIEVEMENTS.forEach(ach => {
       if (!unlockedAchievements.includes(ach.id)) {
           if (ach.condition(stats)) {
               newUnlockIds.push(ach.id);
               newNotifications.push({
                   id: ach.id,
                   title: ach.title,
                   description: ach.description,
                   icon: ach.icon,
                   type: 'ACHIEVEMENT'
               });
           }
       }
    });

    if (newUnlockIds.length > 0) {
       setUnlockedAchievements(prev => [...prev, ...newUnlockIds]);
       setNotificationQueue(prev => [...prev, ...newNotifications]);
       soundEngine.playLevelUp(); 
    }
  };

  const handleQuoteComplete = (xpCalc: number, wpm: number, mistakes: string[], retryCount: number) => {
    // Recalculate with Read Ahead Bonus (if any changed since TypingArea)
    // Actually simpler to pass raw WPM/Length and recalc here or trust TypingArea passed value.
    // TypingArea uses calculateXP so it already includes ReadAhead bonus from settings passed to it.
    let finalXp = xpCalc; 

    // Update Time Played
    if (quoteStartTime) {
        const durationSec = Math.floor((Date.now() - quoteStartTime) / 1000);
        setTotalTimePlayed(prev => prev + durationSec);
    }

    if (gameMode === 'HARDCORE') {
      finalXp = finalXp * 5;
    }

    // Fix Mistake Mode Logic
    if (gameMode === 'FIX_MISTAKE' && currentQuote) {
      const wordsFixed = [...new Set(currentQuote.text.split(' '))]; 
      setMistakePool(prev => prev.filter(word => !wordsFixed.includes(word)));
    }

    // Mark quote as completed so it never shows again (if in standard modes)
    if (currentQuote && gameMode !== 'FIX_MISTAKE') {
       setCompletedQuotes(prev => [...prev, currentQuote.text]);
    }

    // Update History
    const newHistory = [...wpmHistory, wpm].slice(-10); 
    setWpmHistory(newHistory);
    const avgWpm = getAverageWPM(newHistory);

    const newTestResult: TestResult = {
      id: Date.now(),
      date: new Date().toISOString(),
      wpm,
      xpEarned: finalXp,
      mode: gameMode,
      quoteText: currentQuote?.text || "",
      mistakes: mistakes,
      retryCount: retryCount
    };
    setTestHistory(prev => [...prev, newTestResult]);

    checkAchievements(wpm);

    // Calculate XP and Handle Gates/Unlocks
    const currentLevelObj = getCurrentLevel(userXP);
    const nextLevelObj = getNextLevel(currentLevelObj);
    let potentialXp = userXP + finalXp;

    if (nextLevelObj && potentialXp >= nextLevelObj.minXP) {
         let effectiveMistakeCount = mistakePool.length;
         if (gameMode === 'FIX_MISTAKE' && currentQuote) {
             const wordsFixed = [...new Set(currentQuote.text.split(' '))];
             effectiveMistakeCount = mistakePool.filter(word => !wordsFixed.includes(word)).length;
         }

         const isMasteryGated = effectiveMistakeCount > 0;
         const isSpeedGated = avgWpm < nextLevelObj.requiredWpm;

         if (isMasteryGated || isSpeedGated) {
            potentialXp = nextLevelObj.minXP - 1; 
         }
    }

    const newLevel = getCurrentLevel(potentialXp);

    // Check for Tier Unlocks (Persistent - Only once per tier)
    if (!unlockedTiers.includes(newLevel.tier)) {
         setUnlockedTiers(prev => [...prev, newLevel.tier]);

         const newStations = RADIO_STATIONS.filter(s => s.tier === newLevel.tier);

         if (newStations.length > 0) {
             const musicNotifications: NotificationItem[] = newStations.map(s => ({
                id: `unlock_${s.id}`,
                title: 'New Station Unlocked',
                description: s.name,
                icon: <Radio className="w-5 h-5 text-stone-900" />,
                type: 'UNLOCK'
             }));
             setNotificationQueue(prev => [...prev, ...musicNotifications]);
         }
    }

    const prevLevel = getCurrentLevel(userXP);
    if (newLevel.tier !== prevLevel.tier && potentialXp >= newLevel.minXP) {
          setTimeout(() => {
              confetti({
                particleCount: 200,
                spread: 120,
                origin: { y: 0.6 },
                colors: ['#40D672', '#22c55e', '#fbbf24', '#f59e0b'],
                startVelocity: 45
              });
              soundEngine.playLevelUp(); 
          }, 300);
    }

    setUserXP(potentialXp);
    setStreak(prev => prev + 1);

    // Update Daily Streak
    updateDailyStreakActivity();

    setLastWpm(wpm);
    setCurrentQuote(null); 
    setQuoteStartTime(null);
  };

  const handleQuoteFail = () => {
    setStreak(0);
  };

  const handleMistake = (word?: string) => {
    const penaltyMultiplier = gameMode === 'HARDCORE' ? 0.5 : 0.85;
    setUserXP(prev => Math.floor(prev * penaltyMultiplier));

    setStreak(0);

    if (word && word.length > 1) {
       setMistakePool(prev => {
         if (prev.includes(word)) return prev;
         return [...prev, word];
       });
    }
  };

  const handlePracticeFromHistory = (mistakes: string[]) => {
      setMistakePool(prev => {
          const newSet = new Set([...prev, ...mistakes]);
          return Array.from(newSet);
      });
      switchMode('FIX_MISTAKE');
  };

  const toggleSettings = () => setIsSettingsOpen(!isSettingsOpen);
  const toggleMusic = () => setIsMusicOpen(!isMusicOpen);
  const toggleHelp = () => setIsHelpOpen(!isHelpOpen);
  const toggleStats = () => setIsStatsOpen(!isStatsOpen);
  const toggleTheme = () => setIsThemeOpen(!isThemeOpen);
  const toggleAchievements = () => setIsAchievementsOpen(!isAchievementsOpen);

  const cycleReadAhead = () => {
      const levels: ReadAheadLevel[] = ['NONE', 'FOCUS', 'ULTRA', 'BLIND'];
      const currentIndex = levels.indexOf(settings.readAheadLevel);
      const nextIndex = (currentIndex + 1) % levels.length;
      setSettings({ ...settings, readAheadLevel: levels[nextIndex] });
      soundEngine.playKeypress(); // Feedback
  };

  const switchMode = (mode: GameMode) => {
    if (mode === 'FIX_MISTAKE' && mistakePool.length === 0) return;
    if (mode === 'HARDCORE' && isHardcoreLocked) return;
    setGameMode(mode);
    setQuotesQueue([]); 
    setCurrentQuote(null); 
  };

  const handleRequestNextQuote = async () => {
      setCurrentQuote(null);
      setQuoteStartTime(null);
  };

  const clearToast = useCallback(() => {
    setNotificationQueue(prev => prev.slice(1));
  }, []);

  // Helper for Read Ahead Icon/Color
  const getReadAheadConfig = () => {
      switch(settings.readAheadLevel) {
          case 'FOCUS': return { label: 'Focus', color: 'text-frog-green', bg: 'bg-frog-100', bonus: '+10%' };
          case 'ULTRA': return { label: 'Ultra', color: 'text-purple-600', bg: 'bg-purple-100', bonus: '+20%' };
          case 'BLIND': return { label: 'Blind', color: 'text-red-600', bg: 'bg-red-100', bonus: '+30%' };
          default: return { label: 'Off', color: 'text-stone-400', bg: 'hover:bg-stone-100', bonus: '' };
      }
  };
  const raConfig = getReadAheadConfig();

  return (
    <div className="min-h-screen flex flex-col bg-transparent text-stone-800 font-sans selection:bg-frog-200">
      <header className="w-full bg-stone-50/80 backdrop-blur-md border-b border-stone-200 sticky top-0 z-40 px-6 py-4 shadow-sm transition-all">
        <div className="max-w-[1400px] mx-auto flex flex-col xl:flex-row items-center justify-between gap-4 xl:gap-8">

          <div className="flex flex-col md:flex-row items-center gap-6 md:gap-8 w-full xl:w-auto">
            <div className="flex flex-col items-center md:items-start flex-shrink-0">
              <h1 className="text-xl font-black text-frog-green tracking-tight flex items-center gap-2">
                <span className="text-2xl">🐸</span> Frog Type
              </h1>
            </div>

            <div className="flex gap-1 p-1 bg-stone-100/80 rounded-lg shadow-inner border border-stone-200/50">
              <button 
                  onClick={() => switchMode('QUOTES')}
                  className={`px-3 py-1.5 rounded-md text-xs font-bold flex items-center gap-1.5 transition-all focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 ${gameMode === 'QUOTES' ? 'bg-white text-frog-green shadow-sm ring-1 ring-stone-200' : 'text-stone-400 hover:bg-stone-200/50 hover:text-stone-600'}`}
              >
                  <BookOpen className="w-3.5 h-3.5" /> Quotes
              </button>
              <button 
                  onClick={() => switchMode('HARDCORE')}
                  disabled={isHardcoreLocked}
                  title={isHardcoreLocked ? "Unlocks at Polliwog level" : "High risk, high reward"}
                  className={`px-3 py-1.5 rounded-md text-xs font-bold flex items-center gap-1.5 transition-all focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 
                    ${gameMode === 'HARDCORE' 
                      ? 'bg-stone-800 text-white shadow-sm ring-1 ring-stone-900' 
                      : isHardcoreLocked 
                          ? 'opacity-50 cursor-not-allowed text-stone-400 bg-stone-100' 
                          : 'text-stone-400 hover:bg-stone-200/50 hover:text-stone-600'}`}
              >
                  {isHardcoreLocked ? <Lock className="w-3.5 h-3.5" /> : <Skull className="w-3.5 h-3.5" />} 
                  Hardcore
              </button>
              <button 
                  onClick={() => switchMode('FIX_MISTAKE')}
                  disabled={mistakePool.length === 0}
                  className={`px-3 py-1.5 rounded-md text-xs font-bold flex items-center gap-1.5 transition-all focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 
                    ${gameMode === 'FIX_MISTAKE' ? 'bg-red-500 text-white shadow-sm ring-1 ring-red-600' : 'text-stone-400 hover:bg-stone-200/50 hover:text-stone-600'}
                    ${mistakePool.length === 0 ? 'opacity-50 cursor-not-allowed' : ''}
                    ${isGated && reason === 'MASTERY' && gameMode !== 'FIX_MISTAKE' ? 'ring-2 ring-red-500 bg-red-50 text-red-600 animate-pulse shadow-[0_0_10px_rgba(239,68,68,0.4)]' : ''}
                  `}
                  title={mistakePool.length === 0 ? "No mistakes recorded yet" : `${mistakePool.length} words to fix`}
              >
                  <Eraser className="w-3.5 h-3.5" /> Fix ({mistakePool.length})
              </button>
            </div>
          </div>

          <div className="w-full xl:w-auto xl:flex-grow xl:max-w-2xl flex items-center gap-4 justify-end">
             <ProgressBar 
               xp={userXP} 
               avgWpm={getAverageWPM(wpmHistory)} 
               mistakeCount={mistakePool.length} 
             />

             <div className="flex items-center gap-1.5 border-l border-stone-200 pl-4 ml-2 shrink-0">
               <button 
                 onClick={cycleReadAhead}
                 className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 group relative ${raConfig.bg} ${raConfig.color}`}
                 title={`Read Ahead: ${raConfig.label} (${raConfig.bonus ? raConfig.bonus + ' XP' : 'No Bonus'})`}
               >
                  {settings.readAheadLevel === 'NONE' ? <Eye className="w-5 h-5" /> : <EyeOff className="w-5 h-5" />}
                  {raConfig.bonus && (
                      <span className="absolute -top-1 -right-1 bg-frog-green text-white text-[8px] px-1 rounded-full font-bold">
                          {raConfig.bonus.replace('+','')}
                      </span>
                  )}
               </button>

               <button 
                 onClick={toggleAchievements} 
                 className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 ${isAchievementsOpen ? 'bg-stone-100 text-frog-green' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                 title="Achievements"
               >
                  <Award className="w-5 h-5" />
               </button>
               <button 
                 onClick={toggleTheme} 
                 className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 ${isThemeOpen ? 'bg-stone-100 text-frog-green' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                 title="Themes"
               >
                  <Palette className="w-5 h-5" />
               </button>
               <button 
                 onClick={toggleStats} 
                 className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 ${isStatsOpen ? 'bg-stone-100 text-frog-green' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                 title="Statistics & History"
               >
                  <TrendingUp className="w-5 h-5" />
               </button>
               <button 
                 onClick={toggleHelp} 
                 className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 ${isHelpOpen ? 'bg-stone-100 text-stone-700' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                 title="How to Play"
               >
                  <CircleHelp className="w-5 h-5" />
               </button>
               <button 
                 onClick={toggleMusic} 
                 className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 ${isMusicOpen || settings.musicConfig.source !== 'NONE' ? 'bg-stone-100 text-frog-green' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                 title="Background Music"
               >
                  <Music className="w-5 h-5" />
               </button>
               <button onClick={toggleSettings} className="p-2 hover:bg-stone-100 rounded-full text-stone-400 hover:text-stone-600 transition-colors focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2">
                  <SettingsIcon className="w-5 h-5" />
               </button>
             </div>
          </div>

        </div>
      </header>

      <main className="flex-grow flex flex-col items-center justify-center p-6 md:p-12 w-full relative">
        <div className="w-full flex flex-col items-center justify-center min-h-[60vh]">
          {isGated && reason === 'MASTERY' && gameMode !== 'FIX_MISTAKE' && (
              <button
                  onClick={() => switchMode('FIX_MISTAKE')}
                  className="mb-8 relative group overflow-hidden bg-red-500 hover:bg-red-600 text-white px-8 py-4 rounded-3xl shadow-xl shadow-red-200 flex items-center gap-5 transition-all transform hover:-translate-y-1 hover:shadow-2xl ring-4 ring-red-100 animate-bounce z-50"
              >
                  <div className="absolute inset-0 bg-white/10 skew-x-12 -translate-x-full group-hover:translate-x-full transition-transform duration-700"></div>
                  <div className="bg-white/20 p-3 rounded-full shadow-inner">
                      <AlertTriangle className="w-8 h-8 text-white fill-white/20" />
                  </div>
                  <div className="text-left">
                      <div className="font-black text-xl uppercase tracking-tight leading-none text-white">Level Gated!</div>
                      <div className="font-medium text-sm text-red-100 mt-1">
                          Fix <span className="font-black text-white border-b-2 border-red-300/50">{mistakePool.length} mistakes</span> to evolve
                      </div>
                  </div>
                  <div className="bg-white text-red-600 p-2.5 rounded-full shadow-lg ml-2 group-hover:scale-110 transition-transform">
                      <ArrowRight className="w-6 h-6" />
                  </div>
              </button>
          )}

          {loading && !currentQuote ? (
            <div className="flex flex-col items-center justify-center text-stone-400 animate-pulse">
              <Loader2 className="w-10 h-10 animate-spin mb-4 text-frog-green" />
              <p className="font-mono text-xs">
                  Hatching wisdom...
              </p>
            </div>
          ) : currentQuote ? (
            <TypingArea 
              quote={currentQuote} 
              onComplete={handleQuoteComplete} 
              onFail={handleQuoteFail}
              onMistake={handleMistake}
              onRequestNewQuote={handleRequestNextQuote}
              streak={streak}
              ghostWpm={getAverageWPM(wpmHistory)}
              settings={settings}
              gameMode={gameMode}
              onInteract={() => setIsMusicOpen(false)}
            />
          ) : (
             <div className="flex flex-col items-center justify-center text-stone-400">
              <Loader2 className="w-10 h-10 animate-spin mb-4 text-frog-green" />
              <p className="font-mono text-xs">Fetching wisdom...</p>
            </div>
          )}
        </div>
      </main>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        settings={settings} 
        setSettings={setSettings} 
      />

      <ThemeModal
        isOpen={isThemeOpen}
        onClose={() => setIsThemeOpen(false)}
        currentThemeId={settings.themeId}
        setThemeId={(id) => setSettings({ ...settings, themeId: id })}
        currentLevel={getCurrentLevel(userXP)}
        allLevels={LEVELS}
      />

      <AchievementsModal
        isOpen={isAchievementsOpen}
        onClose={() => setIsAchievementsOpen(false)}
        unlockedIds={unlockedAchievements}
      />

      <AchievementToast 
        notifications={notificationQueue}
        onClear={clearToast}
      />

      <HelpModal
        isOpen={isHelpOpen}
        onClose={() => setIsHelpOpen(false)}
      />

      <StatsModal
        isOpen={isStatsOpen}
        onClose={() => setIsStatsOpen(false)}
        avgWpm={getAverageWPM(wpmHistory)}
        history={testHistory}
        onPractice={handlePracticeFromHistory}
        totalTime={totalTimePlayed}
        joinDate={joinDate}
        streak={dailyStreak} // Pass Daily Streak here instead of Session Streak
        userName={userName}
        setUserName={setUserName}
        completedTestsCount={testHistory.length}
      />

      <MusicPlayer 
        isOpen={isMusicOpen} 
        onClose={() => setIsMusicOpen(false)} 
        settings={settings}
        setSettings={setSettings}
        userXP={userXP}
      />

      <footer className="p-6 text-center text-stone-300 text-[10px]">
        <p>© {new Date().getFullYear()} Frog Type. Wisdom from the Ages.</p>
      </footer>
    </div>
  );
};

