                                    {result.mode === 'FIX_MISTAKE' ? 'FIX' : result.mode}
                                </span>
                                <span className="text-xs text-stone-400 flex items-center gap-1 group-hover:text-frog-green transition-colors">
                                    <Calendar className="w-3 h-3" /> {formatDateTime(result.date)}
