import React, { useState, useEffect, useRef, useCallback } from 'react';
import { soundEngine } from '../utils/soundEngine';
import { Timer, Trophy, RotateCcw, X, Zap } from 'lucide-react';
import { fetchQuotes } from '../services/quoteService';

interface TimeAttackGameProps {
  onGameOver: (score: number, xp: number) => void;
  onExit: () => void;
}

const TimeAttackGame: React.FC<TimeAttackGameProps> = ({ onGameOver, onExit }) => {
  const [gameState, setGameState] = useState<'START' | 'PLAYING' | 'GAMEOVER'>('START');
  const [timeLeft, setTimeLeft] = useState(60);
  const [score, setScore] = useState(0);
  const [currentWord, setCurrentWord] = useState('');
  const [nextWords, setNextWords] = useState<string[]>([]);
  const [input, setInput] = useState('');
  const [status, setStatus] = useState<'NORMAL' | 'ERROR'>('NORMAL');

  const inputRef = useRef<HTMLInputElement>(null);
  const timerRef = useRef<number | undefined>(undefined);

  // Initialize
  const startGame = async () => {
    // Generate pool
    const quotes = await fetchQuotes(20, [], 'Tadpole', 'QUOTES'); 
    // Flatten quotes into words for speed typing
    const allWords = quotes.map(q => q.text.split(' ')).flat().filter(w => w.length > 2);

    setCurrentWord(allWords[0]);
    setNextWords(allWords.slice(1));
    setScore(0);
    setTimeLeft(60);
    setInput('');
    setStatus('NORMAL');
    setGameState('PLAYING');

    // Auto focus
    setTimeout(() => inputRef.current?.focus(), 100);
  };

  useEffect(() => {
    if (gameState === 'PLAYING') {
      timerRef.current = window.setInterval(() => {
        setTimeLeft((prev) => {
          if (prev <= 1) {
            endGame();
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
    }
    return () => clearInterval(timerRef.current);
  }, [gameState]);

  const endGame = () => {
    setGameState('GAMEOVER');
    clearInterval(timerRef.current);
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (gameState !== 'PLAYING') return;

    const val = e.target.value;

    // Check for error immediately
    if (!currentWord.startsWith(val)) {
        setStatus('ERROR');
        soundEngine.playError();
    } else {
        setStatus('NORMAL');
        soundEngine.playKeypress();
    }

    setInput(val);

    if (val === currentWord) {
        // Word Complete
        setScore(s => s + 1);
        soundEngine.playSuccess();
        setInput('');

        // Advance Word
        const next = nextWords[0] || "finish";
        setCurrentWord(next);
        setNextWords(prev => {
            const newNext = prev.slice(1);
            // Infinite generation hack
            if (newNext.length < 5) {
                return [...newNext, ...["fast", "speed", "zoom", "dash", "rush", "quick", "blitz", "hyper", "turbo", "sonic"]];
            }
            return newNext;
        });
    }
  };

  if (gameState === 'START') {
      return (
          <div className="w-full max-w-4xl mx-auto h-[400px] bg-white rounded-3xl border-4 border-stone-100 flex flex-col items-center justify-center shadow-xl p-8">
              <div className="text-center space-y-6">
                  <div className="w-20 h-20 bg-yellow-100 rounded-full flex items-center justify-center mx-auto mb-4">
                      <Zap className="w-10 h-10 text-yellow-500" />
                  </div>
                  <h2 className="text-4xl font-black text-stone-800 tracking-tight">SPEED RUSH</h2>
                  <p className="text-stone-500 text-lg">60 Seconds. Infinite Words. How fast can you go?</p>

                  <div className="flex gap-4 justify-center">
                      <button onClick={onExit} className="px-6 py-3 text-stone-400 font-bold hover:text-stone-600">
                          Back
                      </button>
                      <button 
                        onClick={startGame}
                        className="px-10 py-4 bg-yellow-400 hover:bg-yellow-500 text-stone-900 font-black text-xl rounded-full shadow-lg shadow-yellow-200 transition-transform hover:scale-105"
                      >
                          START TIMER
                      </button>
                  </div>
              </div>
          </div>
      );
  }

  if (gameState === 'GAMEOVER') {
      return (
          <div className="w-full max-w-4xl mx-auto h-[400px] bg-stone-900 rounded-3xl flex flex-col items-center justify-center text-white p-8 shadow-2xl">
              <div className="text-center space-y-6 animate-in zoom-in-95">
                  <div className="text-yellow-400 font-black text-6xl">{score}</div>
                  <div className="text-stone-400 uppercase tracking-widest font-bold">Words Typed</div>

                  <div className="flex gap-4 justify-center mt-8">
                      <button onClick={startGame} className="px-6 py-3 bg-stone-800 hover:bg-stone-700 rounded-xl font-bold flex items-center gap-2">
                          <RotateCcw className="w-4 h-4" /> Retry
                      </button>
                      <button onClick={() => onGameOver(score, score * 2)} className="px-6 py-3 bg-yellow-500 hover:bg-yellow-600 text-stone-900 rounded-xl font-bold flex items-center gap-2">
                          <Trophy className="w-4 h-4" /> Finish
                      </button>
                  </div>
              </div>
          </div>
      );
  }

  return (
    <div className="w-full max-w-4xl mx-auto h-[400px] bg-white rounded-3xl border border-stone-200 shadow-xl flex flex-col relative overflow-hidden">
        {/* Header */}
        <div className="flex justify-between items-center p-6 border-b border-stone-100">
            <div className="flex items-center gap-3">
                <div className="bg-yellow-100 p-2 rounded-lg"><Zap className="w-6 h-6 text-yellow-600" /></div>
                <div className="text-2xl font-black text-stone-800">{score}</div>
            </div>
            <div className={`text-4xl font-black font-mono ${timeLeft < 10 ? 'text-red-500 animate-pulse' : 'text-stone-800'}`}>
                {timeLeft}
            </div>
            <button onClick={onExit} className="p-2 hover:bg-stone-100 rounded-full text-stone-400">
                <X className="w-6 h-6" />
            </button>
        </div>

        {/* Game Area */}
        <div className="flex-1 flex flex-col items-center justify-center bg-stone-50/50">

            {/* Word Queue */}
            <div className="flex items-center gap-4 mb-8 opacity-50">
                {nextWords.slice(0, 3).map((w, i) => (
                    <span key={i} className="text-xl font-bold text-stone-400">{w}</span>
                ))}
            </div>

            {/* Active Word */}
            <div className="relative mb-8">
                <div className="text-6xl font-black text-stone-200 tracking-wide select-none">
                    {currentWord}
                </div>
                <div className={`absolute top-0 left-0 text-6xl font-black tracking-wide pointer-events-none whitespace-pre ${status === 'ERROR' ? 'text-red-500' : 'text-stone-800'}`}>
                    {input}
                </div>
            </div>

            {/* Input */}
            <input 
                ref={inputRef}
                value={input}
                onChange={handleInputChange}
                className="opacity-0 absolute inset-0 cursor-default"
                autoFocus
            />

            <div className="text-stone-400 text-sm font-bold uppercase tracking-widest">Type Fast!</div>
        </div>

        {/* Progress Bar for Time */}
        <div className="h-2 bg-stone-100 w-full">
            <div 
                className="h-full bg-yellow-400 transition-all duration-1000 ease-linear"
                style={{ width: `${(timeLeft / 60) * 100}%` }}
            ></div>
        </div>
    </div>
  );
};

export default TimeAttackGame;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { soundEngine } from '../utils/soundEngine';
import { Skull, Heart, Trophy, X, Play, Zap, Shield, Biohazard, RotateCcw } from 'lucide-react';

// --- WORD POOLS ---

const SWAMP_WORDS = [
  "frog", "jump", "pond", "green", "water", "lily", "pad", "swim", "croak", "fly",
  "bug", "tongue", "catch", "swamp", "reed", "mud", "rain", "splash", "hop", "toad",
  "nature", "wild", "forest", "tree", "leaf", "root", "moss", "fern", "stone", "rock",
  "river", "creek", "lake", "stream", "flow", "drift", "float", "sink", "dive", "wet",
  "slime", "slick", "quick", "fast", "slow", "wait", "hide", "seek", "find", "hunt",
  "blue", "teal", "lime", "dark", "light", "sun", "moon", "star", "sky", "cloud"
];

const ZOMBIE_WORDS = [
  "run", "hide", "flee", "dead", "bite", "gore", "fear", "dark", "doom", "grim",
  "tomb", "dust", "bone", "pale", "cold", "rot", "sick", "pain", "hurt", "kill",
  "aim", "gun", "shot", "fire", "load", "clip", "ammo", "bang", "boom", "slam",
  "lock", "door", "safe", "help", "save", "cure", "pill", "heal", "life", "soul",
  "blood", "flesh", "brain", "skull", "spine", "ribs", "limbs", "teeth", "claw", "nail",
  "virus", "toxin", "decay", "grave", "ghost", "haunt", "scare", "panic", "shout", "scream",
  "horror", "terror", "night", "black", "shadow", "creep", "crawl", "stalk", "chase", "hunt",
  "ruins", "ashes", "smoke", "flame", "burn", "torch", "light", "flash", "spark", "ember",
  "survive", "escape", "resist", "defend", "attack", "strike", "smash", "break", "crush", "snap"
];

const HARD_WORDS = [
    "amphibian", "ecosystem", "metamorphosis", "evolution", "biodiversity",
    "photosynthesis", "chlorophyll", "atmosphere", "temperature", "precipitation",
    "apocalypse", "infection", "quarantine", "sanctuary", "barricade",
    "evacuation", "contagion", "mutation", "resurrection", "survivalist",
    "ammunition", "ballistics", "headshot", "marksmanship", "adrenaline",
    "desolation", "abandoned", "nightmare", "hallucination", "psychosis"
];

export type SurvivalVariant = 'SWAMP' | 'ZOMBIE';

interface Enemy {
  id: number;
  word: string;
  typed: string; // What has been typed so far
  x: number; // Percentage 0-100 (starts at 100)
  y: number; // Percentage 10-90
  speed: number;
  type: 'NORMAL' | 'FAST' | 'TANK' | 'BOSS';
  isLocked: boolean;
  damage: number;
}

interface SurvivalGameProps {
  variant: SurvivalVariant;
  onGameOver: (score: number, xp: number) => void;
  onExit: () => void;
}

const SurvivalGame: React.FC<SurvivalGameProps> = ({ variant, onGameOver, onExit }) => {
  const [gameState, setGameState] = useState<'START' | 'PLAYING' | 'GAMEOVER'>('START');
  const [enemies, setEnemies] = useState<Enemy[]>([]);
  const [score, setScore] = useState(0);
  const [lives, setLives] = useState(3);
  const [multiplier, setMultiplier] = useState(1);

  // Game Loop Refs
  const requestRef = useRef<number>(0);
  const lastTimeRef = useRef<number>(0);
  const spawnTimerRef = useRef<number>(0);
  const difficultyRef = useRef<number>(1);
  const gameStateRef = useRef<'START' | 'PLAYING' | 'GAMEOVER'>('START');
  const livesRef = useRef(3);

  // Input Refs
  const activeEnemyIdRef = useRef<number | null>(null);

  // Sync state to refs for game loop
  useEffect(() => {
    gameStateRef.current = gameState;
  }, [gameState]);

  useEffect(() => {
    livesRef.current = lives;
  }, [lives]);

  // Theme Configuration
  const isZombie = variant === 'ZOMBIE';
  const PRIMARY_COLOR = isZombie ? 'text-red-500' : 'text-frog-green';
  const BG_CLASS = isZombie ? 'bg-stone-950' : 'bg-stone-900';
  const BORDER_CLASS = isZombie ? 'border-red-900/50' : 'border-stone-800';

  // Initialize Game
  const startGame = () => {
    setEnemies([]);
    setScore(0);
    setLives(3);
    setMultiplier(1);
    setGameState('PLAYING');

    // Reset Refs
    gameStateRef.current = 'PLAYING';
    livesRef.current = 3;
    activeEnemyIdRef.current = null;
    difficultyRef.current = 1;
    spawnTimerRef.current = 0;
    lastTimeRef.current = performance.now();

    if (requestRef.current) cancelAnimationFrame(requestRef.current);
    requestRef.current = requestAnimationFrame(gameLoop);
  };

  const spawnEnemy = () => {
    const id = Date.now() + Math.random();
    const isHard = Math.random() < (0.05 * difficultyRef.current);

    // Choose pool based on variant
    const basePool = isZombie ? ZOMBIE_WORDS : SWAMP_WORDS;
    const pool = isHard ? HARD_WORDS : basePool;
    const word = pool[Math.floor(Math.random() * pool.length)];

    // Determine Type
    let type: Enemy['type'] = 'NORMAL';
    let speedBase = 0.03; 
    let damage = 1;

    if (word.length > 7) {
        type = 'TANK';
        speedBase = 0.02;
        damage = 2;
    } else if (Math.random() > 0.75) {
        type = 'FAST';
        speedBase = 0.045;
    }

    // Apply difficulty multiplier to speed
    const finalSpeed = speedBase * (1 + (difficultyRef.current * 0.1));

    const newEnemy: Enemy = {
      id,
      word,
      typed: '',
      x: 100,
      y: 15 + Math.random() * 70, 
      speed: finalSpeed,
      type,
      isLocked: false,
      damage
    };

    setEnemies(prev => [...prev, newEnemy]);
  };

  const gameLoop = (time: number) => {
    if (gameStateRef.current !== 'PLAYING') return;

    const deltaTime = time - (lastTimeRef.current || time);
    lastTimeRef.current = time;

    // Difficulty scaling
    difficultyRef.current += 0.0005;

    // Spawning Logic
    spawnTimerRef.current += deltaTime;
    const spawnInterval = Math.max(500, 2000 - (difficultyRef.current * 100));

    if (spawnTimerRef.current > spawnInterval) {
        spawnEnemy();
        spawnTimerRef.current = 0;
    }

    // Update Enemies
    setEnemies(prevEnemies => {
      const nextEnemies: Enemy[] = [];
      let damageTaken = 0;

      prevEnemies.forEach(enemy => {
         const moveAmount = (enemy.speed * deltaTime) / 16; 
         enemy.x -= moveAmount;

         if (enemy.x <= 10) { // Reached player
             damageTaken += enemy.damage;
             soundEngine.playError();
             if (activeEnemyIdRef.current === enemy.id) {
                 activeEnemyIdRef.current = null;
             }
         } else {
             nextEnemies.push(enemy);
         }
      });

      if (damageTaken > 0) {
          // Update ref immediately for the next frame check
          livesRef.current = Math.max(0, livesRef.current - damageTaken);

          setLives(prev => {
              const newLives = prev - damageTaken;
              if (newLives <= 0) {
                  endGame();
                  return 0;
              }
              return newLives;
          });
          setMultiplier(1);
      }

      return nextEnemies;
    });

    if (livesRef.current > 0) {
        requestRef.current = requestAnimationFrame(gameLoop);
    }
  };

  const endGame = () => {
      setGameState('GAMEOVER');
      gameStateRef.current = 'GAMEOVER';
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
  };

  const handleKeyDown = useCallback((e: KeyboardEvent) => {
    if (gameStateRef.current !== 'PLAYING') return;

    if (e.key === 'Escape') {
        setEnemies(prev => prev.map(en => ({...en, isLocked: false, typed: ''})));
        activeEnemyIdRef.current = null;
        return;
    }

    if (e.key.length !== 1 || e.metaKey || e.ctrlKey || e.altKey) return;

    const char = e.key.toLowerCase();

    setEnemies(prev => {
        let newEnemies = [...prev];
        let hit = false;
        let kill = false;

        if (activeEnemyIdRef.current !== null) {
            const idx = newEnemies.findIndex(e => e.id === activeEnemyIdRef.current);
            if (idx !== -1) {
                const enemy = newEnemies[idx];
                const nextChar = enemy.word[enemy.typed.length];

                if (nextChar === char) {
                    hit = true;
                    const newTyped = enemy.typed + char;
                    newEnemies[idx] = { ...enemy, typed: newTyped };

                    if (newTyped === enemy.word) {
                        kill = true;
                        newEnemies.splice(idx, 1);
                        activeEnemyIdRef.current = null;
                    }
                } else {
                    soundEngine.playError();
                    setMultiplier(1);
                }
            } else {
                activeEnemyIdRef.current = null;
            }
        } else {
            const candidates = newEnemies
                .filter(e => e.word.startsWith(char))
                .sort((a, b) => a.x - b.x);

            if (candidates.length > 0) {
                const target = candidates[0];
                const idx = newEnemies.findIndex(e => e.id === target.id);

                hit = true;
                activeEnemyIdRef.current = target.id;

                const newTyped = char;
                newEnemies[idx] = { ...target, isLocked: true, typed: newTyped };

                if (newTyped === target.word) {
                     kill = true;
                     newEnemies.splice(idx, 1);
                     activeEnemyIdRef.current = null;
                }
            }
        }

        if (hit) soundEngine.playKeypress();
        if (kill) {
            soundEngine.playSuccess();
            setScore(s => s + (10 * multiplier));
            setMultiplier(m => Math.min(m + 1, 10));
        }

        return newEnemies;
    });

  }, [multiplier]); // Multiplier dependency is fine as long as we use refs for game state

  useEffect(() => {
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleKeyDown]);

  useEffect(() => {
      return () => {
          if (requestRef.current) cancelAnimationFrame(requestRef.current);
      };
  }, []);

  const handleFinish = () => {
     const xp = Math.floor(score / 2);
     onGameOver(score, xp);
  };

  const renderEnemy = (enemy: Enemy) => {
      let icon = '';
      if (isZombie) {
          if (enemy.type === 'TANK') icon = '🧟‍♂️'; // Big Zombie
          else if (enemy.type === 'FAST') icon = '🐕'; // Zombie Dog
          else icon = '🧟'; // Normal Zombie
      } else {
          if (enemy.type === 'TANK') icon = '👻'; // Ghost
          else if (enemy.type === 'FAST') icon = '🕷️'; // Spider
          else icon = '🪰'; // Fly
      }

      const untyped = enemy.word.slice(enemy.typed.length);
      const isLocked = enemy.isLocked;

      return (
          <div 
            key={enemy.id}
            className="absolute flex flex-col items-center transition-transform"
            style={{ 
                left: `${enemy.x}%`, 
                top: `${enemy.y}%`,
                transform: `scale(${isLocked ? 1.2 : 1})`,
                zIndex: isLocked ? 20 : 10
            }}
          >
              <div className={`
                 text-sm font-mono font-bold px-2 py-0.5 rounded-full mb-1 whitespace-nowrap shadow-sm
                 ${isLocked 
                     ? isZombie ? 'bg-red-600 text-white ring-2 ring-white' : 'bg-frog-green text-white ring-2 ring-white'
                     : 'bg-stone-800/80 text-stone-200'
                 }
              `}>
                  <span className="text-white/50">{enemy.typed}</span>
                  <span className="text-white">{untyped}</span>
              </div>
              <div className="text-4xl filter drop-shadow-lg animate-bounce" style={{ animationDuration: `${2/enemy.speed}s` }}>
                  {icon}
              </div>
          </div>
      );
  };

  if (gameState === 'START') {
      return (
          <div className={`w-full max-w-4xl mx-auto h-[500px] rounded-3xl relative overflow-hidden flex flex-col items-center justify-center text-white border-4 shadow-2xl ${BG_CLASS} ${BORDER_CLASS}`}>
              <div className="absolute inset-0 opacity-20 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')]"></div>
              <div className="z-10 text-center space-y-6">
                  <h2 className={`text-5xl font-black tracking-tighter flex items-center gap-4 justify-center ${PRIMARY_COLOR}`}>
                      {isZombie ? <Biohazard className="w-12 h-12" /> : <Skull className="w-12 h-12" />}
                      {isZombie ? 'OUTBREAK Z' : 'SWAMP SURVIVAL'}
                  </h2>
                  <p className="text-stone-400 max-w-md mx-auto text-lg">
                      {isZombie 
                        ? "The horde is coming. Type to shoot. Don't let them get close."
                        : "Defend the pond! Type the words above the enemies to zap them."
                      }
                  </p>

                  <div className="grid grid-cols-3 gap-4 text-sm max-w-lg mx-auto">
                      <div className="bg-stone-800 p-3 rounded-xl border border-stone-700">
                          <div className={PRIMARY_COLOR + " font-bold"}>Lock On</div>
                          <div className="text-stone-500">Type 1st letter</div>
                      </div>
                      <div className="bg-stone-800 p-3 rounded-xl border border-stone-700">
                          <div className="text-orange-500 font-bold">Priority</div>
                          <div className="text-stone-500">Fastest/Closest</div>
                      </div>
                      <div className="bg-stone-800 p-3 rounded-xl border border-stone-700">
                          <div className="text-purple-500 font-bold">Combo</div>
                          <div className="text-stone-500">Don't miss</div>
                      </div>
                  </div>

                  <button 
                    onClick={startGame}
                    className={`px-8 py-4 ${isZombie ? 'bg-red-600 hover:bg-red-500' : 'bg-frog-green hover:bg-green-500'} text-white font-black text-xl rounded-full transition-transform hover:scale-105 shadow-lg flex items-center gap-2 mx-auto`}
                  >
                      <Play className="w-6 h-6 fill-current" /> START WAVE
                  </button>
                  <button onClick={onExit} className="text-stone-500 hover:text-white text-sm underline decoration-stone-600 underline-offset-4">
                      Return to Menu
                  </button>
              </div>
          </div>
      );
  }

  if (gameState === 'GAMEOVER') {
      return (
          <div className="w-full max-w-4xl mx-auto h-[500px] bg-stone-900 rounded-3xl relative overflow-hidden flex flex-col items-center justify-center text-white border-4 border-red-900 shadow-2xl">
              <div className="z-10 text-center space-y-6 animate-in zoom-in-95 duration-300">
                  <div className="text-red-600 font-black text-6xl tracking-widest mb-2">OVERRUN</div>
                  <div className="text-2xl font-mono">
                      Score: <span className={PRIMARY_COLOR}>{score}</span>
                  </div>
                  <div className="flex gap-4 justify-center mt-8">
                      <button 
                        onClick={startGame}
                        className="px-6 py-3 bg-stone-100 hover:bg-white text-stone-900 font-bold rounded-xl flex items-center gap-2"
                      >
                          <RotateCcw className="w-5 h-5" /> Retry
                      </button>
                      <button 
                        onClick={handleFinish}
                        className={`px-6 py-3 ${isZombie ? 'bg-red-600 hover:bg-red-500' : 'bg-frog-green hover:bg-green-500'} text-white font-bold rounded-xl flex items-center gap-2`}
                      >
                          <Trophy className="w-5 h-5" /> Collect XP
                      </button>
                  </div>
              </div>
          </div>
      );
  }

  return (
    <div className={`w-full max-w-4xl mx-auto h-[500px] rounded-3xl relative overflow-hidden border-4 shadow-inner cursor-crosshair select-none ${BG_CLASS} ${BORDER_CLASS}`}>
        {/* Background Elements */}
        <div className={`absolute inset-0 opacity-10 bg-[radial-gradient(ellipse_at_center,_var(--tw-gradient-stops))] ${isZombie ? 'from-red-900 via-stone-950 to-black' : 'from-frog-green via-stone-900 to-stone-950'}`}></div>
        <div className="absolute bottom-0 w-full h-1/3 bg-gradient-to-t from-black/80 to-transparent pointer-events-none"></div>

        {/* HUD */}
        <div className="absolute top-4 left-4 right-4 flex justify-between items-start z-30">
            <div className="flex items-center gap-4">
                <div className="bg-stone-800/80 backdrop-blur-sm border border-stone-700 px-4 py-2 rounded-xl flex items-center gap-2">
                    <Trophy className="w-4 h-4 text-yellow-500" />
                    <span className="font-mono text-xl font-bold text-white">{score}</span>
                </div>
                {multiplier > 1 && (
                    <div className="text-yellow-400 font-black italic text-xl animate-pulse">
                        {multiplier}x
                    </div>
                )}
            </div>

            <div className="flex items-center gap-2 bg-stone-800/80 backdrop-blur-sm border border-stone-700 px-3 py-1.5 rounded-full">
                {Array.from({length: 3}).map((_, i) => (
                    <Heart 
                        key={i} 
                        className={`w-5 h-5 ${i < lives ? 'fill-red-500 text-red-500' : 'text-stone-700'}`} 
                    />
                ))}
            </div>

            <button onClick={onExit} className="p-2 bg-stone-800/50 hover:bg-red-900/50 rounded-full text-white/50 hover:text-white transition-colors">
                <X className="w-5 h-5" />
            </button>
        </div>

        {/* Player */}
        <div className="absolute left-4 top-1/2 -translate-y-1/2 z-20 transition-transform">
             <div className={`text-6xl filter drop-shadow-[0_0_15px_rgba(255,255,255,0.2)] transform ${isZombie ? '' : '-scale-x-100'}`}>
                 {isZombie ? '🏰' : '🐸'}
             </div>
        </div>

        {/* Danger Zone Line */}
        <div className="absolute left-[10%] top-0 bottom-0 w-1 bg-red-500/10 border-r border-red-500/10 z-0"></div>

        {/* Enemies */}
        {enemies.map(renderEnemy)}

    </div>
  );
};

export default SurvivalGame;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { soundEngine } from '../utils/soundEngine';
import { Timer, Trophy, RotateCcw, X, Zap } from 'lucide-react';
import { fetchQuotes } from '../services/quoteService';

interface TimeAttackGameProps {
  onGameOver: (score: number, xp: number) => void;
  onExit: () => void;
}

const TimeAttackGame: React.FC<TimeAttackGameProps> = ({ onGameOver, onExit }) => {
  const [gameState, setGameState] = useState<'START' | 'PLAYING' | 'GAMEOVER'>('START');
  const [timeLeft, setTimeLeft] = useState(60);
  const [score, setScore] = useState(0);
  const [currentWord, setCurrentWord] = useState('');
  const [nextWords, setNextWords] = useState<string[]>([]);
  const [input, setInput] = useState('');
  const [status, setStatus] = useState<'NORMAL' | 'ERROR'>('NORMAL');
  const [isLoading, setIsLoading] = useState(false);

  const inputRef = useRef<HTMLInputElement>(null);
  const timerRef = useRef<number | undefined>(undefined);

  // Helper to clean words
  const cleanWord = (w: string) => w.replace(/[^a-zA-Z]/g, '').toLowerCase();

  // Initialize
  const startGame = async () => {
    setIsLoading(true);
    // Generate pool
    const quotes = await fetchQuotes(30, [], 'Tadpole', 'QUOTES'); 
    // Flatten quotes into words for speed typing, remove punctuation
    const allWords = quotes
        .map(q => q.text.split(' '))
        .flat()
        .map(cleanWord)
        .filter(w => w.length > 2);

    // Add backup words
    const backupWords = ["speed", "rush", "fast", "quick", "zoom", "dash", "type", "frog", "jump", "leap", "time", "clock", "race"];
    const finalPool = [...allWords, ...backupWords];

    setCurrentWord(finalPool[0]);
    setNextWords(finalPool.slice(1));
    setScore(0);
    setTimeLeft(60);
    setInput('');
    setStatus('NORMAL');
    setGameState('PLAYING');
    setIsLoading(false);

    // Auto focus
    setTimeout(() => inputRef.current?.focus(), 100);
  };

  useEffect(() => {
    if (gameState === 'PLAYING') {
      timerRef.current = window.setInterval(() => {
        setTimeLeft((prev) => {
          if (prev <= 1) {
            endGame();
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
    }
    return () => clearInterval(timerRef.current);
  }, [gameState]);

  const endGame = () => {
    setGameState('GAMEOVER');
    clearInterval(timerRef.current);
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (gameState !== 'PLAYING') return;

    const rawVal = e.target.value;

    // Prevent space from becoming part of the word, acts as a soft block or ignored
    if (rawVal.endsWith(' ')) {
        return; 
    }

    const val = rawVal.trim().toLowerCase();

    // Check for error immediately
    if (!currentWord.startsWith(val)) {
        setStatus('ERROR');
        soundEngine.playError();
    } else {
        setStatus('NORMAL');
        soundEngine.playKeypress();
    }

    setInput(val);

    if (val === currentWord) {
        // Word Complete
        setScore(s => s + 1);
        soundEngine.playSuccess();
        setInput('');

        // Advance Word
        // If queue empty, reuse some words randomly
        const nextPool = nextWords.length > 0 
            ? nextWords 
            : ["fast", "speed", "zoom", "dash", "rush", "quick", "blitz", "hyper", "turbo", "sonic"];

        setCurrentWord(nextPool[0]);
        setNextWords(prev => prev.slice(1));
    }
  };

  if (gameState === 'START') {
      return (
          <div className="w-full max-w-4xl mx-auto h-[400px] bg-white rounded-3xl border-4 border-stone-100 flex flex-col items-center justify-center shadow-xl p-8">
              <div className="text-center space-y-6">
                  <div className="w-20 h-20 bg-yellow-100 rounded-full flex items-center justify-center mx-auto mb-4">
                      <Zap className="w-10 h-10 text-yellow-500" />
                  </div>
                  <h2 className="text-4xl font-black text-stone-800 tracking-tight">SPEED RUSH</h2>
                  <p className="text-stone-500 text-lg">60 Seconds. Infinite Words. No Punctuation.</p>

                  <div className="flex gap-4 justify-center">
                      <button onClick={onExit} className="px-6 py-3 text-stone-400 font-bold hover:text-stone-600">
                          Back
                      </button>
                      <button 
                        onClick={startGame}
                        disabled={isLoading}
                        className="px-10 py-4 bg-yellow-400 hover:bg-yellow-500 text-stone-900 font-black text-xl rounded-full shadow-lg shadow-yellow-200 transition-transform hover:scale-105 disabled:opacity-50"
                      >
                          {isLoading ? "LOADING..." : "START TIMER"}
                      </button>
                  </div>
              </div>
          </div>
      );
  }

  if (gameState === 'GAMEOVER') {
      return (
          <div className="w-full max-w-4xl mx-auto h-[400px] bg-stone-900 rounded-3xl flex flex-col items-center justify-center text-white p-8 shadow-2xl">
              <div className="text-center space-y-6 animate-in zoom-in-95">
                  <div className="text-yellow-400 font-black text-6xl">{score}</div>
                  <div className="text-stone-400 uppercase tracking-widest font-bold">Words Typed</div>

                  <div className="flex gap-4 justify-center mt-8">
                      <button onClick={startGame} className="px-6 py-3 bg-stone-800 hover:bg-stone-700 rounded-xl font-bold flex items-center gap-2">
                          <RotateCcw className="w-4 h-4" /> Retry
                      </button>
                      <button onClick={() => onGameOver(score, score * 2)} className="px-6 py-3 bg-yellow-500 hover:bg-yellow-600 text-stone-900 rounded-xl font-bold flex items-center gap-2">
                          <Trophy className="w-4 h-4" /> Finish
                      </button>
                  </div>
              </div>
          </div>
      );
  }

  return (
    <div className="w-full max-w-4xl mx-auto h-[400px] bg-white rounded-3xl border border-stone-200 shadow-xl flex flex-col relative overflow-hidden">
        {/* Header */}
        <div className="flex justify-between items-center p-6 border-b border-stone-100">
            <div className="flex items-center gap-3">
                <div className="bg-yellow-100 p-2 rounded-lg"><Zap className="w-6 h-6 text-yellow-600" /></div>
                <div className="text-2xl font-black text-stone-800">{score}</div>
            </div>
            <div className={`text-4xl font-black font-mono ${timeLeft < 10 ? 'text-red-500 animate-pulse' : 'text-stone-800'}`}>
                {timeLeft}
            </div>
            <button onClick={onExit} className="p-2 hover:bg-stone-100 rounded-full text-stone-400">
                <X className="w-6 h-6" />
            </button>
        </div>

        {/* Game Area */}
        <div className="flex-1 flex flex-col items-center justify-center bg-stone-50/50">

            {/* Word Queue */}
            <div className="flex items-center gap-4 mb-8 opacity-50">
                {nextWords.slice(0, 3).map((w, i) => (
                    <span key={i} className="text-xl font-bold text-stone-400">{w}</span>
                ))}
            </div>

            {/* Active Word */}
            <div className="relative mb-8">
                <div className="text-6xl font-black text-stone-200 tracking-wide select-none">
                    {currentWord}
                </div>
                <div className={`absolute top-0 left-0 text-6xl font-black tracking-wide pointer-events-none whitespace-pre ${status === 'ERROR' ? 'text-red-500' : 'text-stone-800'}`}>
                    {input}
                </div>
            </div>

            {/* Input */}
            <input 
                ref={inputRef}
                value={input}
                onChange={handleInputChange}
                className="opacity-0 absolute inset-0 cursor-default"
                autoFocus
            />

            <div className="text-stone-400 text-sm font-bold uppercase tracking-widest">Type Fast!</div>
        </div>

        {/* Progress Bar for Time */}
        <div className="h-2 bg-stone-100 w-full">
            <div 
                className="h-full bg-yellow-400 transition-all duration-1000 ease-linear"
                style={{ width: `${(timeLeft / 60) * 100}%` }}
            ></div>
        </div>
    </div>
  );
};

export default TimeAttackGame;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { soundEngine } from '../utils/soundEngine';
import { Skull, Heart, Trophy, X, Play, Zap, Biohazard, RotateCcw, ShieldPlus } from 'lucide-react';

// --- WORD POOLS ---

const SWAMP_WORDS = [
  "frog", "jump", "pond", "green", "water", "lily", "pad", "swim", "croak", "fly",
  "bug", "tongue", "catch", "swamp", "reed", "mud", "rain", "splash", "hop", "toad",
  "nature", "wild", "forest", "tree", "leaf", "root", "moss", "fern", "stone", "rock",
  "river", "creek", "lake", "stream", "flow", "drift", "float", "sink", "dive", "wet",
  "slime", "slick", "quick", "fast", "slow", "wait", "hide", "seek", "find", "hunt",
  "blue", "teal", "lime", "dark", "light", "sun", "moon", "star", "sky", "cloud"
];

const ZOMBIE_WORDS = [
  "run", "hide", "flee", "dead", "bite", "gore", "fear", "dark", "doom", "grim",
  "tomb", "dust", "bone", "pale", "cold", "rot", "sick", "pain", "hurt", "kill",
  "aim", "gun", "shot", "fire", "load", "clip", "ammo", "bang", "boom", "slam",
  "lock", "door", "safe", "help", "save", "cure", "pill", "heal", "life", "soul",
  "blood", "flesh", "brain", "skull", "spine", "ribs", "limbs", "teeth", "claw", "nail",
  "virus", "toxin", "decay", "grave", "ghost", "haunt", "scare", "panic", "shout", "scream",
  "horror", "terror", "night", "black", "shadow", "creep", "crawl", "stalk", "chase", "hunt",
  "ruins", "ashes", "smoke", "flame", "burn", "torch", "light", "flash", "spark", "ember",
  "survive", "escape", "resist", "defend", "attack", "strike", "smash", "break", "crush", "snap"
];

const HARD_WORDS = [
    "amphibian", "ecosystem", "metamorphosis", "evolution", "biodiversity",
    "photosynthesis", "chlorophyll", "atmosphere", "temperature", "precipitation",
    "apocalypse", "infection", "quarantine", "sanctuary", "barricade",
    "evacuation", "contagion", "mutation", "resurrection", "survivalist",
    "ammunition", "ballistics", "headshot", "marksmanship", "adrenaline",
    "desolation", "abandoned", "nightmare", "hallucination", "psychosis"
];

export type SurvivalVariant = 'SWAMP' | 'ZOMBIE';

interface Enemy {
  id: number;
  word: string;
  typed: string; // What has been typed so far
  x: number; // Percentage 0-100 (starts at 100)
  y: number; // Percentage 10-90
  speed: number;
  type: 'NORMAL' | 'FAST' | 'TANK' | 'BOSS';
  isLocked: boolean;
  damage: number;
}

interface SurvivalGameProps {
  variant: SurvivalVariant;
  onGameOver: (score: number, xp: number) => void;
  onExit: () => void;
}

const SurvivalGame: React.FC<SurvivalGameProps> = ({ variant, onGameOver, onExit }) => {
  const [gameState, setGameState] = useState<'START' | 'PLAYING' | 'GAMEOVER' | 'WAVE_COMPLETE'>('START');
  const [enemies, setEnemies] = useState<Enemy[]>([]);
  const [score, setScore] = useState(0);
  const [lives, setLives] = useState(3);
  const [multiplier, setMultiplier] = useState(1);
  const [wave, setWave] = useState(1);
  const [waveProgress, setWaveProgress] = useState(0);
  const [waveTarget, setWaveTarget] = useState(10);
  const [waveNotification, setWaveNotification] = useState<string | null>(null);

  // Game Loop Refs
  const requestRef = useRef<number>(0);
  const lastTimeRef = useRef<number>(0);
  const spawnTimerRef = useRef<number>(0);
  const difficultyRef = useRef<number>(1);
  const gameStateRef = useRef<'START' | 'PLAYING' | 'GAMEOVER' | 'WAVE_COMPLETE'>('START');
  const livesRef = useRef(3);

  // Input Refs
  const activeEnemyIdRef = useRef<number | null>(null);

  // Sync state to refs for game loop
  useEffect(() => {
    gameStateRef.current = gameState;
  }, [gameState]);

  useEffect(() => {
    livesRef.current = lives;
  }, [lives]);

  // Theme Configuration
  const isZombie = variant === 'ZOMBIE';
  const PRIMARY_COLOR = isZombie ? 'text-red-500' : 'text-frog-green';
  const BG_CLASS = isZombie ? 'bg-stone-950' : 'bg-stone-900';
  const BORDER_CLASS = isZombie ? 'border-red-900/50' : 'border-stone-800';

  // Initialize Game
  const startGame = () => {
    setEnemies([]);
    setScore(0);
    setLives(3);
    setMultiplier(1);
    setWave(1);
    setWaveProgress(0);
    setWaveTarget(10);
    setWaveNotification("WAVE 1");
    setGameState('PLAYING');

    // Reset Refs
    gameStateRef.current = 'PLAYING';
    livesRef.current = 3;
    activeEnemyIdRef.current = null;
    difficultyRef.current = 1;
    spawnTimerRef.current = 0;
    lastTimeRef.current = performance.now();

    setTimeout(() => setWaveNotification(null), 2000);

    if (requestRef.current) cancelAnimationFrame(requestRef.current);
    requestRef.current = requestAnimationFrame(gameLoop);
  };

  const advanceWave = () => {
      // Heal player
      const newLives = Math.min(3, livesRef.current + 1);
      setLives(newLives);
      livesRef.current = newLives;

      const nextWave = wave + 1;
      setWave(nextWave);
      setWaveProgress(0);
      setWaveTarget(Math.floor(10 + (nextWave * 5))); // Increase target count

      // Increase Difficulty
      difficultyRef.current += 0.5;

      // Show Notification
      setWaveNotification(`WAVE ${nextWave}`);
      soundEngine.playLevelUp(); // Re-use level up sound for wave complete

      setTimeout(() => setWaveNotification(null), 2500);
  };

  const spawnEnemy = () => {
    const id = Date.now() + Math.random();
    // Increase chance of hard words significantly with wave
    const hardChance = 0.05 + (wave * 0.02);
    const isHard = Math.random() < hardChance;

    // Choose pool based on variant
    const basePool = isZombie ? ZOMBIE_WORDS : SWAMP_WORDS;
    const pool = isHard ? HARD_WORDS : basePool;
    const word = pool[Math.floor(Math.random() * pool.length)];

    // Determine Type
    let type: Enemy['type'] = 'NORMAL';
    let speedBase = 0.03; 
    let damage = 1;

    // Tank logic (more frequent in later waves)
    if (word.length > 7 || (wave > 3 && Math.random() > 0.8)) {
        type = 'TANK';
        speedBase = 0.02;
        damage = 2;
    } else if (Math.random() > 0.75) {
        type = 'FAST';
        speedBase = 0.045;
    }

    // Apply difficulty multiplier to speed
    const finalSpeed = speedBase * (1 + (difficultyRef.current * 0.15));

    const newEnemy: Enemy = {
      id,
      word,
      typed: '',
      x: 100,
      y: 15 + Math.random() * 70, 
      speed: finalSpeed,
      type,
      isLocked: false,
      damage
    };

    setEnemies(prev => [...prev, newEnemy]);
  };

  const gameLoop = (time: number) => {
    if (gameStateRef.current !== 'PLAYING') return;

    const deltaTime = time - (lastTimeRef.current || time);
    lastTimeRef.current = time;

    // Difficulty scaling (passive increase)
    difficultyRef.current += 0.0001;

    // Spawning Logic
    spawnTimerRef.current += deltaTime;
    // Spawn rate caps at 400ms
    const spawnInterval = Math.max(400, 2000 - (difficultyRef.current * 150));

    if (spawnTimerRef.current > spawnInterval) {
        spawnEnemy();
        spawnTimerRef.current = 0;
    }

    // Update Enemies
    setEnemies(prevEnemies => {
      const nextEnemies: Enemy[] = [];
      let damageTaken = 0;

      prevEnemies.forEach(enemy => {
         const moveAmount = (enemy.speed * deltaTime) / 16; 
         enemy.x -= moveAmount;

         if (enemy.x <= 10) { // Reached player
             damageTaken += enemy.damage;
             soundEngine.playError();
             if (activeEnemyIdRef.current === enemy.id) {
                 activeEnemyIdRef.current = null;
             }
         } else {
             nextEnemies.push(enemy);
         }
      });

      if (damageTaken > 0) {
          // Update ref immediately for the next frame check
          livesRef.current = Math.max(0, livesRef.current - damageTaken);

          setLives(prev => {
              const newLives = prev - damageTaken;
              if (newLives <= 0) {
                  endGame();
                  return 0;
              }
              return newLives;
          });
          setMultiplier(1);
      }

      return nextEnemies;
    });

    if (livesRef.current > 0) {
        requestRef.current = requestAnimationFrame(gameLoop);
    }
  };

  const endGame = () => {
      setGameState('GAMEOVER');
      gameStateRef.current = 'GAMEOVER';
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
  };

  const handleKeyDown = useCallback((e: KeyboardEvent) => {
    if (gameStateRef.current !== 'PLAYING') return;

    if (e.key === 'Escape') {
        setEnemies(prev => prev.map(en => ({...en, isLocked: false, typed: ''})));
        activeEnemyIdRef.current = null;
        return;
    }

    if (e.key.length !== 1 || e.metaKey || e.ctrlKey || e.altKey) return;

    const char = e.key.toLowerCase();

    setEnemies(prev => {
        let newEnemies = [...prev];
        let hit = false;
        let kill = false;

        if (activeEnemyIdRef.current !== null) {
            const idx = newEnemies.findIndex(e => e.id === activeEnemyIdRef.current);
            if (idx !== -1) {
                const enemy = newEnemies[idx];
                const nextChar = enemy.word[enemy.typed.length];

                if (nextChar === char) {
                    hit = true;
                    const newTyped = enemy.typed + char;
                    newEnemies[idx] = { ...enemy, typed: newTyped };

                    if (newTyped === enemy.word) {
                        kill = true;
                        newEnemies.splice(idx, 1);
                        activeEnemyIdRef.current = null;
                    }
                } else {
                    soundEngine.playError();
                    setMultiplier(1);
                }
            } else {
                activeEnemyIdRef.current = null;
            }
        } else {
            const candidates = newEnemies
                .filter(e => e.word.startsWith(char))
                .sort((a, b) => a.x - b.x);

            if (candidates.length > 0) {
                const target = candidates[0];
                const idx = newEnemies.findIndex(e => e.id === target.id);

                hit = true;
                activeEnemyIdRef.current = target.id;

                const newTyped = char;
                newEnemies[idx] = { ...target, isLocked: true, typed: newTyped };

                if (newTyped === target.word) {
                     kill = true;
                     newEnemies.splice(idx, 1);
                     activeEnemyIdRef.current = null;
                }
            }
        }

        if (hit) soundEngine.playKeypress();
        if (kill) {
            soundEngine.playSuccess();
            setScore(s => s + (10 * multiplier));
            setMultiplier(m => Math.min(m + 1, 10));

            // Handle Wave Progress
            setWaveProgress(current => {
                const next = current + 1;
                if (next >= waveTarget) {
                    setTimeout(advanceWave, 0); // Schedule wave advance
                    return 0; // Reset progress visual immediately (will update target in advanceWave)
                }
                return next;
            });
        }

        return newEnemies;
    });

  }, [multiplier, wave, waveTarget]);

  useEffect(() => {
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleKeyDown]);

  useEffect(() => {
      return () => {
          if (requestRef.current) cancelAnimationFrame(requestRef.current);
      };
  }, []);

  const handleFinish = () => {
     const xp = Math.floor(score / 2);
     onGameOver(score, xp);
  };

  const renderEnemy = (enemy: Enemy) => {
      let icon = '';
      if (isZombie) {
          if (enemy.type === 'TANK') icon = '🧟‍♂️'; // Big Zombie
          else if (enemy.type === 'FAST') icon = '🐕'; // Zombie Dog
          else icon = '🧟'; // Normal Zombie
      } else {
          if (enemy.type === 'TANK') icon = '👻'; // Ghost
          else if (enemy.type === 'FAST') icon = '🕷️'; // Spider
          else icon = '🪰'; // Fly
      }

      const untyped = enemy.word.slice(enemy.typed.length);
      const isLocked = enemy.isLocked;

      return (
          <div 
            key={enemy.id}
            className="absolute flex flex-col items-center transition-transform"
            style={{ 
                left: `${enemy.x}%`, 
                top: `${enemy.y}%`,
                transform: `scale(${isLocked ? 1.2 : 1})`,
                zIndex: isLocked ? 20 : 10
            }}
          >
              <div className={`
                 text-sm font-mono font-bold px-2 py-0.5 rounded-full mb-1 whitespace-nowrap shadow-sm
                 ${isLocked 
                     ? isZombie ? 'bg-red-600 text-white ring-2 ring-white' : 'bg-frog-green text-white ring-2 ring-white'
                     : 'bg-stone-800/80 text-stone-200'
                 }
              `}>
                  <span className="text-white/50">{enemy.typed}</span>
                  <span className="text-white">{untyped}</span>
              </div>
              <div className="text-4xl filter drop-shadow-lg animate-bounce" style={{ animationDuration: `${2/enemy.speed}s` }}>
                  {icon}
              </div>
          </div>
      );
  };

  if (gameState === 'START') {
      return (
          <div className={`w-full max-w-4xl mx-auto h-[500px] rounded-3xl relative overflow-hidden flex flex-col items-center justify-center text-white border-4 shadow-2xl ${BG_CLASS} ${BORDER_CLASS}`}>
              <div className="absolute inset-0 opacity-20 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')]"></div>
              <div className="z-10 text-center space-y-6">
                  <h2 className={`text-5xl font-black tracking-tighter flex items-center gap-4 justify-center ${PRIMARY_COLOR}`}>
                      {isZombie ? <Biohazard className="w-12 h-12" /> : <Skull className="w-12 h-12" />}
                      {isZombie ? 'OUTBREAK Z' : 'SWAMP SURVIVAL'}
                  </h2>
                  <p className="text-stone-400 max-w-md mx-auto text-lg">
                      {isZombie 
                        ? "The horde is coming. Type to shoot. Don't let them get close."
                        : "Defend the pond! Type the words above the enemies to zap them."
                      }
                  </p>

                  <div className="grid grid-cols-3 gap-4 text-sm max-w-lg mx-auto">
                      <div className="bg-stone-800 p-3 rounded-xl border border-stone-700">
                          <div className={PRIMARY_COLOR + " font-bold"}>Lock On</div>
                          <div className="text-stone-500">Type 1st letter</div>
                      </div>
                      <div className="bg-stone-800 p-3 rounded-xl border border-stone-700">
                          <div className="text-orange-500 font-bold">Waves</div>
                          <div className="text-stone-500">Heal on Complete</div>
                      </div>
                      <div className="bg-stone-800 p-3 rounded-xl border border-stone-700">
                          <div className="text-purple-500 font-bold">Combo</div>
                          <div className="text-stone-500">Don't miss</div>
                      </div>
                  </div>

                  <button 
                    onClick={startGame}
                    className={`px-8 py-4 ${isZombie ? 'bg-red-600 hover:bg-red-500' : 'bg-frog-green hover:bg-green-500'} text-white font-black text-xl rounded-full transition-transform hover:scale-105 shadow-lg flex items-center gap-2 mx-auto`}
                  >
                      <Play className="w-6 h-6 fill-current" /> START WAVE 1
                  </button>
                  <button onClick={onExit} className="text-stone-500 hover:text-white text-sm underline decoration-stone-600 underline-offset-4">
                      Return to Menu
                  </button>
              </div>
          </div>
      );
  }

  if (gameState === 'GAMEOVER') {
      return (
          <div className="w-full max-w-4xl mx-auto h-[500px] bg-stone-900 rounded-3xl relative overflow-hidden flex flex-col items-center justify-center text-white border-4 border-red-900 shadow-2xl">
              <div className="z-10 text-center space-y-6 animate-in zoom-in-95 duration-300">
                  <div className="text-red-600 font-black text-6xl tracking-widest mb-2">OVERRUN</div>
                  <div className="text-2xl font-mono mb-4">
                      Reached Wave <span className="text-white font-bold">{wave}</span>
                  </div>
                  <div className="text-3xl font-mono font-black">
                      Final Score: <span className={PRIMARY_COLOR}>{score}</span>
                  </div>
                  <div className="flex gap-4 justify-center mt-8">
                      <button 
                        onClick={startGame}
                        className="px-6 py-3 bg-stone-100 hover:bg-white text-stone-900 font-bold rounded-xl flex items-center gap-2"
                      >
                          <RotateCcw className="w-5 h-5" /> Retry
                      </button>
                      <button 
                        onClick={handleFinish}
                        className={`px-6 py-3 ${isZombie ? 'bg-red-600 hover:bg-red-500' : 'bg-frog-green hover:bg-green-500'} text-white font-bold rounded-xl flex items-center gap-2`}
                      >
                          <Trophy className="w-5 h-5" /> Collect XP
                      </button>
                  </div>
              </div>
          </div>
      );
  }

  return (
    <div className={`w-full max-w-4xl mx-auto h-[500px] rounded-3xl relative overflow-hidden border-4 shadow-inner cursor-crosshair select-none ${BG_CLASS} ${BORDER_CLASS}`}>
        {/* Background Elements */}
        <div className={`absolute inset-0 opacity-10 bg-[radial-gradient(ellipse_at_center,_var(--tw-gradient-stops))] ${isZombie ? 'from-red-900 via-stone-950 to-black' : 'from-frog-green via-stone-900 to-stone-950'}`}></div>
        <div className="absolute bottom-0 w-full h-1/3 bg-gradient-to-t from-black/80 to-transparent pointer-events-none"></div>

        {/* HUD */}
        <div className="absolute top-4 left-4 right-4 flex justify-between items-start z-30">
            <div className="flex flex-col gap-2">
                <div className="flex items-center gap-4">
                    <div className="bg-stone-800/80 backdrop-blur-sm border border-stone-700 px-4 py-2 rounded-xl flex items-center gap-2">
                        <Trophy className="w-4 h-4 text-yellow-500" />
                        <span className="font-mono text-xl font-bold text-white">{score}</span>
                    </div>
                    <div className="bg-stone-800/80 backdrop-blur-sm border border-stone-700 px-4 py-2 rounded-xl flex items-center gap-2">
                        <span className="text-xs font-bold text-stone-400 uppercase tracking-wider">Wave</span>
                        <span className={`font-mono text-xl font-bold ${PRIMARY_COLOR}`}>{wave}</span>
                    </div>
                </div>

                {/* Wave Progress */}
                <div className="w-32 h-2 bg-stone-800 rounded-full overflow-hidden border border-stone-700">
                    <div 
                        className={`h-full transition-all duration-300 ${isZombie ? 'bg-red-600' : 'bg-frog-green'}`}
                        style={{ width: `${(waveProgress / waveTarget) * 100}%` }}
                    ></div>
                </div>
            </div>

            <div className="flex items-center gap-2 bg-stone-800/80 backdrop-blur-sm border border-stone-700 px-3 py-1.5 rounded-full">
                {Array.from({length: 3}).map((_, i) => (
                    <Heart 
                        key={i} 
                        className={`w-5 h-5 ${i < lives ? 'fill-red-500 text-red-500' : 'text-stone-700'}`} 
                    />
                ))}
            </div>

