                  ) : icon}
              </div>
          </div>
      );
  };

  if (gameState === 'START') {
      return (
          <div className={`w-full max-w-4xl mx-auto h-[500px] rounded-3xl relative overflow-hidden flex flex-col items-center justify-center text-white border-4 shadow-2xl ${BG_CLASS} ${BORDER_CLASS}`}>
