```typescript
// components/CosmicDefenseGame.tsx

import React, { useState, useEffect } from 'react';
import { useKeyPress } from '../hooks/useKeyPress';
import { MAX_LIVES, PLAYER_INITIAL_X, PLAYER_Y, PLAYER_SIZE, ENEMY_INITIAL_Y, ENEMY_SPEED, ENEMY_SIZE, MAX_ENEMIES, INITIAL_WPM, MIN_WPM, MAX_WPM, MIN_WORD_LENGTH, MAX_WORD_LENGTH, SCORE_MULTIPLIER, BOMB_HIT_DAMAGE } from '../utils/constants';
import { generateRandomWord, clamp, randomInRange } from '../utils/helpers';
import { getWordDifficulty } from '../utils/difficulty';
import '../styles/CosmicDefenseGame.css';
import { useAppContext } from '../context/AppContext';
import { NotificationType } from '../types/Notification';
import { EnemyType, GameState, Entity } from '../types/GameTypes';
import { wpmCalculator } from '../utils/wpmCalculator';

const BOSS_WORD = "COSMIC";
const BOMB_WORDS = ["tic", "tac", "toe", "boom"];

const CosmicDefenseGame = () => {
  const { handleMiniGameOver, handleQuoteComplete, handleXPGain, testHistory, setTestHistory } = useAppContext();
  const [gameState, setGameState] = useState<GameState>({
    score: 0,
    lives: MAX_LIVES,
    enemies: [],
    level: 1,
    currentWord: generateRandomWord(MIN_WORD_LENGTH, MAX_WORD_LENGTH),
    player: { x: PLAYER_INITIAL_X, y: PLAYER_Y, size: PLAYER_SIZE },
    wpm: INITIAL_WPM,
    lastAttackTime: 0,
  });
  const [gameOver, setGameOver] = useState(false);
  const [gameStarted, setGameStarted] = useState(false);
  const [typing, setTyping] = useState<string>('');
  const [notification, setNotification] = useState<{message: string, type: NotificationType} | null>(null);

