      readAheadLevel: initialReadAhead, 
      sfxEnabled: true,
      mechanicalSoundEnabled: parsed.mechanicalSoundEnabled ?? false,
      mechanicalSoundPreset: parsed.mechanicalSoundPreset || 'THOCK',
